window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["四字熟語"]={
"_note": "07. 四字熟語 — mỗi mục một dòng. LEVEL: p1 → p3 = 3 nhóm của chuyên đề (giữ nguyên nhãn gốc). THỨ TỰ: các nhóm xếp p1, p2, p3, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, hanviet, note (tuỳ chọn), chars, poem (tuỳ chọn), example, example_reading, example_meaning, examples, level. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: p1 67, p2 67, p3 66; tổng 200 mục.",
"id": "7. 四字熟語",
"title": "四字熟語",
"icon": "🀄",
"category": "ref",
"kind": "proverb",
"vocab": [
{"word":"一石二鳥","reading":"いっせきにちょう","meaning":"một mũi tên trúng hai đích; làm một việc mà đạt được hai lợi ích cùng lúc.\n(Tối ưu hóa nỗ lực để đạt hiệu quả cao nhất trong hành động.)","hanviet":"nhất thạch nhị điểu","note":"Gốc từ tục ngữ Anh «kill two birds with one stone», người Nhật dịch lại chứ không phải điển Hán văn.","chars":[{"c":"一","h":"nhất"},{"c":"石","h":"thạch"},{"c":"二","h":"nhị"},{"c":"鳥","h":"điểu"}],"poem":{"han":"一石投波驚雙羽／半力收功倍有餘","hv":"Nhất thạch đầu ba kinh song vũ / Bán lực thu công bội hữu dư","vi":"Một viên đá ném xuống làm hai cánh chim giật mình; nửa sức mà công gấp đôi còn dư."},"example":"通勤中に勉強できて、一石二鳥だ。","example_reading":"つうきんちゅうにべんきょうできて、いっせきにちょうだ。","example_meaning":"Học được ngay lúc đi làm, một công đôi việc.","examples":[{"example":"通勤中に勉強できて、一石二鳥だ。","example_reading":"つうきんちゅうにべんきょうできて、いっせきにちょうだ。","example_meaning":"Học được ngay lúc đi làm, một công đôi việc."},{"example":"歩いて通えば運動にも節約にもなる。まさに一石二鳥だ。","example_reading":"あるいてかよえばうんどうにもせつやくにもなる。まさにいっせきにちょうだ。","example_meaning":"Đi bộ đến vừa tập thể dục vừa tiết kiệm, đúng là một công đôi việc."}],"level":"p1"},
{"word":"十人十色","reading":"じゅうにんといろ","meaning":"mỗi người một vẻ, mười người mười màu sắc.\n(Mỗi cá nhân đều có tính cách, sở thích và lối sống riêng biệt; đại diện cho sự đa dạng và cá tính.)","hanviet":"thập nhân thập sắc","note":"Tinh thần giống câu «人心之不同，如其面焉» trong Tả truyện: lòng người khác nhau như khuôn mặt.","chars":[{"c":"十","h":"thập"},{"c":"人","h":"nhân"},{"c":"十","h":"thập"},{"c":"色","h":"sắc"}],"poem":{"han":"千面千心各異色／一林百鳥自殊音","hv":"Thiên diện thiên tâm các dị sắc / Nhất lâm bách điểu tự thù âm","vi":"Nghìn mặt nghìn lòng mỗi người một sắc, một rừng trăm chim mỗi con một giọng."},"example":"好みは十人十色だから、無理に合わせなくていい。","example_reading":"このみはじゅうにんといろだから、むりにあわせなくていい。","example_meaning":"Sở thích mỗi người một khác, không cần ép hợp nhau.","examples":[{"example":"好みは十人十色だから、無理に合わせなくていい。","example_reading":"このみはじゅうにんといろだから、むりにあわせなくていい。","example_meaning":"Sở thích mỗi người một khác, không cần ép hợp nhau."},{"example":"同じ授業を受けても、感じ方は十人十色だ。","example_reading":"おなじじゅぎょうをうけても、かんじかたはじゅうにんといろだ。","example_meaning":"Cùng học một tiết mà cảm nhận mỗi người một khác."}],"level":"p1"},
{"word":"以心伝心","reading":"いしんでんしん","meaning":"thấu hiểu nhau mà không cần dùng lời nói; tâm linh tương thông.\n(Sự kết nối sâu sắc giữa hai tâm hồn khi chỉ cần ánh mắt hay cử chỉ là hiểu thấu.)","hanviet":"dĩ tâm truyền tâm","note":"Gốc nhà Thiền: Phật cầm hoa, Ca-diếp mỉm cười (拈華微笑), đạo truyền từ tâm sang tâm, không qua văn tự.","chars":[{"c":"以","h":"dĩ"},{"c":"心","h":"tâm"},{"c":"伝","h":"truyền"},{"c":"心","h":"tâm"}],"poem":{"han":"拈花一笑無言契／心印相傳萬古情","hv":"Niêm hoa nhất tiếu vô ngôn khế / Tâm ấn tương truyền vạn cổ tình","vi":"Cầm hoa mỉm cười, khế hợp không cần lời; tâm ấn trao nhau, tình xưa vẫn đó."},"example":"長年の友達とは、以心伝心で話が通じる。","example_reading":"ながねんのともだちとは、いしんでんしんではなしがつうじる。","example_meaning":"Với bạn lâu năm, không cần nói cũng hiểu nhau.","examples":[{"example":"長年の友達とは、以心伝心で話が通じる。","example_reading":"ながねんのともだちとは、いしんでんしんではなしがつうじる。","example_meaning":"Với bạn lâu năm, không cần nói cũng hiểu nhau."},{"example":"長年連れ添った夫婦は、以心伝心で気持ちが分かる。","example_reading":"ながねんつれそったふうふは、いしんでんしんできもちがわかる。","example_meaning":"Vợ chồng sống lâu năm không cần nói cũng hiểu lòng nhau."}],"level":"p1"},
{"word":"自業自得","reading":"じごうじとく","meaning":"gieo nhân nào gặp quả nấy; tự làm tự chịu.\n(Nhắc nhở về quy luật nhân quả, mọi hành động cá nhân đều dẫn đến kết quả tương ứng.)","hanviet":"tự nghiệp tự đắc","note":"Thuật ngữ Phật giáo: nghiệp mình gây, quả mình nhận. Chỉ dùng cho kết quả xấu do chính mình.","chars":[{"c":"自","h":"tự"},{"c":"業","h":"nghiệp"},{"c":"自","h":"tự"},{"c":"得","h":"đắc"}],"poem":{"han":"種瓜得瓜種豆豆／苦果由來是己栽","hv":"Chủng qua đắc qua chủng đậu đậu / Khổ quả do lai thị kỷ tài","vi":"Trồng dưa được dưa, trồng đậu được đậu; quả đắng xưa nay do tay mình gieo."},"example":"勉強しなかったのだから、不合格は自業自得だ。","example_reading":"べんきょうしなかったのだから、ふごうかくはじごうじとくだ。","example_meaning":"Không học nên trượt là tự mình chuốc lấy.","examples":[{"example":"勉強しなかったのだから、不合格は自業自得だ。","example_reading":"べんきょうしなかったのだから、ふごうかくはじごうじとくだ。","example_meaning":"Không học nên trượt là tự mình chuốc lấy."},{"example":"夜更かしして遅刻したのは自業自得だ。","example_reading":"よふかししてちこくしたのはじごうじとくだ。","example_meaning":"Thức khuya rồi đi muộn thì đúng là tự làm tự chịu."}],"level":"p1"},
{"word":"臨機応変","reading":"りんきおうへん","meaning":"linh hoạt thích ứng theo từng hoàn cảnh và tình huống cụ thể.\n(Khả năng nhạy bén, không rập khuôn máy móc để xử lý tốt mọi biến động.)","hanviet":"lâm cơ ứng biến","note":"臨機 = đứng trước thời cơ, 応変 = ứng theo biến đổi. Như người lái thuyền xoay buồm theo gió.","chars":[{"c":"臨","h":"lâm"},{"c":"機","h":"cơ"},{"c":"応","h":"ứng"},{"c":"変","h":"biến"}],"poem":{"han":"隨風轉舵因時變／見水行舟順勢移","hv":"Tùy phong chuyển đà nhân thời biến / Kiến thủy hành chu thuận thế di","vi":"Theo gió xoay lái, nhân thời mà biến; thấy nước đưa thuyền, thuận thế mà dời."},"example":"お客様に合わせて、臨機応変に対応します。","example_reading":"おきゃくさまにあわせて、りんきおうへんにたいおうします。","example_meaning":"Tôi sẽ linh hoạt xử lý theo từng khách.","examples":[{"example":"お客様に合わせて、臨機応変に対応します。","example_reading":"おきゃくさまにあわせて、りんきおうへんにたいおうします。","example_meaning":"Tôi sẽ linh hoạt xử lý theo từng khách."},{"example":"天気が悪くなったので、臨機応変に予定を変えた。","example_reading":"てんきがわるくなったので、りんきおうへんによていをかえた。","example_meaning":"Trời xấu đi nên tôi linh hoạt đổi kế hoạch."}],"level":"p1"},
{"word":"一生懸命","reading":"いっしょうけんめい","meaning":"dốc hết sức mình, nỗ lực hết tâm trí cho một mục tiêu.\n(Tinh thần kiên định, cống hiến trọn vẹn sức lực mà không ngần ngại khó khăn.)","hanviet":"nhất sinh huyền mệnh","note":"Gốc là 一所懸命: võ sĩ liều mạng giữ một mảnh đất được chủ ban, sau đổi thành 一生 (cả đời).","chars":[{"c":"一","h":"nhất"},{"c":"生","h":"sinh"},{"c":"懸","h":"huyền"},{"c":"命","h":"mệnh"}],"poem":{"han":"一寸丹心燃到曉／千山萬水不辭勞","hv":"Nhất thốn đan tâm nhiên đáo hiểu / Thiên san vạn thủy bất từ lao","vi":"Tấc lòng son cháy đến sáng, nghìn núi vạn sông chẳng quản nhọc."},"example":"一生懸命がんばりますので、よろしくお願いします。","example_reading":"いっしょうけんめいがんばりますので、よろしくおねがいします。","example_meaning":"Tôi sẽ cố gắng hết sức, mong được giúp đỡ.","examples":[{"example":"一生懸命がんばりますので、よろしくお願いします。","example_reading":"いっしょうけんめいがんばりますので、よろしくおねがいします。","example_meaning":"Tôi sẽ cố gắng hết sức, mong được giúp đỡ."},{"example":"試験に合格するため、一生懸命に勉強している。","example_reading":"しけんにごうかくするため、いっしょうけんめいにべんきょうしている。","example_meaning":"Tôi đang học hết sức để đỗ kỳ thi."}],"level":"p1"},
{"word":"四苦八苦","reading":"しくはっく","meaning":"thập toàn gian khổ, vật lộn khó khăn muôn vàn.\n(Trải qua nhiều vất vả, cay đắng trong cuộc sống nhưng vẫn phải đối mặt để vượt qua.)","hanviet":"tứ khổ bát khổ","note":"Từ Phật giáo: 四苦 = sinh, lão, bệnh, tử; thêm 愛別離苦, 怨憎会苦, 求不得苦, 五蘊盛苦 thành 八苦.","chars":[{"c":"四","h":"tứ"},{"c":"苦","h":"khổ"},{"c":"八","h":"bát"},{"c":"苦","h":"khổ"}],"poem":{"han":"生老病終皆是苦／愛離怨會幾時休","hv":"Sinh lão bệnh chung giai thị khổ / Ái ly oán hội kỷ thời hưu","vi":"Sinh già bệnh chết đều là khổ, thương xa oán gặp biết bao giờ thôi."},"example":"新しい仕事に慣れるまで、四苦八苦した。","example_reading":"あたらしいしごとになれるまで、しくはっくした。","example_meaning":"Tôi đã vất vả mãi mới quen việc mới.","examples":[{"example":"新しい仕事に慣れるまで、四苦八苦した。","example_reading":"あたらしいしごとになれるまで、しくはっくした。","example_meaning":"Tôi đã vất vả mãi mới quen việc mới."},{"example":"引っ越しの準備で、四苦八苦している。","example_reading":"ひっこしのじゅんびで、しくはっくしている。","example_meaning":"Tôi đang vật lộn với việc chuẩn bị chuyển nhà."}],"level":"p1"},
{"word":"日進月歩","reading":"にっしんげっぽ","meaning":"tiến bộ từng ngày từng giờ, phát triển nhanh chóng vượt bậc.\n(Sự đổi mới, tăng trưởng không ngừng nghỉ của xã hội, công nghệ hay bản thân.)","hanviet":"nhật tiến nguyệt bộ","note":"Mỗi ngày một bước, mỗi tháng một dặm. Gần với «日就月將» trong Kinh Thi. Dùng cho kỹ thuật, khoa học.","chars":[{"c":"日","h":"nhật"},{"c":"進","h":"tiến"},{"c":"月","h":"nguyệt"},{"c":"歩","h":"bộ"}],"poem":{"han":"旭日東昇天漸遠／新月西移步更長","hv":"Húc nhật đông thăng thiên tiệm viễn / Tân nguyệt tây di bộ cánh trường","vi":"Mặt trời sớm lên, trời càng xa rộng; trăng non dời bước, đường càng dài thêm."},"example":"科学技術は日進月歩で発展している。","example_reading":"かがくぎじゅつはにっしんげっぽではってんしている。","example_meaning":"Khoa học kỹ thuật phát triển từng ngày.","examples":[{"example":"科学技術は日進月歩で発展している。","example_reading":"かがくぎじゅつはにっしんげっぽではってんしている。","example_meaning":"Khoa học kỹ thuật phát triển từng ngày."},{"example":"スマートフォンの性能は日進月歩だ。","example_reading":"スマートフォンのせいのうはにっしんげっぽだ。","example_meaning":"Hiệu năng điện thoại thông minh tiến bộ từng ngày."}],"level":"p1"},
{"word":"試行錯誤","reading":"しこうさくご","meaning":"vừa làm vừa rút kinh nghiệm; học từ những thất bại.\n(Quá trình thử nghiệm và sửa sai liên tục để tìm ra giải pháp đúng đắn nhất.)","hanviet":"thí hành thác ngộ","note":"Là chữ dịch của «trial and error». 試行 = thử, 錯誤 = sai. Sai thì sửa, thử mãi sẽ ra đường.","chars":[{"c":"試","h":"thí"},{"c":"行","h":"hành"},{"c":"錯","h":"thác"},{"c":"誤","h":"ngộ"}],"poem":{"han":"九折羊腸千度試／一朝破霧見天開","hv":"Cửu chiết dương trường thiên độ thí / Nhất triêu phá vụ kiến thiên khai","vi":"Đường ruột dê chín khúc thử nghìn lần, một sớm xé sương thấy trời mở."},"example":"試行錯誤しながら、新しい方法を探している。","example_reading":"しこうさくごしながら、あたらしいほうほうをさがしている。","example_meaning":"Tôi vừa thử vừa sửa để tìm cách mới.","examples":[{"example":"試行錯誤しながら、新しい方法を探している。","example_reading":"しこうさくごしながら、あたらしいほうほうをさがしている。","example_meaning":"Tôi vừa thử vừa sửa để tìm cách mới."},{"example":"試行錯誤を重ねて、ようやくおいしいパンが焼けた。","example_reading":"しこうさくごをかさねて、ようやくおいしいパンがやけた。","example_meaning":"Sau nhiều lần thử và sai, cuối cùng tôi nướng được bánh ngon."}],"level":"p1"},
{"word":"無我夢中","reading":"むがむちゅう","meaning":"mải mê, đắm chìm hoàn toàn vào một việc đến mức quên cả bản thân.\n(Trạng thái tập trung tuyệt đối và say mê mãnh liệt đối với công việc hay đam mê.)","hanviet":"vô ngã mộng trung","note":"無我 (vô ngã) là khái niệm Phật giáo: quên mất cái «tôi». 夢中 = như đang trong mộng.","chars":[{"c":"無","h":"vô"},{"c":"我","h":"ngã"},{"c":"夢","h":"mộng"},{"c":"中","h":"trung"}],"poem":{"han":"忘身忘我如痴夢／萬籟俱沉一念專","hv":"Vong thân vong ngã như si mộng / Vạn lại câu trầm nhất niệm chuyên","vi":"Quên thân quên ta như mộng dại, muôn tiếng lặng chìm chỉ còn một niệm."},"example":"無我夢中で走って、電車に間に合った。","example_reading":"むがむちゅうではしって、でんしゃにまにあった。","example_meaning":"Tôi chạy hết sức nên kịp chuyến tàu.","examples":[{"example":"無我夢中で走って、電車に間に合った。","example_reading":"むがむちゅうではしって、でんしゃにまにあった。","example_meaning":"Tôi chạy hết sức nên kịp chuyến tàu."},{"example":"無我夢中でゲームをしていて、時間を忘れた。","example_reading":"むがむちゅうでゲームをしていて、じかんをわすれた。","example_meaning":"Mải mê chơi game đến quên cả thời gian."}],"level":"p1"},
{"word":"危機一髪","reading":"ききいっぱつ","meaning":"ngàn cân treo sợi tóc; tình thế nguy cấp trong gang tấc.\n(Khoảnh khắc mong mỏng giữa ranh giới an toàn và hiểm nguy.)","hanviet":"nguy cơ nhất phát","note":"Gợi câu Hàn Dũ «危如一髮引千鈞»: nguy như sợi tóc kéo nghìn cân. 一髪 = chỉ cách một sợi tóc.","chars":[{"c":"危","h":"nguy"},{"c":"機","h":"cơ"},{"c":"一","h":"nhất"},{"c":"髪","h":"phát"}],"poem":{"han":"千鈞繫髮懸崖畔／一線偷生墜露間","hv":"Thiên quân hệ phát huyền nhai bạn / Nhất tuyến thâu sinh trụy lộ gian","vi":"Nghìn cân buộc sợi tóc bên vách đá, một tia sống sót giữa giọt sương rơi."},"example":"車にひかれそうになったが、危機一髪で助かった。","example_reading":"くるまにひかれそうになったが、ききいっぱつでたすかった。","example_meaning":"Suýt bị xe tông nhưng thoát trong gang tấc.","examples":[{"example":"車にひかれそうになったが、危機一髪で助かった。","example_reading":"くるまにひかれそうになったが、ききいっぱつでたすかった。","example_meaning":"Suýt bị xe tông nhưng thoát trong gang tấc."},{"example":"信号無視の車をよけて、危機一髪で助かった。","example_reading":"しんごうむしのくるまをよけて、ききいっぱつでたすかった。","example_meaning":"Né chiếc xe vượt đèn đỏ, tôi thoát trong gang tấc."}],"level":"p1"},
{"word":"八方美人","reading":"はっぽうびじん","meaning":"người khéo léo lấy lòng tất cả mọi người; người tròn trĩnh, dễ mến với ai cũng tốt.\n(Vừa mang ý nghĩa giao tiếp khéo léo, vừa mang thái độ ba phải, thiếu cá tính riêng.)","hanviet":"bát phương mỹ nhân","note":"八方 = tám phương, 美人 = ai cũng khen đẹp. Muốn vừa lòng mọi người nên không dám có chính kiến. Hơi chê. Thường mang nghĩa hơi tiêu cực: người không có chính kiến, chỉ muốn được lòng mọi người.","chars":[{"c":"八","h":"bát"},{"c":"方","h":"phương"},{"c":"美","h":"mỹ"},{"c":"人","h":"nhân"}],"poem":{"han":"八面玲瓏皆笑臉／一心無主任東西","hv":"Bát diện linh lung giai tiếu kiểm / Nhất tâm vô chủ nhậm đông tây","vi":"Tám mặt khéo léo ai cũng mặt cười, một lòng không chủ mặc đông tây."},"example":"彼は八方美人で、誰にでもいい顔をする。","example_reading":"かれははっぽうびじんで、だれにでもいいかおをする。","example_meaning":"Anh ta lấy lòng tất cả, ai cũng đối xử tử tế.","examples":[{"example":"彼は八方美人で、誰にでもいい顔をする。","example_reading":"かれははっぽうびじんで、だれにでもいいかおをする。","example_meaning":"Anh ta lấy lòng tất cả, ai cũng đối xử tử tế."},{"example":"八方美人な彼は、誰からも嫌われないが、本音が見えない。","example_reading":"はっぽうびじんなかれは、だれからもきらわれないが、ほんねがみえない。","example_meaning":"Anh ta khéo lòng mọi người nên không ai ghét, nhưng chẳng ai thấy tâm ý thật."}],"level":"p1"},
{"word":"十中八九","reading":"じっちゅうはっく","meaning":"mười phần thì nắm chắc tám chín phần; khả năng xảy ra cực kỳ cao.\n(Sự dự đoán có cơ sở vững chắc, gần như chắc chắn sẽ xảy ra.)","hanviet":"thập trung bát cửu","note":"Mười thì trúng tám chín: gần như chắc chắn. Dùng để đoán.","chars":[{"c":"十","h":"thập"},{"c":"中","h":"trung"},{"c":"八","h":"bát"},{"c":"九","h":"cửu"}],"poem":{"han":"十有八九天將雨／一心七分已先知","hv":"Thập hữu bát cửu thiên tương vũ / Nhất tâm thất phân dĩ tiên tri","vi":"Mười phần tám chín trời sắp mưa, lòng đã biết trước bảy phần rồi."},"example":"この雲なら、十中八九、雨が降るだろう。","example_reading":"このくもなら、じっちゅうはっく、あめがふるだろう。","example_meaning":"Mây thế này thì tám chín phần là mưa.","examples":[{"example":"この雲なら、十中八九、雨が降るだろう。","example_reading":"このくもなら、じっちゅうはっく、あめがふるだろう。","example_meaning":"Mây thế này thì tám chín phần là mưa."},{"example":"彼が犯人なのは十中八九間違いない。","example_reading":"かれがはんにんなのはじっちゅうはっくまちがいない。","example_meaning":"Anh ta là thủ phạm thì gần như chắc."}],"level":"p1"},
{"word":"心機一転","reading":"しんきいってん","meaning":"thay đổi tâm thế, làm lại từ đầu với năng lượng mới.\n(Rũ bỏ quá khứ hay tâm lý tiêu cực để bắt đầu một chặng đường tươi sáng hơn.)","hanviet":"tâm cơ nhất chuyển","note":"心機 = lòng dạ, 一転 = đổi hẳn. Hay dùng dịp năm mới, chuyển việc.","chars":[{"c":"心","h":"tâm"},{"c":"機","h":"cơ"},{"c":"一","h":"nhất"},{"c":"転","h":"chuyển"}],"poem":{"han":"舊夢拋殘新曉起／一輪紅日換心胸","hv":"Cựu mộng phao tàn tân hiểu khởi / Nhất luân hồng nhật hoán tâm hung","vi":"Mộng cũ vứt đi, bình minh mới dậy, vầng hồng đổi lòng."},"example":"心機一転、新しい職場で頑張ります。","example_reading":"しんきいってん、あたらしいしょくばでがんばります。","example_meaning":"Đổi tâm thế, tôi sẽ cố gắng ở nơi làm mới.","examples":[{"example":"心機一転、新しい職場で頑張ります。","example_reading":"しんきいってん、あたらしいしょくばでがんばります。","example_meaning":"Đổi tâm thế, tôi sẽ cố gắng ở nơi làm mới."},{"example":"失敗のあと、心機一転して勉強を始めた。","example_reading":"しっぱいのあと、しんきいってんしてべんきょうをはじめた。","example_meaning":"Sau thất bại, tôi làm lại từ đầu và bắt đầu học."}],"level":"p1"},
{"word":"古今東西","reading":"ここんとうざい","meaning":"từ xưa đến nay, từ đông sang tây; khắp mọi nơi và mọi thời đại.\n(Chỉ tính bao quát rộng lớn vượt không gian và thời gian.)","hanviet":"cổ kim đông tây","note":"Cổ kim = thời gian, đông tây = không gian. Chỉ sự phổ biến.","chars":[{"c":"古","h":"cổ"},{"c":"今","h":"kim"},{"c":"東","h":"đông"},{"c":"西","h":"tây"}],"poem":{"han":"古往今來東復西／人情萬里一般同","hv":"Cổ vãng kim lai đông phục tây / Nhân tình vạn lý nhất ban đồng","vi":"Xưa qua nay lại, đông rồi tây, tình người muôn dặm vẫn giống nhau."},"example":"古今東西、親が子を思う気持ちは変わらない。","example_reading":"ここんとうざい、おやがこをおもうきもちはかわらない。","example_meaning":"Xưa nay đâu đâu, lòng cha mẹ thương con vẫn vậy.","examples":[{"example":"古今東西、親が子を思う気持ちは変わらない。","example_reading":"ここんとうざい、おやがこをおもうきもちはかわらない。","example_meaning":"Xưa nay đâu đâu, lòng cha mẹ thương con vẫn vậy."},{"example":"古今東西の名作を読み比べる。","example_reading":"ここんとうざいのめいさくをよみくらべる。","example_meaning":"Đọc so sánh các kiệt tác khắp xưa nay."}],"level":"p1"},
{"word":"天下一品","reading":"てんかいっぴん","meaning":"món đồ/tác phẩm độc nhất vô nhị, tuyệt hảo không gì so sánh được dưới bầu trời.\n(Sự hoàn hảo, xuất sắc đạt đến đỉnh cao tuyệt đối.)","hanviet":"thiên hạ nhất phẩm","note":"Một món hạng nhất cả thiên hạ. Hay khen món ăn, tay nghề.","chars":[{"c":"天","h":"thiên"},{"c":"下","h":"hạ"},{"c":"一","h":"nhất"},{"c":"品","h":"phẩm"}],"poem":{"han":"四海尋遍無雙味／一品當筵壓百珍","hv":"Tứ hải tầm biến vô song vị / Nhất phẩm đương diên áp bách trân","vi":"Khắp bốn biển tìm chẳng có vị thứ hai, một món trên tiệc át trăm của quý."},"example":"この店のラーメンは天下一品だ。","example_reading":"このみせのラーメンはてんかいっぴんだ。","example_meaning":"Mì ramen quán này là nhất thiên hạ.","examples":[{"example":"この店のラーメンは天下一品だ。","example_reading":"このみせのラーメンはてんかいっぴんだ。","example_meaning":"Mì ramen quán này là nhất thiên hạ."},{"example":"祖母の漬物は天下一品の味だ。","example_reading":"そぼのつけものはてんかいっぴんのあじだ。","example_meaning":"Dưa muối của bà có vị tuyệt hảo."}],"level":"p1"},
{"word":"自給自足","reading":"じきゅうじそく","meaning":"tự cung tự cấp, tự làm ra những gì mình cần mà không phụ thuộc bên ngoài.\n(Lối sống độc lập, tự chủ và không dựa dẫm.)","hanviet":"tự cấp tự túc","note":"自 = tự, 給 = cấp, 足 = đủ. Lối sống tự lo ăn dùng.","chars":[{"c":"自","h":"tự"},{"c":"給","h":"cấp"},{"c":"自","h":"tự"},{"c":"足","h":"túc"}],"poem":{"han":"自耕自織無求處／一飯一衣皆己躬","hv":"Tự canh tự chức vô cầu xứ / Nhất phạn nhất y giai kỷ cung","vi":"Tự cày tự dệt chẳng cầu ai, bát cơm tấm áo đều do mình làm."},"example":"田舎で自給自足の生活を始めた。","example_reading":"いなかでじきゅうじそくのせいかつをはじめた。","example_meaning":"Tôi bắt đầu cuộc sống tự cung tự cấp ở quê.","examples":[{"example":"田舎で自給自足の生活を始めた。","example_reading":"いなかでじきゅうじそくのせいかつをはじめた。","example_meaning":"Tôi bắt đầu cuộc sống tự cung tự cấp ở quê."},{"example":"食料の自給自足は難しい。","example_reading":"しょくりょうのじきゅうじそくはむずかしい。","example_meaning":"Tự cung tự cấp lương thực là việc khó."}],"level":"p1"},
{"word":"東奔西走","reading":"とうほんせいそう","meaning":"bôn ba khắp nơi, chạy ngược chạy xuôi để lo liệu công việc.\n(Sự bận rộn, vất vả dốc sức di chuyển và làm việc vì mục tiêu nào đó.)","hanviet":"đông bôn tây tẩu","note":"奔 và 走 đều là chạy. Chạy đông chạy tây vì một việc.","chars":[{"c":"東","h":"đông"},{"c":"奔","h":"bôn"},{"c":"西","h":"tây"},{"c":"走","h":"tẩu"}],"poem":{"han":"東馳西驟因何事／汗透征衫不得閒","hv":"Đông trì tây sậu nhân hà sự / Hãn thấu chinh sam bất đắc nhàn","vi":"Chạy đông chạy tây vì việc gì, mồ hôi thấm áo chẳng lúc nhàn."},"example":"資金集めのため、東奔西走している。","example_reading":"しきんあつめのため、とうほんせいそうしている。","example_meaning":"Tôi chạy khắp nơi để gom vốn.","examples":[{"example":"資金集めのため、東奔西走している。","example_reading":"しきんあつめのため、とうほんせいそうしている。","example_meaning":"Tôi chạy khắp nơi để gom vốn."},{"example":"社長は取引先を東奔西走した。","example_reading":"しゃちょうはとりひきさきをとうほんせいそうした。","example_meaning":"Giám đốc chạy khắp nơi gặp đối tác."}],"level":"p1"},
{"word":"千差万別","reading":"せんさばんべつ","meaning":"muôn hình muôn vẻ, vô vàn sự khác biệt đa dạng.\n(Mỗi sự vật, sự việc đều có những đặc điểm riêng biệt không giống nhau.)","hanviet":"thiên sai vạn biệt","note":"差 = khác, 別 = riêng. Nghìn khác, vạn riêng.","chars":[{"c":"千","h":"thiên"},{"c":"差","h":"sai"},{"c":"万","h":"vạn"},{"c":"別","h":"biệt"}],"poem":{"han":"千山各異形千狀／萬卉爭開色萬般","hv":"Thiên san các dị hình thiên trạng / Vạn hủy tranh khai sắc vạn ban","vi":"Nghìn núi mỗi núi một hình, muôn hoa đua nở muôn màu."},"example":"人の考え方は千差万別だ。","example_reading":"ひとのかんがえかたはせんさばんべつだ。","example_meaning":"Cách nghĩ của mỗi người một khác.","examples":[{"example":"人の考え方は千差万別だ。","example_reading":"ひとのかんがえかたはせんさばんべつだ。","example_meaning":"Cách nghĩ của mỗi người một khác."},{"example":"千差万別の意見が出た。","example_reading":"せんさばんべつのいけんがでた。","example_meaning":"Có đủ muôn kiểu ý kiến được đưa ra."}],"level":"p1"},
{"word":"取捨選択","reading":"しゅしゃせんたく","meaning":"cân nhắc chọn lọc; giữ lại cái tốt, bỏ đi cái không phù hợp.\n(Khả năng tư duy sáng suốt để đưa ra quyết định đúng đắn nhất.)","hanviet":"thủ xả tuyển trạch","note":"取 = lấy, 捨 = bỏ, 選 = chọn, 択 = tuyển. Dùng khi lọc thông tin.","chars":[{"c":"取","h":"thủ"},{"c":"捨","h":"xả"},{"c":"選","h":"tuyển"},{"c":"択","h":"trạch"}],"poem":{"han":"披沙揀金留實物／去蕪存菁取精華","hv":"Phi sa giản kim lưu thực vật / Khứ vu tồn tinh thủ tinh hoa","vi":"Sàng cát nhặt vàng giữ của thật, bỏ cỏ giữ hoa lấy tinh hoa."},"example":"情報を取捨選択して使う。","example_reading":"じょうほうをしゅしゃせんたくしてつかう。","example_meaning":"Tôi lọc thông tin rồi mới dùng.","examples":[{"example":"情報を取捨選択して使う。","example_reading":"じょうほうをしゅしゃせんたくしてつかう。","example_meaning":"Tôi lọc thông tin rồi mới dùng."},{"example":"荷物が多いので取捨選択した。","example_reading":"にもつがおおいのでしゅしゃせんたくした。","example_meaning":"Hành lý nhiều quá nên tôi chọn bỏ bớt."}],"level":"p1"},
{"word":"不言実行","reading":"ふげんじっこう","meaning":"nói ít làm nhiều; âm thầm hành động mà không cần phô trương lời nói.\n(Đề cao giá trị của hành động thực tế hơn là những lời hứa suông.)","hanviet":"bất ngôn thực hành","chars":[{"c":"不","h":"bất"},{"c":"言","h":"ngôn"},{"c":"実","h":"thực"},{"c":"行","h":"hành"}],"example":"彼は不言実行の人だ。","example_reading":"かれはふげんじっこうのひとだ。","example_meaning":"Anh ấy là người làm mà không nói.","examples":[{"example":"彼は不言実行の人だ。","example_reading":"かれはふげんじっこうのひとだ。","example_meaning":"Anh ấy là người làm mà không nói."},{"example":"不言実行で成果を出した。","example_reading":"ふげんじっこうでせいかをだした。","example_meaning":"Làm lặng lẽ mà ra thành quả."}],"level":"p1"},
{"word":"電光石火","reading":"でんこうせっか","meaning":"nhanh như chớp; diễn ra trong chớp mắt với tốc độ cực nhanh.\n(Mô tả phản ứng cực kỳ nhanh nhạy hoặc sự việc diễn ra dồn dập, tức thì.)","hanviet":"điện quang thạch hỏa","chars":[{"c":"電","h":"điện"},{"c":"光","h":"quang"},{"c":"石","h":"thạch"},{"c":"火","h":"hỏa"}],"example":"電光石火の早業で勝った。","example_reading":"でんこうせっかのはやわざでかった。","example_meaning":"Thắng bằng đường đi nhanh như chớp.","examples":[{"example":"電光石火の早業で勝った。","example_reading":"でんこうせっかのはやわざでかった。","example_meaning":"Thắng bằng đường đi nhanh như chớp."},{"example":"電光石火のごとく走り去った。","example_reading":"でんこうせっかのごとくはしりさった。","example_meaning":"Chạy vụt đi nhanh như chớp."}],"level":"p1"},
{"word":"単刀直入","reading":"たんとうちょくにゅう","meaning":"đi thẳng vào vấn đề; không vòng vo Tam Quốc.\n(Phong cách giao tiếp ngắn gọn, rõ ràng và hiệu quả trong công việc.)","hanviet":"đơn đao trực nhập","chars":[{"c":"単","h":"đơn"},{"c":"刀","h":"đao"},{"c":"直","h":"trực"},{"c":"入","h":"nhập"}],"example":"単刀直入に言うと、反対だ。","example_reading":"たんとうちょくにゅうにいうと、はんたいだ。","example_meaning":"Nói thẳng ra, tôi phản đối.","examples":[{"example":"単刀直入に言うと、反対だ。","example_reading":"たんとうちょくにゅうにいうと、はんたいだ。","example_meaning":"Nói thẳng ra, tôi phản đối."},{"example":"単刀直入に質問します。","example_reading":"たんとうちょくにゅうにしつもんします。","example_meaning":"Tôi xin hỏi thẳng."}],"level":"p1"},
{"word":"百発百中","reading":"ひゃっぱつひゃくちゅう","meaning":"trăm phát trăm trúng; đoán đâu trúng đó, làm việc gì cũng thành công tuyệt đối.\n(Sự chính xác hoàn hảo nhờ tài năng, kinh nghiệm hoặc sự chuẩn bị kỹ lưỡng.)","hanviet":"bách phát bách trúng","chars":[{"c":"百","h":"bách"},{"c":"発","h":"phát"},{"c":"百","h":"bách"},{"c":"中","h":"trúng"}],"example":"彼の予想は百発百中だ。","example_reading":"かれのよそうはひゃっぱつひゃくちゅうだ。","example_meaning":"Dự đoán của anh ấy trăm lần trúng cả trăm.","examples":[{"example":"彼の予想は百発百中だ。","example_reading":"かれのよそうはひゃっぱつひゃくちゅうだ。","example_meaning":"Dự đoán của anh ấy trăm lần trúng cả trăm."},{"example":"百発百中の腕前の射手だ。","example_reading":"ひゃっぱつひゃくちゅうのうでまえのしゃしゅだ。","example_meaning":"Một xạ thủ bắn trăm phát trúng trăm."}],"level":"p1"},
{"word":"無病息災","reading":"むびょうそくさい","meaning":"khỏe mạnh không bệnh tật, bình an vô sự trọn vẹn.\n(Ước nguyện giản dị nhưng quý giá nhất về sức khỏe và bình an cho bản thân, gia đình.)","hanviet":"vô bệnh tức tai","chars":[{"c":"無","h":"vô"},{"c":"病","h":"bệnh"},{"c":"息","h":"tức"},{"c":"災","h":"tai"}],"example":"家族の無病息災を祈る。","example_reading":"かぞくのむびょうそくさいをいのる。","example_meaning":"Cầu cho gia đình khỏe mạnh bình an.","examples":[{"example":"家族の無病息災を祈る。","example_reading":"かぞくのむびょうそくさいをいのる。","example_meaning":"Cầu cho gia đình khỏe mạnh bình an."},{"example":"無病息災のお守りを買った。","example_reading":"むびょうそくさいのおまもりをかった。","example_meaning":"Tôi mua bùa cầu khỏe mạnh."}],"level":"p1"},
{"word":"誠心誠意","reading":"せいしんせいい","meaning":"trọn vẹn chân thành, dốc hết lòng thành đối xử với người khác.\n(Phẩm chất cốt lõi trong giao tiếp và xây dựng niềm tin bền vững.)","hanviet":"thành tâm thành ý","chars":[{"c":"誠","h":"thành"},{"c":"心","h":"tâm"},{"c":"誠","h":"thành"},{"c":"意","h":"ý"}],"example":"誠心誠意、お詫びします。","example_reading":"せいしんせいい、おわびします。","example_meaning":"Tôi xin lỗi bằng cả tấm lòng.","examples":[{"example":"誠心誠意、お詫びします。","example_reading":"せいしんせいい、おわびします。","example_meaning":"Tôi xin lỗi bằng cả tấm lòng."},{"example":"誠心誠意、お客様に対応する。","example_reading":"せいしんせいい、おきゃくさまにたいおうする。","example_meaning":"Tiếp khách hết lòng."}],"level":"p1"},
{"word":"適材適所","reading":"てきざいてきしょ","meaning":"giao đúng người đúng việc; đặt nhân tài vào đúng vị trí phát huy năng lực.\n(Nghệ thuật quản lý và sử dụng nguồn lực một cách tối ưu.)","hanviet":"thích tài thích sở","chars":[{"c":"適","h":"thích"},{"c":"材","h":"tài"},{"c":"適","h":"thích"},{"c":"所","h":"sở"}],"example":"適材適所に人を配置する。","example_reading":"てきざいてきしょにひとをはいちする。","example_meaning":"Bố trí người đúng việc.","examples":[{"example":"適材適所に人を配置する。","example_reading":"てきざいてきしょにひとをはいちする。","example_meaning":"Bố trí người đúng việc."},{"example":"適材適所の人事だ。","example_reading":"てきざいてきしょのじんじだ。","example_meaning":"Nhân sự đúng người đúng chỗ."}],"level":"p1"},
{"word":"一所懸命","reading":"いっしょけんめい","meaning":"dốc hết sức lực bảo vệ vùng đất của mình; nỗ lực hết mình cho một mục tiêu.\n(Nguồn gốc của 一生懸命, thể hiện tinh thần trách nhiệm và sự tận tụy.)","hanviet":"nhất sở huyền mệnh","chars":[{"c":"一","h":"nhất"},{"c":"所","h":"sở"},{"c":"懸","h":"huyền"},{"c":"命","h":"mệnh"}],"example":"一所懸命に働いた。","example_reading":"いっしょけんめいにはたらいた。","example_meaning":"Tôi làm việc hết sức.","examples":[{"example":"一所懸命に働いた。","example_reading":"いっしょけんめいにはたらいた。","example_meaning":"Tôi làm việc hết sức."},{"example":"一所懸命の努力が実った。","example_reading":"いっしょけんめいのどりょくがみのった。","example_meaning":"Nỗ lực hết mình đã có kết quả."}],"level":"p1"},
{"word":"有言実行","reading":"ゆうげんじっこう","meaning":"nói được làm được; giữ lời hứa và hoàn thành cam kết của bản thân.\n(Xây dựng uy tín và chữ tín dựa trên sự thống nhất giữa lời nói và việc làm.)","hanviet":"hữu ngôn thực hành","chars":[{"c":"有","h":"hữu"},{"c":"言","h":"ngôn"},{"c":"実","h":"thực"},{"c":"行","h":"hành"}],"example":"有言実行で目標を達成した。","example_reading":"ゆうげんじっこうでもくひょうをたっせいした。","example_meaning":"Nói được làm được, đạt mục tiêu.","examples":[{"example":"有言実行で目標を達成した。","example_reading":"ゆうげんじっこうでもくひょうをたっせいした。","example_meaning":"Nói được làm được, đạt mục tiêu."},{"example":"彼女は有言実行のタイプだ。","example_reading":"かのじょはゆうげんじっこうのタイプだ。","example_meaning":"Cô ấy là kiểu người nói là làm."}],"level":"p1"},
{"word":"臨戦態勢","reading":"りんせんたいせい","meaning":"sẵn sàng chiến đấu; trong trạng thái chuẩn bị đầy đủ đối mặt thử thách.\n(Sự chủ động và tinh thần tập trung cao độ trước những kỳ thi hay dự án lớn.)","hanviet":"lâm chiến thái thế","chars":[{"c":"臨","h":"lâm"},{"c":"戦","h":"chiến"},{"c":"態","h":"thái"},{"c":"勢","h":"thế"}],"example":"臨戦態勢に入った。","example_reading":"りんせんたいせいにはいった。","example_meaning":"Đã vào thế sẵn sàng chiến đấu.","examples":[{"example":"臨戦態勢に入った。","example_reading":"りんせんたいせいにはいった。","example_meaning":"Đã vào thế sẵn sàng chiến đấu."},{"example":"警察は臨戦態勢を取った。","example_reading":"けいさつはりんせんたいせいをとった。","example_meaning":"Cảnh sát vào trạng thái sẵn sàng."}],"level":"p1"},
{"word":"自由自在","reading":"じゆうじざい","meaning":"thoải mái làm theo ý mình, không bị ràng buộc hay hạn chế bởi điều gì.\n(Trạng thái làm chủ hoàn toàn bản thân và kỹ năng đạt đến trình độ điêu luyện.)","hanviet":"tự do tự tại","chars":[{"c":"自","h":"tự"},{"c":"由","h":"do"},{"c":"自","h":"tự"},{"c":"在","h":"tại"}],"example":"自由自在に操る。","example_reading":"じゆうじざいにあやつる。","example_meaning":"Điều khiển thoải mái tự nhiên.","examples":[{"example":"自由自在に操る。","example_reading":"じゆうじざいにあやつる。","example_meaning":"Điều khiển thoải mái tự nhiên."},{"example":"彼は英語を自由自在に使う。","example_reading":"かれはえいごをじゆうじざいにつかう。","example_meaning":"Anh ấy dùng tiếng Anh thoải mái."}],"level":"p1"},
{"word":"一朝一夕","reading":"いっちょういっせき","meaning":"một sớm một chiều; thời gian cực kỳ ngắn ngủi.\n(Nhắc nhở rằng những việc lớn hay thành công bền vững không thể đạt được nhanh chóng trong ngày một ngày hai.)","hanviet":"nhất triêu nhất tịch","chars":[{"c":"一","h":"nhất"},{"c":"朝","h":"triêu"},{"c":"一","h":"nhất"},{"c":"夕","h":"tịch"}],"example":"一朝一夕にはできない。","example_reading":"いっちょういっせきにはできない。","example_meaning":"Không thể làm xong trong một sớm một chiều.","examples":[{"example":"一朝一夕にはできない。","example_reading":"いっちょういっせきにはできない。","example_meaning":"Không thể làm xong trong một sớm một chiều."},{"example":"一朝一夕の努力ではない。","example_reading":"いっちょういっせきのどりょくではない。","example_meaning":"Không phải nỗ lực một sớm một chiều."}],"level":"p1"},
{"word":"大同小異","reading":"だいどうしょうい","meaning":"nhìn chung giống nhau, chỉ khác biệt những chi tiết nhỏ không đáng kể.\n(Khuyên ta nên nhìn vào điểm chung tổng thể thay vì soi xét những khác biệt nhỏ nhặt.)","hanviet":"đại đồng tiểu dị","chars":[{"c":"大","h":"đại"},{"c":"同","h":"đồng"},{"c":"小","h":"tiểu"},{"c":"異","h":"dị"}],"example":"二案は大同小異だ。","example_reading":"にあんはだいどうしょういだ。","example_meaning":"Hai phương án gần như giống nhau.","examples":[{"example":"二案は大同小異だ。","example_reading":"にあんはだいどうしょういだ。","example_meaning":"Hai phương án gần như giống nhau."},{"example":"どれも大同小異の内容だ。","example_reading":"どれもだいどうしょういのないようだ。","example_meaning":"Nội dung cái nào cũng gần giống nhau."}],"level":"p1"},
{"word":"一心同体","reading":"いっしんどうたい","meaning":"đồng lòng nhất trí, gắn kết chặt chẽ như cùng một cơ thể.\n(Biểu tượng của tinh thần đồng đội và sự đoàn kết vững chắc.)","hanviet":"nhất tâm đồng thể","chars":[{"c":"一","h":"nhất"},{"c":"心","h":"tâm"},{"c":"同","h":"đồng"},{"c":"体","h":"thể"}],"example":"二人は一心同体だ。","example_reading":"ふたりはいっしんどうたいだ。","example_meaning":"Hai người như một.","examples":[{"example":"二人は一心同体だ。","example_reading":"ふたりはいっしんどうたいだ。","example_meaning":"Hai người như một."},{"example":"一心同体で戦う。","example_reading":"いっしんどうたいでたたかう。","example_meaning":"Chiến đấu như một."}],"level":"p1"},
{"word":"喜怒哀楽","reading":"きどあいらく","meaning":"vui, giận, buồn, sướng; mọi cung bậc cảm xúc của con người.\n(Dùng khi nói về cảm xúc phong phú hoặc việc bộc lộ/giấu cảm xúc của một người.)","hanviet":"hỷ nộ ai lạc","chars":[{"c":"喜","h":"hỷ"},{"c":"怒","h":"nộ"},{"c":"哀","h":"ai"},{"c":"楽","h":"lạc"}],"example":"彼女は喜怒哀楽がはっきりしていて、一緒にいると楽しい。","example_reading":"かのじょはきどあいらくがはっきりしていて、いっしょにいるとたのしい。","example_meaning":"Cô ấy bộc lộ cảm xúc rất rõ ràng nên ở cùng rất vui.","examples":[{"example":"彼女は喜怒哀楽がはっきりしていて、一緒にいると楽しい。","example_reading":"かのじょはきどあいらくがはっきりしていて、いっしょにいるとたのしい。","example_meaning":"Cô ấy bộc lộ cảm xúc rất rõ ràng nên ở cùng rất vui."},{"example":"彼は喜怒哀楽をあまり顔に出さない人だ。","example_reading":"かれはきどあいらくをあまりかおにださないひとだ。","example_meaning":"Anh ấy là người ít để cảm xúc lộ ra mặt."}],"level":"p1"},
{"word":"老若男女","reading":"ろうにゃくなんにょ","meaning":"già trẻ gái trai; mọi người ở mọi lứa tuổi và giới tính.\n(Dùng để nhấn mạnh sức hấp dẫn hoặc phạm vi áp dụng rộng rãi cho tất cả mọi người.)","hanviet":"lão nhược nam nữ","chars":[{"c":"老","h":"lão"},{"c":"若","h":"nhược"},{"c":"男","h":"nam"},{"c":"女","h":"nữ"}],"example":"このゲームは老若男女を問わず楽しめる。","example_reading":"このげーむはろうにゃくなんにょをとわずたのしめる。","example_meaning":"Trò chơi này ai cũng chơi được, bất kể già trẻ gái trai.","examples":[{"example":"このゲームは老若男女を問わず楽しめる。","example_reading":"このげーむはろうにゃくなんにょをとわずたのしめる。","example_meaning":"Trò chơi này ai cũng chơi được, bất kể già trẻ gái trai."},{"example":"祭りには老若男女が集まって、とてもにぎやかだった。","example_reading":"まつりにはろうにゃくなんにょがあつまって、とてもにぎやかだった。","example_meaning":"Lễ hội có đủ già trẻ gái trai tụ họp nên rất náo nhiệt."}],"level":"p1"},
{"word":"一部始終","reading":"いちぶしじゅう","meaning":"từ đầu đến cuối, toàn bộ diễn biến sự việc.\n(Dùng khi kể lại hoặc chứng kiến trọn vẹn một sự việc từ lúc bắt đầu đến khi kết thúc.)","hanviet":"nhất bộ thủy chung","chars":[{"c":"一","h":"nhất"},{"c":"部","h":"bộ"},{"c":"始","h":"thủy"},{"c":"終","h":"chung"}],"example":"彼は事故の一部始終を警察に話した。","example_reading":"かれはじこのいちぶしじゅうをけいさつにはなした。","example_meaning":"Anh ấy kể với cảnh sát toàn bộ sự việc của vụ tai nạn từ đầu đến cuối.","examples":[{"example":"彼は事故の一部始終を警察に話した。","example_reading":"かれはじこのいちぶしじゅうをけいさつにはなした。","example_meaning":"Anh ấy kể với cảnh sát toàn bộ sự việc của vụ tai nạn từ đầu đến cuối."},{"example":"私は事件の一部始終を見ていた。","example_reading":"わたしはじけんのいちぶしじゅうをみていた。","example_meaning":"Tôi đã chứng kiến toàn bộ vụ việc từ đầu đến cuối."}],"level":"p1"},
{"word":"一目散","reading":"いちもくさん","meaning":"chạy thẳng một mạch, không ngoảnh lại.\n(Dùng khi ai đó lao đi hết tốc lực về một hướng, thường vì sợ hãi hoặc vội vã.)","hanviet":"nhất mục tán","chars":[{"c":"一","h":"nhất"},{"c":"目","h":"mục"},{"c":"散","h":"tán"}],"example":"犬に吠えられて、一目散に逃げた。","example_reading":"いぬにほえられて、いちもくさんににげた。","example_meaning":"Bị chó sủa, tôi chạy một mạch không ngoảnh lại.","examples":[{"example":"犬に吠えられて、一目散に逃げた。","example_reading":"いぬにほえられて、いちもくさんににげた。","example_meaning":"Bị chó sủa, tôi chạy một mạch không ngoảnh lại."},{"example":"授業が終わると、子どもたちは一目散に校庭へ走って行った。","example_reading":"じゅぎょうがおわると、こどもたちはいちもくさんにこうていへはしっていった。","example_meaning":"Hết giờ học, lũ trẻ chạy thẳng ra sân trường."}],"level":"p1"},
{"word":"四方八方","reading":"しほうはっぽう","meaning":"khắp mọi phía, mọi hướng.\n(Nhấn mạnh phạm vi rộng, ở mọi hướng xung quanh.)","hanviet":"tứ phương bát phương","chars":[{"c":"四","h":"tứ"},{"c":"方","h":"phương"},{"c":"八","h":"bát"},{"c":"方","h":"phương"}],"example":"迷子の子どもを四方八方探し回った。","example_reading":"まいごのこどもをしほうはっぽうさがしまわった。","example_meaning":"Chúng tôi tìm đứa trẻ bị lạc khắp mọi hướng.","examples":[{"example":"迷子の子どもを四方八方探し回った。","example_reading":"まいごのこどもをしほうはっぽうさがしまわった。","example_meaning":"Chúng tôi tìm đứa trẻ bị lạc khắp mọi hướng."},{"example":"花火の音が四方八方から聞こえてくる。","example_reading":"はなびのおとがしほうはっぽうからきこえてくる。","example_meaning":"Tiếng pháo hoa vang lên từ khắp mọi phía."}],"level":"p1"},
{"word":"無理難題","reading":"むりなんだい","meaning":"yêu cầu vô lý, đòi hỏi quá đáng khó làm.\n(Dùng khi người khác đưa ra yêu cầu phi lý, không thể đáp ứng.)","hanviet":"vô lý nan đề","chars":[{"c":"無","h":"vô"},{"c":"理","h":"lý"},{"c":"難","h":"nan"},{"c":"題","h":"đề"}],"example":"上司から無理難題を押しつけられて困っている。","example_reading":"じょうしからむりなんだいをおしつけられてこまっている。","example_meaning":"Tôi đang khổ sở vì bị sếp áp đặt những yêu cầu vô lý.","examples":[{"example":"上司から無理難題を押しつけられて困っている。","example_reading":"じょうしからむりなんだいをおしつけられてこまっている。","example_meaning":"Tôi đang khổ sở vì bị sếp áp đặt những yêu cầu vô lý."},{"example":"客の無理難題にも、店員は笑顔で対応した。","example_reading":"きゃくのむりなんだいにも、てんいんはえがおでたいおうした。","example_meaning":"Nhân viên vẫn mỉm cười đáp ứng cả những đòi hỏi vô lý của khách."}],"level":"p1"},
{"word":"勧善懲悪","reading":"かんぜんちょうあく","meaning":"khuyến khích điều thiện, trừng phạt điều ác.\n(Thường dùng để nói về cốt truyện mà người tốt thắng, kẻ xấu bị trừng trị.)","hanviet":"khuyến thiện trừng ác","chars":[{"c":"勧","h":"khuyến"},{"c":"善","h":"thiện"},{"c":"懲","h":"trừng"},{"c":"悪","h":"ác"}],"example":"この時代劇は勧善懲悪の物語だ。","example_reading":"このじだいげきはかんぜんちょうあくのものがたりだ。","example_meaning":"Bộ phim cổ trang này là câu chuyện khuyến thiện trừng ác.","examples":[{"example":"この時代劇は勧善懲悪の物語だ。","example_reading":"このじだいげきはかんぜんちょうあくのものがたりだ。","example_meaning":"Bộ phim cổ trang này là câu chuyện khuyến thiện trừng ác."},{"example":"昔話には勧善懲悪の話が多い。","example_reading":"むかしばなしにはかんぜんちょうあくのはなしがおおい。","example_meaning":"Truyện cổ tích có nhiều câu chuyện khuyến thiện trừng ác."}],"level":"p1"},
{"word":"起承転結","reading":"きしょうてんけつ","meaning":"bố cục bốn phần: mở, tiếp, chuyển, kết.\n(Dùng để nói về cấu trúc của bài văn, câu chuyện hay thơ bốn câu.)","hanviet":"khởi thừa chuyển kết","chars":[{"c":"起","h":"khởi"},{"c":"承","h":"thừa"},{"c":"転","h":"chuyển"},{"c":"結","h":"kết"}],"example":"作文は起承転結を意識して書くといい。","example_reading":"さくぶんはきしょうてんけつをいしきしてかくといい。","example_meaning":"Khi viết văn nên chú ý đến bố cục khởi thừa chuyển kết.","examples":[{"example":"作文は起承転結を意識して書くといい。","example_reading":"さくぶんはきしょうてんけつをいしきしてかくといい。","example_meaning":"Khi viết văn nên chú ý đến bố cục khởi thừa chuyển kết."},{"example":"この漫画は四コマで起承転結がはっきりしている。","example_reading":"このまんがはよんこまできしょうてんけつがはっきりしている。","example_meaning":"Truyện tranh bốn ô này có bố cục mở, tiếp, chuyển, kết rất rõ ràng."}],"level":"p1"},
{"word":"新陳代謝","reading":"しんちんたいしゃ","meaning":"sự trao đổi chất; cái cũ mất đi, cái mới thay thế.\n(Dùng cho cơ thể sinh vật (trao đổi chất) và cả xã hội, tổ chức (thay máu).)","hanviet":"tân trần đại tạ","chars":[{"c":"新","h":"tân"},{"c":"陳","h":"trần"},{"c":"代","h":"đại"},{"c":"謝","h":"tạ"}],"example":"運動をすると新陳代謝が良くなる。","example_reading":"うんどうをするとしんちんたいしゃがよくなる。","example_meaning":"Tập thể dục thì quá trình trao đổi chất tốt hơn.","examples":[{"example":"運動をすると新陳代謝が良くなる。","example_reading":"うんどうをするとしんちんたいしゃがよくなる。","example_meaning":"Tập thể dục thì quá trình trao đổi chất tốt hơn."},{"example":"会社の新陳代謝を進めるために若い人を採用した。","example_reading":"かいしゃのしんちんたいしゃをすすめるためにわかいひとをさいようした。","example_meaning":"Công ty tuyển người trẻ để thúc đẩy sự đổi mới thế hệ."}],"level":"p1"},
{"word":"年中無休","reading":"ねんじゅうむきゅう","meaning":"mở cửa quanh năm, không nghỉ ngày nào.\n(Thường thấy trên biển hiệu cửa hàng, dịch vụ hoạt động mọi ngày trong năm.)","hanviet":"niên trung vô hưu","chars":[{"c":"年","h":"niên"},{"c":"中","h":"trung"},{"c":"無","h":"vô"},{"c":"休","h":"hưu"}],"example":"このコンビニは年中無休で営業している。","example_reading":"このコンビニはねんじゅうむきゅうでえいぎょうしている。","example_meaning":"Cửa hàng tiện lợi này mở cửa quanh năm không nghỉ.","examples":[{"example":"このコンビニは年中無休で営業している。","example_reading":"このコンビニはねんじゅうむきゅうでえいぎょうしている。","example_meaning":"Cửa hàng tiện lợi này mở cửa quanh năm không nghỉ."},{"example":"病院の救急外来は年中無休だ。","example_reading":"びょういんのきゅうきゅうがいらいはねんじゅうむきゅうだ。","example_meaning":"Khoa cấp cứu của bệnh viện hoạt động quanh năm không nghỉ."}],"level":"p1"},
{"word":"前代未聞","reading":"ぜんだいみもん","meaning":"chưa từng nghe thấy từ trước đến nay.\n(Dùng cho sự việc hiếm có, gây sửng sốt, thường là chuyện xấu hoặc kỳ lạ.)","hanviet":"tiền đại vị văn","chars":[{"c":"前","h":"tiền"},{"c":"代","h":"đại"},{"c":"未","h":"vị"},{"c":"聞","h":"văn"}],"example":"社長が突然辞めるとは前代未聞の出来事だ。","example_reading":"しゃちょうがとつぜんやめるとはぜんだいみもんのできごとだ。","example_meaning":"Giám đốc đột ngột từ chức là chuyện chưa từng có.","examples":[{"example":"社長が突然辞めるとは前代未聞の出来事だ。","example_reading":"しゃちょうがとつぜんやめるとはぜんだいみもんのできごとだ。","example_meaning":"Giám đốc đột ngột từ chức là chuyện chưa từng có."},{"example":"前代未聞の大雪で、街の交通は止まった。","example_reading":"ぜんだいみもんのおおゆきで、まちのこうつうはとまった。","example_meaning":"Trận tuyết lớn chưa từng có khiến giao thông thành phố tê liệt."}],"level":"p1"},
{"word":"自信満々","reading":"じしんまんまん","meaning":"tràn đầy tự tin.\n(Dùng khi ai đó thể hiện sự tự tin rất cao qua thái độ, lời nói.)","hanviet":"tự tín mãn mãn","chars":[{"c":"自","h":"tự"},{"c":"信","h":"tín"},{"c":"満","h":"mãn"},{"c":"々","h":"mãn"}],"example":"彼は自信満々で試合に臨んだ。","example_reading":"かれはじしんまんまんでしあいにのぞんだ。","example_meaning":"Anh ấy bước vào trận đấu với đầy tự tin.","examples":[{"example":"彼は自信満々で試合に臨んだ。","example_reading":"かれはじしんまんまんでしあいにのぞんだ。","example_meaning":"Anh ấy bước vào trận đấu với đầy tự tin."},{"example":"自信満々に答えたが、答えは間違っていた。","example_reading":"じしんまんまんにこたえたが、こたえはまちがっていた。","example_meaning":"Tôi trả lời rất tự tin nhưng đáp án lại sai."}],"level":"p1"},
{"word":"一日千秋","reading":"いちじつせんしゅう","meaning":"một ngày dài như nghìn thu; nóng lòng mong đợi.\n(Diễn tả tâm trạng mong ngóng khiến thời gian trôi chậm vô cùng.)","hanviet":"nhất nhật thiên thu","chars":[{"c":"一","h":"nhất"},{"c":"日","h":"nhật"},{"c":"千","h":"thiên"},{"c":"秋","h":"thu"}],"example":"彼女からの返事を一日千秋の思いで待っている。","example_reading":"かのじょからのへんじをいちじつせんしゅうのおもいでまっている。","example_meaning":"Tôi nóng lòng chờ hồi âm của cô ấy.","examples":[{"example":"彼女からの返事を一日千秋の思いで待っている。","example_reading":"かのじょからのへんじをいちじつせんしゅうのおもいでまっている。","example_meaning":"Tôi nóng lòng chờ hồi âm của cô ấy."},{"example":"息子の帰国を一日千秋の思いで待ち望んでいる。","example_reading":"むすこのきこくをいちじつせんしゅうのおもいでまちのぞんでいる。","example_meaning":"Tôi mong ngóng từng ngày để đón con trai về nước."}],"level":"p1"},
{"word":"一網打尽","reading":"いちもうだじん","meaning":"một mẻ lưới bắt gọn toàn bộ.\n(Thường dùng khi cảnh sát bắt gọn cả băng nhóm, hoặc thu hết mọi thứ cùng một lúc.)","hanviet":"nhất võng đả tận","chars":[{"c":"一","h":"nhất"},{"c":"網","h":"võng"},{"c":"打","h":"đả"},{"c":"尽","h":"tận"}],"example":"警察は犯罪グループを一網打尽にした。","example_reading":"けいさつははんざいぐるーぷをいちもうだじんにした。","example_meaning":"Cảnh sát đã bắt gọn cả băng nhóm tội phạm.","examples":[{"example":"警察は犯罪グループを一網打尽にした。","example_reading":"けいさつははんざいぐるーぷをいちもうだじんにした。","example_meaning":"Cảnh sát đã bắt gọn cả băng nhóm tội phạm."},{"example":"この作戦で敵を一網打尽にできるだろう。","example_reading":"このさくせんでてきをいちもうだじんにできるだろう。","example_meaning":"Với kế hoạch này có lẽ sẽ tóm gọn được toàn bộ kẻ địch."}],"level":"p1"},
{"word":"一挙両得","reading":"いっきょりょうとく","meaning":"một việc làm mà được lợi cả hai đường.\n(Gần nghĩa với 一石二鳥, nhấn mạnh làm một việc thu được hai điều lợi.)","hanviet":"nhất cử lưỡng đắc","chars":[{"c":"一","h":"nhất"},{"c":"挙","h":"cử"},{"c":"両","h":"lưỡng"},{"c":"得","h":"đắc"}],"example":"自転車で通勤すれば健康にも節約にもなり、一挙両得だ。","example_reading":"じてんしゃでつうきんすればけんこうにもせつやくにもなり、いっきょりょうとくだ。","example_meaning":"Đi làm bằng xe đạp vừa tốt cho sức khỏe vừa tiết kiệm, một công đôi việc.","examples":[{"example":"自転車で通勤すれば健康にも節約にもなり、一挙両得だ。","example_reading":"じてんしゃでつうきんすればけんこうにもせつやくにもなり、いっきょりょうとくだ。","example_meaning":"Đi làm bằng xe đạp vừa tốt cho sức khỏe vừa tiết kiệm, một công đôi việc."},{"example":"旅行しながら英語を学べば一挙両得だ。","example_reading":"りょこうしながらえいごをまなべばいっきょりょうとくだ。","example_meaning":"Vừa đi du lịch vừa học tiếng Anh thì thật một công đôi việc."}],"level":"p1"},
{"word":"全身全霊","reading":"ぜんしんぜんれい","meaning":"dốc toàn bộ thể xác và tinh thần.\n(Diễn tả sự nỗ lực hết mình, dồn cả sức lực lẫn tâm hồn vào một việc.)","hanviet":"toàn thân toàn linh","chars":[{"c":"全","h":"toàn"},{"c":"身","h":"thân"},{"c":"全","h":"toàn"},{"c":"霊","h":"linh"}],"example":"全身全霊を込めて作品を完成させた。","example_reading":"ぜんしんぜんれいをこめてさくひんをかんせいさせた。","example_meaning":"Tôi đã dốc toàn bộ tâm sức để hoàn thành tác phẩm.","examples":[{"example":"全身全霊を込めて作品を完成させた。","example_reading":"ぜんしんぜんれいをこめてさくひんをかんせいさせた。","example_meaning":"Tôi đã dốc toàn bộ tâm sức để hoàn thành tác phẩm."},{"example":"彼は全身全霊でチームを支えた。","example_reading":"かれはぜんしんぜんれいでちーむをささえた。","example_meaning":"Anh ấy đã dốc hết sức mình để hỗ trợ đội."}],"level":"p1"},
{"word":"理路整然","reading":"りろせいぜん","meaning":"lập luận mạch lạc, logic chặt chẽ.\n(Dùng để khen cách trình bày, lời nói có trình tự hợp lý và dễ hiểu.)","hanviet":"lý lộ chỉnh nhiên","chars":[{"c":"理","h":"lý"},{"c":"路","h":"lộ"},{"c":"整","h":"chỉnh"},{"c":"然","h":"nhiên"}],"example":"彼女は理路整然と意見を述べた。","example_reading":"かのじょはりろせいぜんといけんをのべた。","example_meaning":"Cô ấy trình bày ý kiến một cách mạch lạc, logic.","examples":[{"example":"彼女は理路整然と意見を述べた。","example_reading":"かのじょはりろせいぜんといけんをのべた。","example_meaning":"Cô ấy trình bày ý kiến một cách mạch lạc, logic."},{"example":"理路整然とした説明で、全員が納得した。","example_reading":"りろせいぜんとしたせつめいで、ぜんいんがなっとくした。","example_meaning":"Lời giải thích mạch lạc khiến mọi người đều bị thuyết phục."}],"level":"p1"},
{"word":"品行方正","reading":"ひんこうほうせい","meaning":"phẩm hạnh đoan chính, cư xử đúng mực.\n(Dùng để khen người có đạo đức, hành vi chuẩn mực.)","hanviet":"phẩm hạnh phương chính","chars":[{"c":"品","h":"phẩm"},{"c":"行","h":"hạnh"},{"c":"方","h":"phương"},{"c":"正","h":"chính"}],"example":"彼は品行方正な学生として知られている。","example_reading":"かれはひんこうほうせいながくせいとしてしられている。","example_meaning":"Cậu ấy nổi tiếng là học sinh có phẩm hạnh đoan chính.","examples":[{"example":"彼は品行方正な学生として知られている。","example_reading":"かれはひんこうほうせいながくせいとしてしられている。","example_meaning":"Cậu ấy nổi tiếng là học sinh có phẩm hạnh đoan chính."},{"example":"品行方正な彼が問題を起こすとは思えない。","example_reading":"ひんこうほうせいなかれがもんだいをおこすとはおもえない。","example_meaning":"Tôi không nghĩ một người đoan chính như cậu ấy lại gây chuyện."}],"level":"p1"},
{"word":"天変地異","reading":"てんぺんちい","meaning":"biến động của trời đất như bão, động đất, thiên tai.\n(Chỉ những hiện tượng thiên nhiên bất thường, dữ dội.)","hanviet":"thiên biến địa dị","chars":[{"c":"天","h":"thiên"},{"c":"変","h":"biến"},{"c":"地","h":"địa"},{"c":"異","h":"dị"}],"example":"この地域では天変地異に備えて訓練をしている。","example_reading":"このちいきではてんぺんちいにそなえてくんれんをしている。","example_meaning":"Khu vực này luyện tập để phòng ngừa thiên tai.","examples":[{"example":"この地域では天変地異に備えて訓練をしている。","example_reading":"このちいきではてんぺんちいにそなえてくんれんをしている。","example_meaning":"Khu vực này luyện tập để phòng ngừa thiên tai."},{"example":"昔の人は天変地異を神の怒りだと考えた。","example_reading":"むかしのひとはてんぺんちいをかみのいかりだとかんがえた。","example_meaning":"Người xưa cho rằng thiên tai là cơn giận của thần linh."}],"level":"p1"},
{"word":"自然淘汰","reading":"しぜんとうた","meaning":"chọn lọc tự nhiên; kẻ yếu bị loại bỏ.\n(Thuật ngữ sinh học, cũng dùng nghĩa bóng cho việc doanh nghiệp yếu bị loại khỏi thị trường.)","hanviet":"tự nhiên đào thải","chars":[{"c":"自","h":"tự"},{"c":"然","h":"nhiên"},{"c":"淘","h":"đào"},{"c":"汰","h":"thải"}],"example":"生物は自然淘汰によって進化してきた。","example_reading":"せいぶつはしぜんとうたによってしんかしてきた。","example_meaning":"Sinh vật đã tiến hóa nhờ chọn lọc tự nhiên.","examples":[{"example":"生物は自然淘汰によって進化してきた。","example_reading":"せいぶつはしぜんとうたによってしんかしてきた。","example_meaning":"Sinh vật đã tiến hóa nhờ chọn lọc tự nhiên."},{"example":"競争が激しく、弱い店は自然淘汰されていく。","example_reading":"きょうそうがはげしく、よわいみせはしぜんとうたされていく。","example_meaning":"Cạnh tranh gay gắt nên các cửa hàng yếu dần bị đào thải."}],"level":"p1"},
{"word":"昼夜兼行","reading":"ちゅうやけんこう","meaning":"làm việc cả ngày lẫn đêm không ngừng nghỉ.\n(Dùng khi công việc khẩn cấp phải làm xuyên ngày đêm.)","hanviet":"trú dạ kiêm hành","chars":[{"c":"昼","h":"trú"},{"c":"夜","h":"dạ"},{"c":"兼","h":"kiêm"},{"c":"行","h":"hành"}],"example":"工事は昼夜兼行で進められている。","example_reading":"こうじはちゅうやけんこうですすめられている。","example_meaning":"Công trình đang được thi công cả ngày lẫn đêm.","examples":[{"example":"工事は昼夜兼行で進められている。","example_reading":"こうじはちゅうやけんこうですすめられている。","example_meaning":"Công trình đang được thi công cả ngày lẫn đêm."},{"example":"締め切りに間に合うよう、昼夜兼行で作業した。","example_reading":"しめきりにまにあうよう、ちゅうやけんこうでさぎょうした。","example_meaning":"Để kịp thời hạn, chúng tôi làm việc suốt ngày đêm."}],"level":"p1"},
{"word":"悪戦苦闘","reading":"あくせんくとう","meaning":"chiến đấu vất vả trong hoàn cảnh khó khăn.\n(Dùng khi phải vật lộn, loay hoay khó nhọc với một việc nan giải.)","hanviet":"ác chiến khổ đấu","chars":[{"c":"悪","h":"ác"},{"c":"戦","h":"chiến"},{"c":"苦","h":"khổ"},{"c":"闘","h":"đấu"}],"example":"新しいソフトの使い方に悪戦苦闘している。","example_reading":"あたらしいそふとのつかいかたにあくせんくとうしている。","example_meaning":"Tôi đang vật lộn với cách dùng phần mềm mới.","examples":[{"example":"新しいソフトの使い方に悪戦苦闘している。","example_reading":"あたらしいそふとのつかいかたにあくせんくとうしている。","example_meaning":"Tôi đang vật lộn với cách dùng phần mềm mới."},{"example":"彼は病気と悪戦苦闘しながら仕事を続けた。","example_reading":"かれはびょうきとあくせんくとうしながらしごとをつづけた。","example_meaning":"Anh ấy vừa vật lộn với bệnh tật vừa tiếp tục làm việc."}],"level":"p1"},
{"word":"奇想天外","reading":"きそうてんがい","meaning":"ý tưởng kỳ lạ, vượt ngoài sức tưởng tượng thông thường.\n(Dùng khen hoặc nhận xét những ý tưởng, cốt truyện độc đáo, bất ngờ.)","hanviet":"kỳ tưởng thiên ngoại","chars":[{"c":"奇","h":"kỳ"},{"c":"想","h":"tưởng"},{"c":"天","h":"thiên"},{"c":"外","h":"ngoại"}],"example":"彼の奇想天外な発想にはいつも驚かされる。","example_reading":"かれのきそうてんがいなはっそうにはいつもおどろかされる。","example_meaning":"Tôi luôn ngạc nhiên trước những ý tưởng kỳ lạ của anh ấy.","examples":[{"example":"彼の奇想天外な発想にはいつも驚かされる。","example_reading":"かれのきそうてんがいなはっそうにはいつもおどろかされる。","example_meaning":"Tôi luôn ngạc nhiên trước những ý tưởng kỳ lạ của anh ấy."},{"example":"この映画は奇想天外なストーリーが魅力だ。","example_reading":"このえいがはきそうてんがいなすとーりーがみりょくだ。","example_meaning":"Điểm hấp dẫn của bộ phim này là cốt truyện kỳ lạ, bất ngờ."}],"level":"p1"},
{"word":"支離滅裂","reading":"しりめつれつ","meaning":"rời rạc, lộn xộn, không mạch lạc.\n(Dùng cho lời nói, văn viết hay suy nghĩ thiếu logic, không nhất quán.)","hanviet":"chi ly diệt liệt","chars":[{"c":"支","h":"chi"},{"c":"離","h":"ly"},{"c":"滅","h":"diệt"},{"c":"裂","h":"liệt"}],"example":"酔った彼の話は支離滅裂だった。","example_reading":"よったかれのはなしはしりめつれつだった。","example_meaning":"Lời nói của anh ấy lúc say thật lộn xộn, vô nghĩa.","examples":[{"example":"酔った彼の話は支離滅裂だった。","example_reading":"よったかれのはなしはしりめつれつだった。","example_meaning":"Lời nói của anh ấy lúc say thật lộn xộn, vô nghĩa."},{"example":"この文章は支離滅裂で意味がわからない。","example_reading":"このぶんしょうはしりめつれつでいみがわからない。","example_meaning":"Đoạn văn này rời rạc, không hiểu nổi ý nghĩa."}],"level":"p1"},
{"word":"縦横無尽","reading":"じゅうおうむじん","meaning":"tung hoành ngang dọc, tự do tự tại không giới hạn.\n(Diễn tả sự hoạt động thoải mái, mạnh mẽ ở mọi hướng, không bị cản trở.)","hanviet":"túng hoành vô tận","chars":[{"c":"縦","h":"túng"},{"c":"横","h":"hoành"},{"c":"無","h":"vô"},{"c":"尽","h":"tận"}],"example":"彼はピッチを縦横無尽に駆け回った。","example_reading":"かれはぴっちをじゅうおうむじんにかけまわった。","example_meaning":"Anh ấy chạy tung hoành khắp sân.","examples":[{"example":"彼はピッチを縦横無尽に駆け回った。","example_reading":"かれはぴっちをじゅうおうむじんにかけまわった。","example_meaning":"Anh ấy chạy tung hoành khắp sân."},{"example":"ネットワークが縦横無尽に張り巡らされている。","example_reading":"ねっとわーくがじゅうおうむじんにはりめぐらされている。","example_meaning":"Mạng lưới được giăng ra chằng chịt khắp mọi hướng."}],"level":"p1"},
{"word":"質疑応答","reading":"しつぎおうとう","meaning":"hỏi đáp, phần giải đáp thắc mắc.\n(Dùng trong hội nghị, buổi thuyết trình khi người nghe đặt câu hỏi và người nói trả lời.)","hanviet":"chất nghi ứng đáp","chars":[{"c":"質","h":"chất"},{"c":"疑","h":"nghi"},{"c":"応","h":"ứng"},{"c":"答","h":"đáp"}],"example":"発表のあとに質疑応答の時間がある。","example_reading":"はっぴょうのあとにしつぎおうとうのじかんがある。","example_meaning":"Sau phần thuyết trình có thời gian hỏi đáp.","examples":[{"example":"発表のあとに質疑応答の時間がある。","example_reading":"はっぴょうのあとにしつぎおうとうのじかんがある。","example_meaning":"Sau phần thuyết trình có thời gian hỏi đáp."},{"example":"質疑応答で多くの質問が出た。","example_reading":"しつぎおうとうでおおくのしつもんがでた。","example_meaning":"Trong phần hỏi đáp có rất nhiều câu hỏi được đưa ra."}],"level":"p1"},
{"word":"半信半疑","reading":"はんしんはんぎ","meaning":"nửa tin nửa ngờ.\n(Dùng khi chưa dám tin hoàn toàn, vẫn còn nghi hoặc.)","hanviet":"bán tín bán nghi","chars":[{"c":"半","h":"bán"},{"c":"信","h":"tín"},{"c":"半","h":"bán"},{"c":"疑","h":"nghi"}],"example":"うまい話だと思って、半信半疑で聞いていた。","example_reading":"うまいはなしだとおもって、はんしんはんぎできいていた。","example_meaning":"Tôi nghe mà nửa tin nửa ngờ vì thấy chuyện quá hay.","examples":[{"example":"うまい話だと思って、半信半疑で聞いていた。","example_reading":"うまいはなしだとおもって、はんしんはんぎできいていた。","example_meaning":"Tôi nghe mà nửa tin nửa ngờ vì thấy chuyện quá hay."},{"example":"彼の言葉を半信半疑で受け止めた。","example_reading":"かれのことばをはんしんはんぎでうけとめた。","example_meaning":"Tôi tiếp nhận lời anh ấy với tâm trạng nửa tin nửa ngờ."}],"level":"p1"},
{"word":"美人薄命","reading":"びじんはくめい","meaning":"người đẹp thường có số phận ngắn ngủi, bạc mệnh.\n(Thường dùng khi tiếc thương người tài sắc qua đời sớm; nay cũng dùng đùa.)","hanviet":"mỹ nhân bạc mệnh","chars":[{"c":"美","h":"mỹ"},{"c":"人","h":"nhân"},{"c":"薄","h":"bạc"},{"c":"命","h":"mệnh"}],"example":"美人薄命というが、彼女は若くして亡くなった。","example_reading":"びじんはくめいというが、かのじょはわかくしてなくなった。","example_meaning":"Người ta nói mỹ nhân bạc mệnh, quả thật cô ấy mất khi còn trẻ.","examples":[{"example":"美人薄命というが、彼女は若くして亡くなった。","example_reading":"びじんはくめいというが、かのじょはわかくしてなくなった。","example_meaning":"Người ta nói mỹ nhân bạc mệnh, quả thật cô ấy mất khi còn trẻ."},{"example":"「美人薄命」と言われても、彼女は元気に長生きした。","example_reading":"「びじんはくめい」といわれても、かのじょはげんきにながいきした。","example_meaning":"Dù có câu mỹ nhân bạc mệnh, cô ấy vẫn khỏe mạnh sống thọ."}],"level":"p1"},
{"word":"因果応報","reading":"いんがおうほう","meaning":"nhân nào quả nấy; làm việc gì sẽ nhận quả báo tương ứng.\n(Gốc từ Phật giáo, dùng cho cả báo ứng xấu lẫn tốt, thường nói về điều xấu.)","hanviet":"nhân quả ứng báo","chars":[{"c":"因","h":"nhân"},{"c":"果","h":"quả"},{"c":"応","h":"ứng"},{"c":"報","h":"báo"}],"example":"悪いことをすれば因果応報で自分に返ってくる。","example_reading":"わるいことをすればいんがおうほうでじぶんにかえってくる。","example_meaning":"Làm điều xấu thì nhân quả sẽ quay lại với chính mình.","examples":[{"example":"悪いことをすれば因果応報で自分に返ってくる。","example_reading":"わるいことをすればいんがおうほうでじぶんにかえってくる。","example_meaning":"Làm điều xấu thì nhân quả sẽ quay lại với chính mình."},{"example":"彼の失敗は因果応報というしかない。","example_reading":"かれのしっぱいはいんがおうほうというしかない。","example_meaning":"Thất bại của anh ta chỉ có thể nói là nhân quả báo ứng."}],"level":"p1"},
{"word":"七転八起","reading":"ななころびやおき","meaning":"ngã bảy lần, đứng dậy tám lần; không nản chí.\n(Khuyên không bỏ cuộc dù thất bại nhiều lần; đồng nghĩa 七転び八起き.)","hanviet":"thất chuyển bát khởi","chars":[{"c":"七","h":"thất"},{"c":"転","h":"chuyển"},{"c":"八","h":"bát"},{"c":"起","h":"khởi"}],"example":"七転八起の精神で挑戦を続けよう。","example_reading":"ななころびやおきのせいしんでちょうせんをつづけよう。","example_meaning":"Hãy tiếp tục thử thách với tinh thần ngã bảy lần đứng dậy tám lần.","examples":[{"example":"七転八起の精神で挑戦を続けよう。","example_reading":"ななころびやおきのせいしんでちょうせんをつづけよう。","example_meaning":"Hãy tiếp tục thử thách với tinh thần ngã bảy lần đứng dậy tám lần."},{"example":"彼の人生は七転八起の連続だった。","example_reading":"かれのじんせいはななころびやおきのれんぞくだった。","example_meaning":"Cuộc đời ông ấy là chuỗi những lần ngã xuống rồi đứng dậy."}],"level":"p1"},
{"word":"千客万来","reading":"せんきゃくばんらい","meaning":"khách khứa nườm nượp kéo đến.\n(Thường dùng làm lời chúc cửa hàng đông khách.)","hanviet":"thiên khách vạn lai","chars":[{"c":"千","h":"thiên"},{"c":"客","h":"khách"},{"c":"万","h":"vạn"},{"c":"来","h":"lai"}],"example":"新しい店は千客万来で大忙しだ。","example_reading":"あたらしいみせはせんきゃくばんらいでおおいそがしだ。","example_meaning":"Cửa hàng mới khách đông nườm nượp nên bận tối mắt.","examples":[{"example":"新しい店は千客万来で大忙しだ。","example_reading":"あたらしいみせはせんきゃくばんらいでおおいそがしだ。","example_meaning":"Cửa hàng mới khách đông nườm nượp nên bận tối mắt."},{"example":"開店の日は千客万来を願って花を飾った。","example_reading":"かいてんのひはせんきゃくばんらいをねがってはなをかざった。","example_meaning":"Ngày khai trương, họ trang trí hoa cầu mong khách đông."}],"level":"p1"},
{"word":"商売繁盛","reading":"しょうばいはんじょう","meaning":"làm ăn phát đạt.\n(Thường dùng trong lời chúc hoặc cầu nguyện cho việc kinh doanh.)","hanviet":"thương mại phồn thịnh","chars":[{"c":"商","h":"thương"},{"c":"売","h":"mại"},{"c":"繁","h":"phồn"},{"c":"盛","h":"thịnh"}],"example":"お正月に神社で商売繁盛を祈った。","example_reading":"おしょうがつにじんじゃでしょうばいはんじょうをいのった。","example_meaning":"Dịp Tết tôi cầu nguyện ở đền cho việc làm ăn phát đạt.","examples":[{"example":"お正月に神社で商売繁盛を祈った。","example_reading":"おしょうがつにじんじゃでしょうばいはんじょうをいのった。","example_meaning":"Dịp Tết tôi cầu nguyện ở đền cho việc làm ăn phát đạt."},{"example":"店の入口に商売繁盛の縁起物が飾ってある。","example_reading":"みせのいりぐちにしょうばいはんじょうのえんぎものがかざってある。","example_meaning":"Ở cửa ra vào cửa hàng có đặt vật may mắn cầu làm ăn phát đạt."}],"level":"p1"},
{"word":"家内安全","reading":"かないあんぜん","meaning":"gia đình bình an, mọi người trong nhà khỏe mạnh.\n(Thường dùng trong lời cầu nguyện ở đền chùa cho gia đình.)","hanviet":"gia nội an toàn","chars":[{"c":"家","h":"gia"},{"c":"内","h":"nội"},{"c":"安","h":"an"},{"c":"全","h":"toàn"}],"example":"初詣で家内安全をお願いした。","example_reading":"はつもうででかないあんぜんをおねがいした。","example_meaning":"Đi lễ đầu năm, tôi cầu cho gia đình bình an.","examples":[{"example":"初詣で家内安全をお願いした。","example_reading":"はつもうででかないあんぜんをおねがいした。","example_meaning":"Đi lễ đầu năm, tôi cầu cho gia đình bình an."},{"example":"お守りには家内安全と書いてある。","example_reading":"おまもりにはかないあんぜんとかいてある。","example_meaning":"Trên bùa hộ mệnh có ghi chữ gia đình bình an."}],"level":"p1"},
{"word":"前途洋々（前途洋洋）","reading":"ぜんとようよう","meaning":"tương lai rộng mở, phía trước rực rỡ và đầy triển vọng.\n(Lời chúc hoặc sự kỳ vọng vào một chặng đường phía trước tươi sáng, hanh thông.)","hanviet":"tiền đồ dương dương","note":"洋洋 = mênh mông như nước biển (Kinh Thi có câu «hà thủy dương dương»). Đường trước trải rộng như sóng xa, hợp nói về người trẻ. Trái nghĩa: 前途多難。 前途 = con đường phía trước. Dùng cho người trẻ hoặc người mới bắt đầu. Trái nghĩa: 前途多難.","chars":[{"c":"前","h":"tiền"},{"c":"途","h":"đồ"},{"c":"洋","h":"dương"},{"c":"洋","h":"dương"}],"poem":{"han":"前路洋洋春水闊／青雲有待少年行","hv":"Tiền lộ dương dương xuân thủy khoát / Thanh vân hữu đãi thiếu niên hành","vi":"Đường trước mênh mang như nước xuân, mây xanh đang đợi bước chân tuổi trẻ."},"example":"彼は優秀な成績で卒業し、前途洋々だ。","example_reading":"かれはゆうしゅうなせいせきでそつぎょうし、ぜんとようようだ。","example_meaning":"Anh ấy tốt nghiệp loại giỏi, tương lai rộng mở.","examples":[{"example":"彼は優秀な成績で卒業し、前途洋々だ。","example_reading":"かれはゆうしゅうなせいせきでそつぎょうし、ぜんとようようだ。","example_meaning":"Anh ấy tốt nghiệp loại giỏi, tương lai rộng mở."},{"example":"新入社員の彼女は、前途洋々の未来を信じている。","example_reading":"しんにゅうしゃいんのかのじょは、ぜんとようようのみらいをしんじている。","example_meaning":"Cô nhân viên mới tin vào tương lai rộng mở của mình."}],"level":"p2"},
{"word":"前途多難","reading":"ぜんとたなん","meaning":"con đường phía trước còn nhiều trắc trở, gian nan.\n(Sự cảnh báo về những thử thách sắp tới cần sự kiên trì vượt qua.)","hanviet":"tiền đồ đa nan","note":"難 = gian nan. Như lữ khách nhìn núi chồng núi trước mặt. Chỉ dùng cho triển vọng sắp tới, không dùng cho việc đã xảy ra. Thường dùng khi nói về triển vọng chưa chắc chắn, không dùng cho chuyện đã xảy ra.","chars":[{"c":"前","h":"tiền"},{"c":"途","h":"đồ"},{"c":"多","h":"đa"},{"c":"難","h":"nan"}],"poem":{"han":"關山疊疊前程遠／風雨重重客路難","hv":"Quan san điệp điệp tiền trình viễn / Phong vũ trùng trùng khách lộ nan","vi":"Núi ải chập chùng đường còn xa, mưa gió dồn dập bước lữ khách nhọc nhằn."},"example":"新しい会社を始めたが、資金が足りず前途多難だ。","example_reading":"あたらしいかいしゃをはじめたが、しきんがたりずぜんとたなんだ。","example_meaning":"Mở công ty mới nhưng thiếu vốn, phía trước còn nhiều gian nan.","examples":[{"example":"新しい会社を始めたが、資金が足りず前途多難だ。","example_reading":"あたらしいかいしゃをはじめたが、しきんがたりずぜんとたなんだ。","example_meaning":"Mở công ty mới nhưng thiếu vốn, phía trước còn nhiều gian nan."},{"example":"新薬の開発は前途多難だが、研究チームは諦めていない。","example_reading":"しんやくのかいはつはぜんとたなんだが、けんきゅうチームはあきらめていない。","example_meaning":"Phát triển thuốc mới còn nhiều trắc trở nhưng nhóm nghiên cứu không bỏ cuộc."}],"level":"p2"},
{"word":"大器晩成","reading":"たいきばんせい","meaning":"tài năng lớn cần thời gian rèn luyện mới thành công; càng về sau càng tỏa sáng.\n(Động viên những ai thành công muộn, khẳng định giá trị của sự kiên trì bền bỉ.)","hanviet":"đại khí vãn thành","note":"Lão Tử, chương 41: «大器晩成». Đồ vật lớn thì đúc lâu. Không dùng để tự an ủi cho sự lười biếng.","chars":[{"c":"大","h":"đại"},{"c":"器","h":"khí"},{"c":"晩","h":"vãn"},{"c":"成","h":"thành"}],"poem":{"han":"巨鼎成時霜鬢老／長松立處歲寒知","hv":"Cự đỉnh thành thời sương mấn lão / Trường tùng lập xứ tuế hàn tri","vi":"Vạc lớn đúc xong thì tóc đã sương, cây tùng cao đứng đó mới biết lúc rét đậm."},"example":"彼は大器晩成型で、四十歳から活躍し始めた。","example_reading":"かれはたいきばんせいがたで、よんじっさいからかつやくしはじめた。","example_meaning":"Anh ấy thành công muộn, đến 40 tuổi mới tỏa sáng.","examples":[{"example":"彼は大器晩成型で、四十歳から活躍し始めた。","example_reading":"かれはたいきばんせいがたで、よんじっさいからかつやくしはじめた。","example_meaning":"Anh ấy thành công muộn, đến 40 tuổi mới tỏa sáng."},{"example":"彼は無名時代が長かったが、大器晩成の典型だ。","example_reading":"かれはむめいじだいがながかったが、たいきばんせいのてんけいだ。","example_meaning":"Anh ấy vô danh lâu năm, đúng là điển hình thành công muộn."}],"level":"p2"},
{"word":"温故知新","reading":"おんこちしん","meaning":"ôn lại chuyện cũ để hiểu điều mới; học từ quá khứ để đúc kết cho tương lai.\n(Trân trọng bài học lịch sử và kinh nghiệm đi trước để sáng tạo giá trị mới.)","hanviet":"ôn cố tri tân","note":"Luận ngữ, thiên Vi chính: «温故而知新，可以為師矣». Ôn chuyện cũ để thấy điều mới thì đáng làm thầy.","chars":[{"c":"温","h":"ôn"},{"c":"故","h":"cố"},{"c":"知","h":"tri"},{"c":"新","h":"tân"}],"poem":{"han":"溫來舊卷知新味／挑盡殘燈見曙光","hv":"Ôn lai cựu quyển tri tân vị / Khiêu tận tàn đăng kiến thự quang","vi":"Ôn quyển sách cũ mà thấy vị mới, khêu hết đèn tàn thì thấy ánh bình minh."},"example":"温故知新の精神で、昔の技術を学ぶ。","example_reading":"おんこちしんのせいしんで、むかしのぎじゅつをまなぶ。","example_meaning":"Theo tinh thần ôn cũ biết mới, tôi học kỹ thuật xưa.","examples":[{"example":"温故知新の精神で、昔の技術を学ぶ。","example_reading":"おんこちしんのせいしんで、むかしのぎじゅつをまなぶ。","example_meaning":"Theo tinh thần ôn cũ biết mới, tôi học kỹ thuật xưa."},{"example":"古い建築を調べて、新しいデザインのヒントを得た。まさに温故知新だ。","example_reading":"ふるいけんちくをしらべて、あたらしいデザインのヒントをえた。まさにおんこちしんだ。","example_meaning":"Khảo cứu kiến trúc cũ rồi có gợi ý cho thiết kế mới, đúng là ôn cố tri tân."}],"level":"p2"},
{"word":"自画自賛","reading":"じがじさん","meaning":"tự vẽ tự khen; tự mèo khen mèo dài đuôi.\n(Sự tự hào quá mức về bản thân hoặc thành quả của chính mình.)","hanviet":"tự họa tự tán","note":"賛 = lời đề tán viết trên tranh. Tự vẽ tranh rồi tự đề thơ khen. Có sắc thái hơi tự mãn.","chars":[{"c":"自","h":"tự"},{"c":"画","h":"họa"},{"c":"自","h":"tự"},{"c":"賛","h":"tán"}],"poem":{"han":"自繪丹青自題贊／孤芳獨賞對東風","hv":"Tự hội đan thanh tự đề tán / Cô phương độc thưởng đối đông phong","vi":"Tự vẽ tranh rồi tự đề lời khen, hoa lẻ tự ngắm trước gió đông."},"example":"自画自賛になるが、この料理は最高だ。","example_reading":"じがじさんになるが、このりょうりはさいこうだ。","example_meaning":"Hơi tự khen, nhưng món này tuyệt nhất.","examples":[{"example":"自画自賛になるが、この料理は最高だ。","example_reading":"じがじさんになるが、このりょうりはさいこうだ。","example_meaning":"Hơi tự khen, nhưng món này tuyệt nhất."},{"example":"自画自賛だが、今回のレポートは自信作だ。","example_reading":"じがじさんだが、こんかいのレポートはじしんさくだ。","example_meaning":"Hơi tự khen, nhưng bản báo cáo lần này tôi rất tự tin."}],"level":"p2"},
{"word":"優柔不断","reading":"ゆうじゅうふだん","meaning":"do dự, thiếu quyết đoán, không thể đưa ra lựa chọn dứt khoát.\n(Sự đắn đo quá nhiều dẫn đến bỏ lỡ thời cơ thích hợp.)","hanviet":"ưu nhu bất đoạn","note":"優 = lề mề, 柔 = mềm yếu, 不断 = không dứt khoát. Như người cầm tay áo, đứng giữa ngã ba đường.","chars":[{"c":"優","h":"ưu"},{"c":"柔","h":"nhu"},{"c":"不","h":"bất"},{"c":"断","h":"đoạn"}],"poem":{"han":"臨岐攬袖徘徊久／日暮空看路兩條","hv":"Lâm kỳ lãm tụ bồi hồi cửu / Nhật mộ không khan lộ lưỡng điều","vi":"Đứng ngã ba cầm tay áo bồi hồi mãi, chiều xuống chỉ ngồi nhìn hai con đường."},"example":"彼は優柔不断で、メニューを決めるのに時間がかかる。","example_reading":"かれはゆうじゅうふだんで、メニューをきめるのにじかんがかかる。","example_meaning":"Anh ấy thiếu quyết đoán, chọn món rất lâu.","examples":[{"example":"彼は優柔不断で、メニューを決めるのに時間がかかる。","example_reading":"かれはゆうじゅうふだんで、メニューをきめるのにじかんがかかる。","example_meaning":"Anh ấy thiếu quyết đoán, chọn món rất lâu."},{"example":"優柔不断な性格で、旅行の行き先がなかなか決まらない。","example_reading":"ゆうじゅうふだんなせいかくで、りょこうのいきさきがなかなかきまらない。","example_meaning":"Tính hay do dự nên mãi chưa chọn được điểm du lịch."}],"level":"p2"},
{"word":"絶体絶命","reading":"ぜったいぜつめい","meaning":"rơi vào bước đường cùng, tình thế vô cùng nguy cấp không còn lối thoát.\n(Thử thách cực hạn đòi hỏi sự dũng cảm và bản lĩnh phi thường.)","hanviet":"tuyệt thể tuyệt mệnh","note":"絶 = dứt, 体 = thân, 命 = mạng. Thân hết đường lui, mạng sát bờ vực. Thường đi với ピンチ, 状況.","chars":[{"c":"絶","h":"tuyệt"},{"c":"体","h":"thể"},{"c":"絶","h":"tuyệt"},{"c":"命","h":"mệnh"}],"poem":{"han":"窮途日暮無歸路／一線生機繫此身","hv":"Cùng đồ nhật mộ vô quy lộ / Nhất tuyến sinh cơ hệ thử thân","vi":"Đường cùng chiều tối không lối về, một tia sống còn buộc vào thân này."},"example":"残り一分で二点差。絶体絶命のピンチだ。","example_reading":"のこりいっぷんでにてんさ。ぜったいぜつめいのピンチだ。","example_meaning":"Còn 1 phút mà thua 2 điểm. Đúng là cùng đường.","examples":[{"example":"残り一分で二点差。絶体絶命のピンチだ。","example_reading":"のこりいっぷんでにてんさ。ぜったいぜつめいのピンチだ。","example_meaning":"Còn 1 phút mà thua 2 điểm. Đúng là cùng đường."},{"example":"崖の端に追い詰められ、絶体絶命の状況になった。","example_reading":"がけのはしにおいつめられ、ぜったいぜつめいのじょうきょうになった。","example_meaning":"Bị dồn đến mép vực, rơi vào tình thế cùng đường."}],"level":"p2"},
{"word":"一期一会","reading":"いちごいちえ","meaning":"cuộc gặp gỡ kỳ diệu chỉ có một lần trong đời.\n(Nhắc nhở ta trân trọng từng khoảnh khắc và con người hiện tại, vì cuộc hội ngộ này sẽ không bao giờ lặp lại.)","hanviet":"nhất kỳ nhất hội","note":"Từ trà đạo, người nâng tầm là Ii Naosuke. 一期 = cả một đời (thuật ngữ Phật giáo), 一会 = một lần gặp.","chars":[{"c":"一","h":"nhất"},{"c":"期","h":"kỳ"},{"c":"一","h":"nhất"},{"c":"会","h":"hội"}],"poem":{"han":"一杯清茗一期遇／此會今生不再逢","hv":"Nhất bôi thanh minh nhất kỳ ngộ / Thử hội kim sinh bất tái phùng","vi":"Một chén trà trong, gặp gỡ một đời; cuộc họp mặt này kiếp này không gặp lại."},"example":"お客様との出会いは一期一会だと思って接する。","example_reading":"おきゃくさまとのであいはいちごいちえだとおもってせっする。","example_meaning":"Tôi tiếp khách với ý nghĩ mỗi lần gặp chỉ có một lần.","examples":[{"example":"お客様との出会いは一期一会だと思って接する。","example_reading":"おきゃくさまとのであいはいちごいちえだとおもってせっする。","example_meaning":"Tôi tiếp khách với ý nghĩ mỗi lần gặp chỉ có một lần."},{"example":"この旅で出会った人たちとの時間は、一期一会だ。","example_reading":"このたびでであったひとたちとのじかんは、いちごいちえだ。","example_meaning":"Thời gian bên những người gặp trong chuyến đi này là một lần duy nhất."}],"level":"p2"},
{"word":"七転八倒","reading":"しちてんばっとう","meaning":"vật vã vì đau đớn","hanviet":"thất chuyển bát đảo","note":"転 = lăn, 倒 = ngã. Bảy và tám chỉ nhiều lần. Chỉ đau đớn thể xác, khác 七転び八起き. ⚠ Không nhầm với 七転び八起き (ことわざ, nghĩa là đứng dậy sau thất bại). Câu này chỉ sự đau đớn quằn quại.","chars":[{"c":"七","h":"thất"},{"c":"転","h":"chuyển"},{"c":"八","h":"bát"},{"c":"倒","h":"đảo"}],"poem":{"han":"痛徹肝腸輾轉夜／床前翻覆不成眠","hv":"Thống triệt can trường triển chuyển dạ / Sàng tiền phiên phúc bất thành miên","vi":"Đau thấu ruột gan trằn trọc suốt đêm, trước giường lăn lộn chẳng thành giấc."},"example":"腹痛で七転八倒した。","example_reading":"ふくつうでしちてんばっとうした。","example_meaning":"Tôi đau bụng đến vật vã.","examples":[{"example":"腹痛で七転八倒した。","example_reading":"ふくつうでしちてんばっとうした。","example_meaning":"Tôi đau bụng đến vật vã."},{"example":"激しい歯の痛みに、一晩中七転八倒した。","example_reading":"はげしいはのいたみに、ひとばんじゅうしちてんばっとうした。","example_meaning":"Cơn đau răng dữ dội khiến tôi quằn quại cả đêm."}],"level":"p2"},
{"word":"首尾一貫","reading":"しゅびいっかん","meaning":"trước sau như một, kiên định từ đầu đến cuối không thay đổi.\n(Tính nhất quán, uy tín và lòng kiên trì trong tư tưởng lẫn hành động.)","hanviet":"thủ vĩ nhất quán","note":"首 = đầu, 尾 = đuôi, 一貫 gợi «吾道一以貫之» (Luận ngữ): một đạo xuyên suốt từ đầu tới cuối.","chars":[{"c":"首","h":"thủ"},{"c":"尾","h":"vĩ"},{"c":"一","h":"nhất"},{"c":"貫","h":"quán"}],"poem":{"han":"一線穿珠無斷處／始終同轍不迷津","hv":"Nhất tuyến xuyên châu vô đoạn xứ / Thủy chung đồng triệt bất mê tân","vi":"Một sợi xuyên chuỗi ngọc không chỗ đứt, đầu cuối cùng một vệt bánh xe, chẳng lạc bến."},"example":"彼の意見は首尾一貫している。","example_reading":"かれのいけんはしゅびいっかんしている。","example_meaning":"Ý kiến của anh ấy nhất quán từ đầu đến cuối.","examples":[{"example":"彼の意見は首尾一貫している。","example_reading":"かれのいけんはしゅびいっかんしている。","example_meaning":"Ý kiến của anh ấy nhất quán từ đầu đến cuối."},{"example":"首尾一貫した態度が、周りの信頼を生んだ。","example_reading":"しゅびいっかんしたたいどが、まわりのしんらいをうんだ。","example_meaning":"Thái độ nhất quán đã tạo nên lòng tin của mọi người."}],"level":"p2"},
{"word":"意気投合","reading":"いきとうごう","meaning":"tâm đầu ý hợp, hợp cạ, chia sẻ cùng chung lý tưởng và quan điểm.\n(Sự ăn ý, hòa hợp nhanh chóng giữa những người có chung chí hướng.)","hanviet":"ý khí đầu hợp","note":"意気 = khí phách, 投合 = ăn khớp nhau. Như «高山流水» gặp tri âm: vừa gặp đã hợp tiếng.","chars":[{"c":"意","h":"ý"},{"c":"気","h":"khí"},{"c":"投","h":"đầu"},{"c":"合","h":"hợp"}],"poem":{"han":"高山流水逢知己／一見傾心酒滿杯","hv":"Cao sơn lưu thủy phùng tri kỷ / Nhất kiến khuynh tâm tửu mãn bôi","vi":"Núi cao nước chảy gặp tri kỷ, vừa gặp đã nghiêng lòng, rượu đầy chén."},"example":"初めて会ったのに、すぐに意気投合した。","example_reading":"はじめてあったのに、すぐにいきとうごうした。","example_meaning":"Mới gặp lần đầu mà đã hợp ý nhau.","examples":[{"example":"初めて会ったのに、すぐに意気投合した。","example_reading":"はじめてあったのに、すぐにいきとうごうした。","example_meaning":"Mới gặp lần đầu mà đã hợp ý nhau."},{"example":"趣味が同じと分かって、二人はすぐ意気投合した。","example_reading":"しゅみがおなじとわかって、ふたりはすぐいきとうごうした。","example_meaning":"Biết cùng sở thích, hai người lập tức hợp ý nhau."}],"level":"p2"},
{"word":"起死回生","reading":"きしかいせい","meaning":"lội ngược dòng; xoay chuyển tình thế từ cõi chết trở về sống.\n(Sự kỳ diệu khi biến thất bại mười mươi thành chiến thắng rực rỡ.)","hanviet":"khởi tử hồi sinh","note":"起 = làm đứng dậy, 回 = kéo về. Gợi thần y Biển Thước cứu thái tử nước Quắc trong Sử ký.","chars":[{"c":"起","h":"khởi"},{"c":"死","h":"tử"},{"c":"回","h":"hồi"},{"c":"生","h":"sinh"}],"poem":{"han":"枯骨重生春滿地／殘燈復燦夜迴天","hv":"Khô cốt trùng sinh xuân mãn địa / Tàn đăng phục xán dạ hồi thiên","vi":"Xương khô sống lại xuân tràn đất, đèn tàn sáng lại đêm quay trời."},"example":"起死回生のホームランで逆転した。","example_reading":"きしかいせいのホームランでぎゃくてんした。","example_meaning":"Cú home run lật ngược thế cờ.","examples":[{"example":"起死回生のホームランで逆転した。","example_reading":"きしかいせいのホームランでぎゃくてんした。","example_meaning":"Cú home run lật ngược thế cờ."},{"example":"起死回生の一手で、会社は倒産をまぬがれた。","example_reading":"きしかいせいのいってで、かいしゃはとうさんをまぬがれた。","example_meaning":"Nhờ một nước cờ lật ngược thế cờ, công ty thoát phá sản."}],"level":"p2"},
{"word":"日常茶飯事","reading":"にちじょうさはんじ","meaning":"chuyện thường ngày như cơm ăn nước uống; việc hết sức bình thường.\n(Những điều quen thuộc diễn ra hàng ngày không có gì đáng ngạc nhiên.)","hanviet":"nhật thường trà phạn sự","note":"茶飯 = trà và cơm. Việc như cơm nước hằng ngày, thành chuyện quen thuộc (Thiền ngữ «家常茶飯»).","chars":[{"c":"日","h":"nhật"},{"c":"常","h":"thường"},{"c":"茶","h":"trà"},{"c":"飯","h":"phạn"},{"c":"事","h":"sự"}],"poem":{"han":"一盞清茶三碗飯／尋常日月不驚人","hv":"Nhất trản thanh trà tam oản phạn / Tầm thường nhật nguyệt bất kinh nhân","vi":"Một chén trà trong ba bát cơm, ngày tháng tầm thường chẳng ai giật mình."},"example":"この地域では、停電は日常茶飯事だ。","example_reading":"このちいきでは、ていでんはにちじょうさはんじだ。","example_meaning":"Ở vùng này mất điện là chuyện thường.","examples":[{"example":"この地域では、停電は日常茶飯事だ。","example_reading":"このちいきでは、ていでんはにちじょうさはんじだ。","example_meaning":"Ở vùng này mất điện là chuyện thường."},{"example":"電車の遅れは都会では日常茶飯事だ。","example_reading":"でんしゃのおくれはとかいではにちじょうさはんじだ。","example_meaning":"Tàu trễ giờ ở thành phố là chuyện thường ngày."}],"level":"p2"},
{"word":"切磋琢磨","reading":"せっさたくま","meaning":"cùng nhau mài dũa, rèn luyện và thúc đẩy nhau tiến bộ.\n(Sự thi đua lành mạnh giữa những người bạn, đồng nghiệp để cùng hoàn thiện.)","hanviet":"thiết tha trác ma","note":"Kinh Thi: «如切如磋，如琢如磨». Cắt xương, mài ngà, đẽo ngọc, mài đá: người cũng cần nhau mài giũa.","chars":[{"c":"切","h":"thiết"},{"c":"磋","h":"tha"},{"c":"琢","h":"trác"},{"c":"磨","h":"ma"}],"poem":{"han":"玉待雕琢方成器／友憑切磋始見真","hv":"Ngọc đãi điêu trác phương thành khí / Hữu bằng thiết tha thủy kiến chân","vi":"Ngọc đợi đẽo mài mới thành khí, bạn nhờ cắt mài mới thấy chân."},"example":"仲間と切磋琢磨して、実力を伸ばした。","example_reading":"なかまとせっさたくましてじつりょくをのばした。","example_meaning":"Tôi cùng bạn bè rèn giũa nhau nên nâng cao được năng lực.","examples":[{"example":"仲間と切磋琢磨して、実力を伸ばした。","example_reading":"なかまとせっさたくましてじつりょくをのばした。","example_meaning":"Tôi cùng bạn bè rèn giũa nhau nên nâng cao được năng lực."},{"example":"ライバルと切磋琢磨して、全国大会に出場した。","example_reading":"ライバルとせっさたくましてぜんこくたいかいにしゅつじょうした。","example_meaning":"Cùng đối thủ rèn giũa nhau, tôi đã vào được giải toàn quốc."}],"level":"p2"},
{"word":"弱肉強食","reading":"じゃくにくきょうしょく","meaning":"cá lớn nuốt cá bé; luật sinh tồn khắc nghiệt.\n(Quy luật tự nhiên và xã hội nơi kẻ mạnh chi phối và kẻ yếu bị lấn lướt.)","hanviet":"nhược nhục cường thực","note":"Hàn Dũ viết «弱之肉，強之食»: thịt của kẻ yếu là thức ăn của kẻ mạnh. Dùng cho tự nhiên, thương trường.","chars":[{"c":"弱","h":"nhược"},{"c":"肉","h":"nhục"},{"c":"強","h":"cường"},{"c":"食","h":"thực"}],"poem":{"han":"大魚吞小魚吞蝦／強者為君弱者糧","hv":"Đại ngư thôn tiểu ngư thôn hà / Cường giả vi quân nhược giả lương","vi":"Cá lớn nuốt cá bé, cá bé nuốt tôm; kẻ mạnh làm vua, kẻ yếu làm lương thực."},"example":"自然界は弱肉強食の世界だ。","example_reading":"しぜんかいはじゃくにくきょうしょくのせかいだ。","example_meaning":"Thế giới tự nhiên là nơi kẻ mạnh ăn kẻ yếu.","examples":[{"example":"自然界は弱肉強食の世界だ。","example_reading":"しぜんかいはじゃくにくきょうしょくのせかいだ。","example_meaning":"Thế giới tự nhiên là nơi kẻ mạnh ăn kẻ yếu."},{"example":"ビジネスの世界は弱肉強食だと言われる。","example_reading":"ビジネスのせかいはじゃくにくきょうしょくだといわれる。","example_meaning":"Người ta bảo thương trường là nơi cá lớn nuốt cá bé."}],"level":"p2"},
{"word":"勇猛果敢","reading":"ゆうもうかかん","meaning":"dũng cảm, quyết đoán, không sợ hãi trước khó khăn.\n(Bản lĩnh mạnh mẽ, sẵn sàng xông pha và đưa ra quyết định táo bạo.)","hanviet":"dũng mãnh quả cảm","note":"勇猛 = mạnh dạn, 果敢 = quyết đoán. Dùng khen hành động dũng cảm.","chars":[{"c":"勇","h":"dũng"},{"c":"猛","h":"mãnh"},{"c":"果","h":"quả"},{"c":"敢","h":"cảm"}],"poem":{"han":"猛虎出山無懼色／長風破浪有雄心","hv":"Mãnh hổ xuất sơn vô cụ sắc / Trường phong phá lãng hữu hùng tâm","vi":"Hổ dữ xuống núi chẳng sợ hãi, gió dài rẽ sóng có lòng hùng."},"example":"消防士は勇猛果敢に火の中へ入っていった。","example_reading":"しょうぼうしはゆうもうかかんにひのなかへはいっていった。","example_meaning":"Người lính cứu hỏa dũng cảm lao vào lửa.","examples":[{"example":"消防士は勇猛果敢に火の中へ入っていった。","example_reading":"しょうぼうしはゆうもうかかんにひのなかへはいっていった。","example_meaning":"Người lính cứu hỏa dũng cảm lao vào lửa."},{"example":"勇猛果敢な攻めで、チームが逆転勝ちした。","example_reading":"ゆうもうかかんなせめで、チームがぎゃくてんがちした。","example_meaning":"Nhờ lối tấn công quả cảm, đội đã ngược dòng thắng."}],"level":"p2"},
{"word":"唯我独尊","reading":"ゆいがどくそん","meaning":"coi mình là nhất, tự cao tự đại.\n(Thái độ tự tin thái quá hoặc tôn vinh sự tồn tại độc nhất của bản thân.)","hanviet":"duy ngã độc tôn","note":"Từ «thiên thượng thiên hạ duy ngã độc tôn» lúc Phật đản sinh. Nay hay chỉ người tự cao.","chars":[{"c":"唯","h":"duy"},{"c":"我","h":"ngã"},{"c":"独","h":"độc"},{"c":"尊","h":"tôn"}],"poem":{"han":"自擡自貴稱無上／四顧無人只有身","hv":"Tự đài tự quý xưng vô thượng / Tứ cố vô nhân chỉ hữu thân","vi":"Tự nâng tự quý xưng không ai hơn, nhìn quanh chẳng ai, chỉ có mình."},"example":"彼は唯我独尊で、人の意見を聞かない。","example_reading":"かれはゆいがどくそんで、ひとのいけんをきかない。","example_meaning":"Anh ta tự cho mình là nhất, chẳng nghe ai.","examples":[{"example":"彼は唯我独尊で、人の意見を聞かない。","example_reading":"かれはゆいがどくそんで、ひとのいけんをきかない。","example_meaning":"Anh ta tự cho mình là nhất, chẳng nghe ai."},{"example":"唯我独尊の態度では、仲間はできない。","example_reading":"ゆいがどくそんのたいどでは、なかまはできない。","example_meaning":"Thái độ coi mình là nhất thì không có bạn."}],"level":"p2"},
{"word":"呉越同舟","reading":"ごえつどうしゅう","meaning":"kẻ thù chung ngồi chung một thuyền; hợp tác vì mục tiêu chung.\n(Sự gạt bỏ hiềm thù cá nhân để cùng đối mặt với thử thách lớn hơn.)","hanviet":"ngô việt đồng chu","note":"Binh pháp Tôn Tử: người nước Ngô và Việt ghét nhau, nhưng cùng thuyền gặp bão thì giúp nhau.","chars":[{"c":"呉","h":"ngô"},{"c":"越","h":"việt"},{"c":"同","h":"đồng"},{"c":"舟","h":"chu"}],"poem":{"han":"吳越仇讎同一棹／風波急處自相扶","hv":"Ngô Việt cừu thù đồng nhất trạo / Phong ba cấp xứ tự tương phù","vi":"Ngô Việt thù nhau chung một chèo, chỗ sóng gió gấp tự đỡ nhau."},"example":"ライバル会社同士が呉越同舟で新技術を開発した。","example_reading":"ライバルがいしゃどうしがごえつどうしゅうでしんぎじゅつをかいはつした。","example_meaning":"Hai công ty đối thủ bắt tay phát triển công nghệ mới.","examples":[{"example":"ライバル会社同士が呉越同舟で新技術を開発した。","example_reading":"ライバルがいしゃどうしがごえつどうしゅうでしんぎじゅつをかいはつした。","example_meaning":"Hai công ty đối thủ bắt tay phát triển công nghệ mới."},{"example":"呉越同舟の状態だが、今は協力するしかない。","example_reading":"ごえつどうしゅうのじょうたいだが、いまはきょうりょくするしかない。","example_meaning":"Tuy như kẻ thù cùng thuyền, giờ chỉ còn cách hợp tác."}],"level":"p2"},
{"word":"五里霧中","reading":"ごりむちゅう","meaning":"như lạc vào màn sương mù năm dặm; mất phương hướng, không biết làm sao.\n(Trạng thái mông lung, bối rối khi thiếu thông tin hoặc chưa tìm ra hướng đi.)","hanviet":"ngũ lý vụ trung","note":"Hậu Hán thư kể Trương Giai làm được sương mù năm dặm. Nay chỉ trạng thái mù mờ không lối ra.","chars":[{"c":"五","h":"ngũ"},{"c":"里","h":"lý"},{"c":"霧","h":"vụ"},{"c":"中","h":"trung"}],"poem":{"han":"霧鎖五里迷歸路／不辨東西不識津","hv":"Vụ tỏa ngũ lý mê quy lộ / Bất biện đông tây bất thức tân","vi":"Sương phủ năm dặm lạc lối về, chẳng phân đông tây, chẳng biết bến."},"example":"事件の真相は、まだ五里霧中だ。","example_reading":"じけんのしんそうは、まだごりむちゅうだ。","example_meaning":"Sự thật vụ việc vẫn còn mù mịt.","examples":[{"example":"事件の真相は、まだ五里霧中だ。","example_reading":"じけんのしんそうは、まだごりむちゅうだ。","example_meaning":"Sự thật vụ việc vẫn còn mù mịt."},{"example":"五里霧中の状態で、研究を進めている。","example_reading":"ごりむちゅうのじょうたいで、けんきゅうをすすめている。","example_meaning":"Tôi đang làm nghiên cứu mà chưa thấy hướng đi."}],"level":"p2"},
{"word":"画竜点睛","reading":"がりょうてんせい","meaning":"vẽ rồng điểm mắt; điểm nhấn hoàn hảo làm nên thần thái cho tác phẩm.\n(Nét hoàn thiện cuối cùng biến điều bình thường trở nên kiệt tác.)","hanviet":"họa long điểm tinh","note":"Truyện họa sĩ Trương Tăng Dao vẽ rồng, chấm mắt thì rồng bay đi. Chỉ nét quyết định.","chars":[{"c":"画","h":"họa"},{"c":"竜","h":"long"},{"c":"点","h":"điểm"},{"c":"睛","h":"tinh"}],"poem":{"han":"丹青畫就龍猶臥／一點睛成雲欲飛","hv":"Đan thanh họa tựu long do ngọa / Nhất điểm tình thành vân dục phi","vi":"Vẽ xong rồng vẫn nằm, chấm mắt một nét mây muốn bay."},"example":"最後の一言が、スピーチの画竜点睛となった。","example_reading":"さいごのひとことが、スピーチのがりょうてんせいとなった。","example_meaning":"Câu cuối cùng chính là nét điểm nhãn của bài phát biểu.","examples":[{"example":"最後の一言が、スピーチの画竜点睛となった。","example_reading":"さいごのひとことが、スピーチのがりょうてんせいとなった。","example_meaning":"Câu cuối cùng chính là nét điểm nhãn của bài phát biểu."},{"example":"この飾りが部屋の画竜点睛だ。","example_reading":"このかざりがへやのがりょうてんせいだ。","example_meaning":"Món đồ trang trí này là nét hoàn thiện của căn phòng."}],"level":"p2"},
{"word":"朝令暮改","reading":"ちょうれいぼかい","meaning":"sáng ban lệnh chiều thay đổi; chính sách bất nhất, thay đổi xoành xoạch.\n(Sự thiếu nhất quán khiến người khác hoang mang, mất niềm tin.)","hanviet":"triều lệnh mộ cải","note":"Từ Hán thư (Thực hóa chí) nói chính lệnh sáng ban chiều đổi. Mang nghĩa chê.","chars":[{"c":"朝","h":"triều"},{"c":"令","h":"lệnh"},{"c":"暮","h":"mộ"},{"c":"改","h":"cải"}],"poem":{"han":"朝頒政令暮更張／百姓茫然不自強","hv":"Triêu ban chính lệnh mộ canh trương / Bách tính mang nhiên bất tự cường","vi":"Sáng ban lệnh, chiều lại đổi, dân chúng ngơ ngác chẳng biết sao."},"example":"朝令暮改の方針に、社員は振り回された。","example_reading":"ちょうれいぼかいのほうしんに、しゃいんはふりまわされた。","example_meaning":"Nhân viên bị xoay như chong chóng vì chủ trương đổi liên tục.","examples":[{"example":"朝令暮改の方針に、社員は振り回された。","example_reading":"ちょうれいぼかいのほうしんに、しゃいんはふりまわされた。","example_meaning":"Nhân viên bị xoay như chong chóng vì chủ trương đổi liên tục."},{"example":"朝令暮改では、誰も信頼してくれない。","example_reading":"ちょうれいぼかいでは、だれもしんらいしてくれない。","example_meaning":"Sáng nắng chiều mưa như vậy thì chẳng ai tin."}],"level":"p2"},
{"word":"針小棒大","reading":"しんしょうぼうだい","meaning":"chuyện bé xé ra to; phóng đại sự việc quá mức.\n(Thái độ thổi phồng thực tế làm trầm trọng hóa vấn đề.)","hanviet":"châm tiểu bổng đại","note":"針 = kim, 棒 = gậy. Phóng đại sự việc. Mang nghĩa chê.","chars":[{"c":"針","h":"châm"},{"c":"小","h":"tiểu"},{"c":"棒","h":"bổng"},{"c":"大","h":"đại"}],"poem":{"han":"一針說作千尋棒／半語傳成萬里風","hv":"Nhất châm thuyết tác thiên tầm bổng / Bán ngữ truyền thành vạn lý phong","vi":"Một cây kim nói thành gậy nghìn tầm, nửa lời đồn thành gió vạn dặm."},"example":"針小棒大に言うと、信用を失うよ。","example_reading":"しんしょうぼうだいにいうと、しんようをうしなうよ。","example_meaning":"Nói quá lên thì sẽ mất uy tín đấy.","examples":[{"example":"針小棒大に言うと、信用を失うよ。","example_reading":"しんしょうぼうだいにいうと、しんようをうしなうよ。","example_meaning":"Nói quá lên thì sẽ mất uy tín đấy."},{"example":"ニュースが針小棒大に伝えられた。","example_reading":"ニュースがしんしょうぼうだいにつたえられた。","example_meaning":"Tin tức bị thổi phồng lên."}],"level":"p2"},
{"word":"他力本願","reading":"たりきほんがん","meaning":"trông chờ, ỷ lại vào sự giúp đỡ của người khác.\n(Thiếu tính tự lập, chỉ biết dựa dẫm vào hoàn cảnh hoặc người bên cạnh.)","hanviet":"tha lực bản nguyện","note":"Là thuật ngữ Tịnh độ tông: nhờ nguyện lực của Phật A-di-đà. Nay chê người ỷ lại.","chars":[{"c":"他","h":"tha"},{"c":"力","h":"lực"},{"c":"本","h":"bản"},{"c":"願","h":"nguyện"}],"poem":{"han":"倚人成事終非己／不種田疇望滿倉","hv":"Ỷ nhân thành sự chung phi kỷ / Bất chủng điền trù vọng mãn thương","vi":"Nhờ người làm việc rốt cuộc chẳng phải của mình, chẳng cày ruộng mà mong đầy kho."},"example":"他力本願ではなく、自分で努力しなさい。","example_reading":"たりきほんがんではなく、じぶんでどりょくしなさい。","example_meaning":"Đừng ỷ lại, hãy tự cố gắng.","examples":[{"example":"他力本願ではなく、自分で努力しなさい。","example_reading":"たりきほんがんではなく、じぶんでどりょくしなさい。","example_meaning":"Đừng ỷ lại, hãy tự cố gắng."},{"example":"他力本願の姿勢では、成長できない。","example_reading":"たりきほんがんのしせいでは、せいちょうできない。","example_meaning":"Thái độ ỷ lại thì không thể trưởng thành."}],"level":"p2"},
{"word":"傍若無人","reading":"ぼうじゃくぶじん","meaning":"coi trời bằng vung, ngông nghênh như chốn không người.\n(Hành vi thiếu lịch sự, không coi ai ra gì và coi thường quy tắc chung.)","hanviet":"bàng nhược vô nhân","note":"Sử ký (Kinh Kha): Kinh Kha uống rượu hát vang như bên cạnh không người. Nay mang nghĩa chê.","chars":[{"c":"傍","h":"bàng"},{"c":"若","h":"nhược"},{"c":"無","h":"vô"},{"c":"人","h":"nhân"}],"poem":{"han":"旁若無人高聲語／滿堂側目不知羞","hv":"Bàng nhược vô nhân cao thanh ngữ / Mãn đường trắc mục bất tri tu","vi":"Coi như không người, nói oang oang, cả sảnh liếc nhìn mà chẳng biết xấu hổ."},"example":"電車で傍若無人に大声で話す人がいる。","example_reading":"でんしゃでぼうじゃくぶじんにおおごえではなすひとがいる。","example_meaning":"Có người ngang nhiên nói to trên tàu.","examples":[{"example":"電車で傍若無人に大声で話す人がいる。","example_reading":"でんしゃでぼうじゃくぶじんにおおごえではなすひとがいる。","example_meaning":"Có người ngang nhiên nói to trên tàu."},{"example":"彼の傍若無人な振る舞いが問題になった。","example_reading":"かれのぼうじゃくぶじんなふるまいがもんだいになった。","example_meaning":"Cách cư xử ngang ngược của anh ta thành vấn đề."}],"level":"p2"},
{"word":"公明正大","reading":"こうめいせいだい","meaning":"thẳng thắn, công bằng, quang minh danh chính không chút khuất tất.\n(Phẩm chất trung thực, minh bạch trong mọi suy nghĩ và hành động.)","hanviet":"công minh chính đại","note":"公 = chung, 明 = sáng, 正 = ngay, 大 = lớn. Không có điều mờ ám.","chars":[{"c":"公","h":"công"},{"c":"明","h":"minh"},{"c":"正","h":"chính"},{"c":"大","h":"đại"}],"poem":{"han":"心如明鏡無私曲／行似青天不掩光","hv":"Tâm như minh kính vô tư khúc / Hành tự thanh thiên bất yểm quang","vi":"Lòng như gương sáng không thiên lệch, việc làm như trời xanh chẳng che ánh."},"example":"審判は公明正大な判断をしなければならない。","example_reading":"しんぱんはこうめいせいだいなはんだんをしなければならない。","example_meaning":"Trọng tài phải phán xét công bằng.","examples":[{"example":"審判は公明正大な判断をしなければならない。","example_reading":"しんぱんはこうめいせいだいなはんだんをしなければならない。","example_meaning":"Trọng tài phải phán xét công bằng."},{"example":"公明正大な選挙が行われた。","example_reading":"こうめいせいだいなせんきょがおこなわれた。","example_meaning":"Cuộc bầu cử đã diễn ra công minh."}],"level":"p2"},
{"word":"有名無実","reading":"ゆうめいむじつ","meaning":"có tiếng mà không có miếng; chỉ có cái tên trên danh nghĩa.\n(Sự hư danh, thiếu đi giá trị cốt lõi hoặc năng lực thực tế.)","hanviet":"hữu danh vô thực","note":"有 = có, 名 = tên, 無 = không, 実 = thực. Chỉ cái vỏ.","chars":[{"c":"有","h":"hữu"},{"c":"名","h":"danh"},{"c":"無","h":"vô"},{"c":"実","h":"thực"}],"poem":{"han":"空懸名號無其實／徒有虛聲不值錢","hv":"Không huyền danh hiệu vô kỳ thực / Đồ hữu hư thanh bất trị tiền","vi":"Treo tên suông mà không có thực, chỉ có tiếng hão chẳng đáng đồng."},"example":"その規則は有名無実になっている。","example_reading":"そのきそくはゆうめいむじつになっている。","example_meaning":"Quy định đó đã thành hữu danh vô thực.","examples":[{"example":"その規則は有名無実になっている。","example_reading":"そのきそくはゆうめいむじつになっている。","example_meaning":"Quy định đó đã thành hữu danh vô thực."},{"example":"有名無実の会長で、何も決めない。","example_reading":"ゆうめいむじつのかいちょうで、なにもきめない。","example_meaning":"Chủ tịch chỉ có danh, chẳng quyết gì."}],"level":"p2"},
{"word":"空前絶後","reading":"くうぜんぜつご","meaning":"vô tiền khoáng hậu; trước đây chưa từng có, sau này cũng khó lặp lại.\n(Sự kiện hoặc thành tựu phi thường, độc nhất vô nhị trong lịch sử.)","hanviet":"không tiền tuyệt hậu","note":"空 = trống, 絶 = dứt. Trước trống không, sau đứt hẳn.","chars":[{"c":"空","h":"không"},{"c":"前","h":"tiền"},{"c":"絶","h":"tuyệt"},{"c":"後","h":"hậu"}],"poem":{"han":"前無古例後無繼／一代風流獨此人","hv":"Tiền vô cổ lệ hậu vô kế / Nhất đại phong lưu độc thử nhân","vi":"Trước chẳng có tiền lệ, sau chẳng ai nối, một đời phong lưu chỉ riêng người này."},"example":"空前絶後の大ヒットとなった。","example_reading":"くうぜんぜつごのだいヒットとなった。","example_meaning":"Nó trở thành cú hit chưa từng có.","examples":[{"example":"空前絶後の大ヒットとなった。","example_reading":"くうぜんぜつごのだいヒットとなった。","example_meaning":"Nó trở thành cú hit chưa từng có."},{"example":"空前絶後の記録を打ち立てた。","example_reading":"くうぜんぜつごのきろくをうちたてた。","example_meaning":"Anh ấy lập kỷ lục trước chưa từng có."}],"level":"p2"},
{"word":"右往左往","reading":"うおうさおう","meaning":"chạy ngược chạy xuôi trong hoảng loạn; hoang mang không biết đi đâu.\n(Trạng thái mất bình tĩnh, hỗn loạn khi gặp sự cố bất ngờ.)","hanviet":"hữu vãng tả vãng","note":"右 = phải, 左 = trái, 往 = đi. Rối loạn khi gặp biến.","chars":[{"c":"右","h":"hữu"},{"c":"往","h":"vãng"},{"c":"左","h":"tả"},{"c":"往","h":"vãng"}],"poem":{"han":"東西南北無尋處／一陣驚慌亂似麻","hv":"Đông tây nam bắc vô tầm xứ / Nhất trận kinh hoàng loạn tự ma","vi":"Đông tây nam bắc chẳng biết tìm đâu, một trận hoảng loạn rối như tơ."},"example":"地震が起き、人々は右往左往した。","example_reading":"じしんがおき、ひとびとはうおうさおうした。","example_meaning":"Động đất xảy ra, mọi người cuống cuồng.","examples":[{"example":"地震が起き、人々は右往左往した。","example_reading":"じしんがおき、ひとびとはうおうさおうした。","example_meaning":"Động đất xảy ra, mọi người cuống cuồng."},{"example":"トラブルで社員が右往左往している。","example_reading":"トラブルでしゃいんがうおうさおうしている。","example_meaning":"Vì sự cố, nhân viên chạy loạn cả lên."}],"level":"p2"},
{"word":"時期尚早","reading":"じきしょうそう","meaning":"thời điểm còn quá sớm, chưa chín muồi để thực hiện.\n(Sự nhắc nhở cần kiên nhẫn chờ đợi cơ hội thích hợp hơn.)","hanviet":"thời kỳ thượng tảo","note":"尚 = còn, 早 = sớm. Dùng khi từ chối làm việc lúc này.","chars":[{"c":"時","h":"thời"},{"c":"期","h":"kỳ"},{"c":"尚","h":"thượng"},{"c":"早","h":"tảo"}],"poem":{"han":"花未盈枝休折取／時還欠火莫催炊","hv":"Hoa vị doanh chi hưu chiết thủ / Thời hoàn khiếm hỏa mạc thôi xuy","vi":"Hoa chưa đầy cành đừng vội hái, lửa chưa đủ lửa chớ giục thổi."},"example":"結論を出すのは時期尚早だ。","example_reading":"けつろんをだすのはじきしょうそうだ。","example_meaning":"Đưa ra kết luận lúc này còn quá sớm.","examples":[{"example":"結論を出すのは時期尚早だ。","example_reading":"けつろんをだすのはじきしょうそうだ。","example_meaning":"Đưa ra kết luận lúc này còn quá sớm."},{"example":"海外進出はまだ時期尚早と判断した。","example_reading":"かいがいしんしゅつはまだじきしょうそうとはんだんした。","example_meaning":"Chúng tôi cho rằng ra nước ngoài còn quá sớm."}],"level":"p2"},
{"word":"責任転嫁","reading":"せきにんてんか","meaning":"đùn đẩy trách nhiệm, đổ lỗi cho người khác.\n(Hành vi thiếu can đảm nhận lỗi về bản thân.)","hanviet":"trách nhiệm chuyển giá","note":"転嫁 = chuyển sang người khác. Mang nghĩa chê.","chars":[{"c":"責","h":"trách"},{"c":"任","h":"nhiệm"},{"c":"転","h":"chuyển"},{"c":"嫁","h":"giá"}],"poem":{"han":"自拋己咎投他處／空說無辜不認非","hv":"Tự phao kỷ cữu đầu tha xứ / Không thuyết vô cô bất nhận phi","vi":"Tự ném lỗi mình sang người, nói suông mình vô tội chẳng nhận sai."},"example":"失敗を部下に責任転嫁してはいけない。","example_reading":"しっぱいをぶかにせきにんてんかしてはいけない。","example_meaning":"Không được đổ lỗi thất bại cho cấp dưới.","examples":[{"example":"失敗を部下に責任転嫁してはいけない。","example_reading":"しっぱいをぶかにせきにんてんかしてはいけない。","example_meaning":"Không được đổ lỗi thất bại cho cấp dưới."},{"example":"彼は責任転嫁ばかりする。","example_reading":"かれはせきにんてんかばかりする。","example_meaning":"Anh ta toàn đổ trách nhiệm cho người khác."}],"level":"p2"},
{"word":"花鳥風月","reading":"かちょうふうげつ","meaning":"thưởng ngoạn vẻ đẹp thiên nhiên (hoa, chim, gió, trăng); tâm hồn hòa mình cùng đất trời.\n(Nghệ thuật sống tao nhã, biết trân trọng những nét đẹp bình dị của tự nhiên.)","hanviet":"hoa điểu phong nguyệt","note":"Bốn vẻ đẹp thiên nhiên mà thi nhân thích vịnh. Cũng chỉ thú phong nhã.","chars":[{"c":"花","h":"hoa"},{"c":"鳥","h":"điểu"},{"c":"風","h":"phong"},{"c":"月","h":"nguyệt"}],"poem":{"han":"花開鳥囀風傳韻／月上江心酒滿觴","hv":"Hoa khai điểu chuyển phong truyền vận / Nguyệt thượng giang tâm tửu mãn thương","vi":"Hoa nở chim hót gió đưa vần, trăng lên giữa sông rượu đầy chén."},"example":"定年後は花鳥風月を楽しんで暮らしたい。","example_reading":"ていねんごはかちょうふうげつをたのしんでくらしたい。","example_meaning":"Sau khi nghỉ hưu tôi muốn sống thưởng hoa, chim, gió, trăng.","examples":[{"example":"定年後は花鳥風月を楽しんで暮らしたい。","example_reading":"ていねんごはかちょうふうげつをたのしんでくらしたい。","example_meaning":"Sau khi nghỉ hưu tôi muốn sống thưởng hoa, chim, gió, trăng."},{"example":"花鳥風月を詠んだ和歌が多い。","example_reading":"かちょうふうげつをよんだわかがおおい。","example_meaning":"Có nhiều bài waka vịnh hoa chim gió trăng."}],"level":"p2"},
{"word":"初志貫徹","reading":"しょしかんてつ","meaning":"giữ vững ý định ban đầu, kiên trì theo đuổi mục tiêu đến cùng.\n(Nhắc nhở không quên lý do bắt đầu khi gặp khó khăn giữa chừng.)","hanviet":"sơ chí quán triệt","chars":[{"c":"初","h":"sơ"},{"c":"志","h":"chí"},{"c":"貫","h":"quán"},{"c":"徹","h":"triệt"}],"example":"初志貫徹を誓う。","example_reading":"しょしかんてつをちかう。","example_meaning":"Thề giữ vững chí ban đầu.","examples":[{"example":"初志貫徹を誓う。","example_reading":"しょしかんてつをちかう。","example_meaning":"Thề giữ vững chí ban đầu."},{"example":"初志貫徹して合格した。","example_reading":"しょしかんてつしてごうかくした。","example_meaning":"Giữ chí ban đầu và đã đỗ."}],"level":"p2"},
{"word":"一意専心","reading":"いちいせんしん","meaning":"tập trung toàn bộ trí lực và tâm trí vào một mục tiêu duy nhất.\n(Bí quyết thành công nhờ sự kiên định, không để các yếu tố bên ngoài làm xao nhãng.)","hanviet":"nhất ý chuyên tâm","chars":[{"c":"一","h":"nhất"},{"c":"意","h":"ý"},{"c":"専","h":"chuyên"},{"c":"心","h":"tâm"}],"example":"一意専心、研究に励む。","example_reading":"いちいせんしん、けんきゅうにはげむ。","example_meaning":"Chuyên tâm vào nghiên cứu.","examples":[{"example":"一意専心、研究に励む。","example_reading":"いちいせんしん、けんきゅうにはげむ。","example_meaning":"Chuyên tâm vào nghiên cứu."},{"example":"一意専心で練習した。","example_reading":"いちいせんしんでれんしゅうした。","example_meaning":"Tập luyện hết lòng một ý."}],"level":"p2"},
{"word":"一刻千金","reading":"いっこくせんきん","meaning":"một khoảng thời gian ngắn trị giá ngàn vàng; thời gian vô cùng quý giá.\n(Khuyên chúng ta trân trọng từng phút giây trôi qua, không lãng phí thời gian.)","hanviet":"nhất khắc thiên kim","chars":[{"c":"一","h":"nhất"},{"c":"刻","h":"khắc"},{"c":"千","h":"thiên"},{"c":"金","h":"kim"}],"example":"一刻千金の思いで待つ。","example_reading":"いっこくせんきんのおもいでまつ。","example_meaning":"Chờ mà thấy từng khắc quý như vàng.","examples":[{"example":"一刻千金の思いで待つ。","example_reading":"いっこくせんきんのおもいでまつ。","example_meaning":"Chờ mà thấy từng khắc quý như vàng."},{"example":"楽しい時間は一刻千金だ。","example_reading":"たのしいじかんはいっこくせんきんだ。","example_meaning":"Thời gian vui đáng giá ngàn vàng."}],"level":"p2"},
{"word":"一進一退","reading":"いっしんいったい","meaning":"lúc tiến lúc lùi; tình thế giằng co chưa có bên nào thắng thế rõ rệt.\n(Mô tả sự kiên trì trong các cuộc thi đấu hoặc quá trình hồi phục bệnh tật.)","hanviet":"nhất tiến nhất thoái","chars":[{"c":"一","h":"nhất"},{"c":"進","h":"tiến"},{"c":"一","h":"nhất"},{"c":"退","h":"thoái"}],"example":"病状は一進一退だ。","example_reading":"びょうじょうはいっしんいったいだ。","example_meaning":"Bệnh lúc tốt lúc xấu.","examples":[{"example":"病状は一進一退だ。","example_reading":"びょうじょうはいっしんいったいだ。","example_meaning":"Bệnh lúc tốt lúc xấu."},{"example":"試合は一進一退だった。","example_reading":"しあいはいっしんいったいだった。","example_meaning":"Trận đấu giằng co."}],"level":"p2"},
{"word":"粉骨砕身","reading":"ふんこつさいしん","meaning":"đập xương nát thịt; dốc hết sức lực, cống hiến quên mình vì sự nghiệp.\n(Sự hy sinh và quyết tâm cao độ để hoàn thành sứ mệnh cao cả.)","hanviet":"phấn cốt toái thân","chars":[{"c":"粉","h":"phấn"},{"c":"骨","h":"cốt"},{"c":"砕","h":"toái"},{"c":"身","h":"thân"}],"example":"粉骨砕身働く。","example_reading":"ふんこつさいしんはたらく。","example_meaning":"Làm việc quên mình.","examples":[{"example":"粉骨砕身働く。","example_reading":"ふんこつさいしんはたらく。","example_meaning":"Làm việc quên mình."},{"example":"粉骨砕身、努力します。","example_reading":"ふんこつさいしん、どりょくします。","example_meaning":"Tôi sẽ nỗ lực hết sức mình."}],"level":"p2"},
{"word":"和洋折衷","reading":"わようせっちゅう","meaning":"pha trộn hài hòa giữa văn hóa Nhật Bản (Hòa) và phương Tây (Dương).\n(Sự sáng tạo tinh tế trong ẩm thực, kiến trúc và phong cách sống hiện đại.)","hanviet":"hòa dương chiết trung","chars":[{"c":"和","h":"hòa"},{"c":"洋","h":"dương"},{"c":"折","h":"chiết"},{"c":"衷","h":"trung"}],"example":"和洋折衷の家に住む。","example_reading":"わようせっちゅうのいえにすむ。","example_meaning":"Ở nhà kết hợp Nhật Tây.","examples":[{"example":"和洋折衷の家に住む。","example_reading":"わようせっちゅうのいえにすむ。","example_meaning":"Ở nhà kết hợp Nhật Tây."},{"example":"和洋折衷の料理が出た。","example_reading":"わようせっちゅうのりょうりがでた。","example_meaning":"Món kết hợp Nhật Tây được dọn ra."}],"level":"p2"},
{"word":"威風堂堂","reading":"いふうどうどう","meaning":"dáng vẻ hiên ngang, uy nghiêm và đầy tự tin.\n(Thần thái xuất chúng của người có khí chất và bản lĩnh vững vàng.)","hanviet":"uy phong đường đường","chars":[{"c":"威","h":"uy"},{"c":"風","h":"phong"},{"c":"堂","h":"đường"},{"c":"堂","h":"đường"}],"example":"威風堂堂と行進する。","example_reading":"いふうどうどうとこうしんする。","example_meaning":"Diễu hành oai phong.","examples":[{"example":"威風堂堂と行進する。","example_reading":"いふうどうどうとこうしんする。","example_meaning":"Diễu hành oai phong."},{"example":"威風堂堂とした姿だ。","example_reading":"いふうどうどうとしたすがただ。","example_meaning":"Dáng vẻ oai nghiêm hùng dũng."}],"level":"p2"},
{"word":"意気消沈","reading":"いきしょうちん","meaning":"nản lòng thoái chí, tinh thần sa sút sau thất bại.\n(Cảm xúc tự nhiên khi gặp bế tắc, cần sự động viên để phục hồi năng lượng.)","hanviet":"ý khí tiêu trầm","antonym":"奮起（ふんき）: phấn chấn","antonym_hanviet":"phấn khởi","chars":[{"c":"意","h":"ý"},{"c":"気","h":"khí"},{"c":"消","h":"tiêu"},{"c":"沈","h":"trầm"}],"example":"負けて意気消沈した。","example_reading":"まけていきしょうちんした。","example_meaning":"Thua nên ủ rũ.","examples":[{"example":"負けて意気消沈した。","example_reading":"まけていきしょうちんした。","example_meaning":"Thua nên ủ rũ."},{"example":"彼は意気消沈している。","example_reading":"かれはいきしょうちんしている。","example_meaning":"Anh ấy đang chán nản."}],"level":"p2"},
{"word":"以身作則","reading":"いしんさそく","meaning":"lấy bản thân làm tấm gương cho người khác noi theo.\n(Phương pháp lãnh đạo và giáo dục hiệu quả nhất bằng chính hành động thực tế.)","hanviet":"dĩ thân tác tắc","chars":[{"c":"以","h":"dĩ"},{"c":"身","h":"thân"},{"c":"作","h":"tác"},{"c":"則","h":"tắc"}],"example":"上司が以身作則で示す。","example_reading":"じょうしがいしんさそくでしめす。","example_meaning":"Sếp làm gương cho mọi người.","examples":[{"example":"上司が以身作則で示す。","example_reading":"じょうしがいしんさそくでしめす。","example_meaning":"Sếp làm gương cho mọi người."},{"example":"以身作則の姿勢を見せる。","example_reading":"いしんさそくのしせいをみせる。","example_meaning":"Thể hiện thái độ làm gương."}],"level":"p2"},
{"word":"百折不撓","reading":"ひゃくせつふとう","meaning":"dù trăm lần gian vất vả vẫn không nản lòng, không khuất phục.\n(Ý chí sắt đá vượt qua mọi nghịch cảnh để đi đến đích cuối cùng.)","hanviet":"bách chiết bất nạo","chars":[{"c":"百","h":"bách"},{"c":"折","h":"chiết"},{"c":"不","h":"bất"},{"c":"撓","h":"nạo"}],"example":"百折不撓の精神。","example_reading":"ひゃくせつふとうのせいしん。","example_meaning":"Tinh thần trăm lần ngã không nản.","examples":[{"example":"百折不撓の精神。","example_reading":"ひゃくせつふとうのせいしん。","example_meaning":"Tinh thần trăm lần ngã không nản."},{"example":"百折不撓で夢を追う。","example_reading":"ひゃくせつふとうでゆめをおう。","example_meaning":"Bền bỉ theo đuổi ước mơ."}],"level":"p2"},
{"word":"不撓不屈","reading":"ふとうふくつ","meaning":"bất khuất kiên cường, không chịu khuất phục trước bất kỳ sức mạnh nào.\n(Tinh thần thép của những con người quả cảm bảo vệ lý tưởng.)","hanviet":"bất nạo bất khuất","chars":[{"c":"不","h":"bất"},{"c":"撓","h":"nạo"},{"c":"不","h":"bất"},{"c":"屈","h":"khuất"}],"example":"不撓不屈の闘志。","example_reading":"ふとうふくつのとうし。","example_meaning":"Ý chí chiến đấu bất khuất.","examples":[{"example":"不撓不屈の闘志。","example_reading":"ふとうふくつのとうし。","example_meaning":"Ý chí chiến đấu bất khuất."},{"example":"不撓不屈の精神で戦う。","example_reading":"ふとうふくつのせいしんでたたかう。","example_meaning":"Chiến đấu bằng ý chí bất khuất."}],"level":"p2"},
{"word":"順風満帆","reading":"じゅんぷうまんぱん","meaning":"thuận buồm xuôi gió; mọi việc diễn ra vô cùng thuận lợi, hanh thông.\n(Trạng thái lý tưởng khi công việc hay cuộc sống phát triển mượt mà.)","hanviet":"thuận phong mãn phàm","chars":[{"c":"順","h":"thuận"},{"c":"風","h":"phong"},{"c":"満","h":"mãn"},{"c":"帆","h":"phàm"}],"example":"人生は順風満帆だ。","example_reading":"じんせいはじゅんぷうまんぱんだ。","example_meaning":"Cuộc sống thuận buồm xuôi gió.","examples":[{"example":"人生は順風満帆だ。","example_reading":"じんせいはじゅんぷうまんぱんだ。","example_meaning":"Cuộc sống thuận buồm xuôi gió."},{"example":"順風満帆の船出だ。","example_reading":"じゅんぷうまんぱんのふなでだ。","example_meaning":"Một chuyến khởi hành thuận lợi."}],"level":"p2"},
{"word":"森羅万象","reading":"しんらばんしょう","meaning":"mọi sự vật, hiện tượng tồn tại trong vũ trụ và tự nhiên.\n(Sự bao la, đa dạng và kỳ diệu của thế giới xung quanh chúng ta.)","hanviet":"sâm la vạn tượng","chars":[{"c":"森","h":"sâm"},{"c":"羅","h":"la"},{"c":"万","h":"vạn"},{"c":"象","h":"tượng"}],"example":"森羅万象を研究する。","example_reading":"しんらばんしょうをけんきゅうする。","example_meaning":"Nghiên cứu muôn vật vạn tượng.","examples":[{"example":"森羅万象を研究する。","example_reading":"しんらばんしょうをけんきゅうする。","example_meaning":"Nghiên cứu muôn vật vạn tượng."},{"example":"森羅万象に神が宿る。","example_reading":"しんらばんしょうにかみがやどる。","example_meaning":"Thần linh ngụ trong vạn vật."}],"level":"p2"},
{"word":"切歯扼腕","reading":"せっしやくわん","meaning":"nghiến răng đấm ngực; tiếc nuối và phẫn nộ tột cùng trước thất bại.\n(Cảm xúc cay đắng khi bỏ lỡ cơ hội lớn ngay trong tầm tay.)","hanviet":"thiết xỉ ách uyển","chars":[{"c":"切","h":"thiết"},{"c":"歯","h":"xỉ"},{"c":"扼","h":"ách"},{"c":"腕","h":"uyển"}],"example":"切歯扼腕して悔しがる。","example_reading":"せっしやくわんしてくやしがる。","example_meaning":"Nghiến răng nắm tay tiếc hận.","examples":[{"example":"切歯扼腕して悔しがる。","example_reading":"せっしやくわんしてくやしがる。","example_meaning":"Nghiến răng nắm tay tiếc hận."},{"example":"逃した好機に切歯扼腕した。","example_reading":"にがしたこうきにせっしやくわんした。","example_meaning":"Nghiến răng tiếc cơ hội đã mất."}],"level":"p2"},
{"word":"一目瞭然","reading":"いちもくりょうぜん","meaning":"nhìn một cái là hiểu ngay; rõ ràng như ban ngày không cần giải thích.\n(Sự minh bạch, mạch lạc trong thông tin hoặc kết quả hiện hữu.)","hanviet":"nhất mục liễu nhiên","chars":[{"c":"一","h":"nhất"},{"c":"目","h":"mục"},{"c":"瞭","h":"liễu"},{"c":"然","h":"nhiên"}],"example":"結果は一目瞭然だ。","example_reading":"けっかはいちもくりょうぜんだ。","example_meaning":"Kết quả rõ ràng, nhìn là biết.","examples":[{"example":"結果は一目瞭然だ。","example_reading":"けっかはいちもくりょうぜんだ。","example_meaning":"Kết quả rõ ràng, nhìn là biết."},{"example":"グラフを見れば一目瞭然だ。","example_reading":"グラフをみればいちもくりょうぜんだ。","example_meaning":"Nhìn biểu đồ là rõ ngay."}],"level":"p2"},
{"word":"一喜一憂","reading":"いっきいちゆう","meaning":"lúc vui lúc lo; tâm trạng thay đổi liên tục theo từng diễn biến của sự việc.\n(Dùng khi ai đó bị cảm xúc cuốn theo từng tin tốt, tin xấu mà thiếu sự bình tĩnh.)","hanviet":"nhất hỷ nhất ưu","chars":[{"c":"一","h":"nhất"},{"c":"喜","h":"hỷ"},{"c":"一","h":"nhất"},{"c":"憂","h":"ưu"}],"example":"試験の結果に一喜一憂しても仕方がない。","example_reading":"しけんのけっかにいっきいちゆうしてもしかたがない。","example_meaning":"Có lúc vui lúc lo trước kết quả thi thì cũng chẳng giải quyết được gì.","examples":[{"example":"試験の結果に一喜一憂しても仕方がない。","example_reading":"しけんのけっかにいっきいちゆうしてもしかたがない。","example_meaning":"Có lúc vui lúc lo trước kết quả thi thì cũng chẳng giải quyết được gì."},{"example":"株価の動きに一喜一憂する毎日だ。","example_reading":"かぶかのうごきにいっきいちゆうするまいにちだ。","example_meaning":"Ngày nào cũng lúc mừng lúc lo theo biến động của giá cổ phiếu."}],"level":"p2"},
{"word":"一念発起","reading":"いちねんほっき","meaning":"đột nhiên hạ quyết tâm làm một việc gì đó.\n(Thường dùng khi ai đó thay đổi cuộc sống, bắt đầu học hoặc làm điều mới sau một cú hích về tinh thần.)","hanviet":"nhất niệm phát khởi","chars":[{"c":"一","h":"nhất"},{"c":"念","h":"niệm"},{"c":"発","h":"phát"},{"c":"起","h":"khởi"}],"example":"彼は一念発起して、会社を辞めて留学することにした。","example_reading":"かれはいちねんほっきして、かいしゃをやめてりゅうがくすることにした。","example_meaning":"Anh ấy quyết tâm nghỉ việc để đi du học.","examples":[{"example":"彼は一念発起して、会社を辞めて留学することにした。","example_reading":"かれはいちねんほっきして、かいしゃをやめてりゅうがくすることにした。","example_meaning":"Anh ấy quyết tâm nghỉ việc để đi du học."},{"example":"一念発起してマラソンの練習を始めた。","example_reading":"いちねんほっきしてまらそんのれんしゅうをはじめた。","example_meaning":"Tôi hạ quyết tâm và bắt đầu tập chạy marathon."}],"level":"p2"},
{"word":"四面楚歌","reading":"しめんそか","meaning":"bị bao vây, cô lập tứ phía, không ai giúp đỡ.\n(Điển tích Hạng Vũ bị quân Hán bao vây nghe khắp bốn phía hát điệu nước Sở.)","hanviet":"tứ diện Sở ca","chars":[{"c":"四","h":"tứ"},{"c":"面","h":"diện"},{"c":"楚","h":"Sở"},{"c":"歌","h":"ca"}],"example":"彼は社内で四面楚歌の状態になった。","example_reading":"かれはしゃないでしめんそかのじょうたいになった。","example_meaning":"Anh ấy bị cô lập tứ phía trong công ty.","examples":[{"example":"彼は社内で四面楚歌の状態になった。","example_reading":"かれはしゃないでしめんそかのじょうたいになった。","example_meaning":"Anh ấy bị cô lập tứ phía trong công ty."},{"example":"反対意見ばかりで、まさに四面楚歌だ。","example_reading":"はんたいいけんばかりで、まさにしめんそかだ。","example_meaning":"Toàn là ý kiến phản đối, đúng là bị bao vây tứ phía."}],"level":"p2"},
{"word":"一触即発","reading":"いっしょくそくはつ","meaning":"chạm nhẹ là nổ; tình hình cực kỳ căng thẳng.\n(Dùng cho tình thế nguy hiểm, chỉ một tác động nhỏ cũng dẫn tới xung đột.)","hanviet":"nhất xúc tức phát","chars":[{"c":"一","h":"nhất"},{"c":"触","h":"xúc"},{"c":"即","h":"tức"},{"c":"発","h":"phát"}],"example":"両国は一触即発の状態にある。","example_reading":"りょうこくはいっしょくそくはつのじょうたいにある。","example_meaning":"Hai nước đang ở tình trạng căng thẳng như dây đàn.","examples":[{"example":"両国は一触即発の状態にある。","example_reading":"りょうこくはいっしょくそくはつのじょうたいにある。","example_meaning":"Hai nước đang ở tình trạng căng thẳng như dây đàn."},{"example":"会議室は一触即発の空気に包まれた。","example_reading":"かいぎしつはいっしょくそくはつのくうきにつつまれた。","example_meaning":"Phòng họp bao trùm bầu không khí căng như dây đàn."}],"level":"p2"},
{"word":"我田引水","reading":"がでんいんすい","meaning":"kéo nước về ruộng mình; chỉ nghĩ cho lợi ích của bản thân.\n(Dùng khi ai đó nói hoặc làm việc có lợi cho mình, bỏ qua lẽ phải.)","hanviet":"ngã điền dẫn thủy","chars":[{"c":"我","h":"ngã"},{"c":"田","h":"điền"},{"c":"引","h":"dẫn"},{"c":"水","h":"thủy"}],"example":"彼の意見は我田引水で、納得できない。","example_reading":"かれのいけんはがでんいんすいで、なっとくできない。","example_meaning":"Ý kiến của anh ta chỉ nghĩ cho mình nên tôi không thể đồng tình.","examples":[{"example":"彼の意見は我田引水で、納得できない。","example_reading":"かれのいけんはがでんいんすいで、なっとくできない。","example_meaning":"Ý kiến của anh ta chỉ nghĩ cho mình nên tôi không thể đồng tình."},{"example":"それは我田引水の解釈にすぎない。","example_reading":"それはがでんいんすいのかいしゃくにすぎない。","example_meaning":"Đó chẳng qua là cách giải thích chỉ có lợi cho bản thân."}],"level":"p2"},
{"word":"自暴自棄","reading":"じぼうじき","meaning":"tuyệt vọng buông xuôi, bỏ mặc bản thân.\n(Dùng khi ai đó thất vọng đến mức không còn quan tâm đến tương lai.)","hanviet":"tự bạo tự khí","chars":[{"c":"自","h":"tự"},{"c":"暴","h":"bạo"},{"c":"自","h":"tự"},{"c":"棄","h":"khí"}],"example":"失敗が続いて、彼は自暴自棄になった。","example_reading":"しっぱいがつづいて、かれはじぼうじきになった。","example_meaning":"Thất bại liên tiếp khiến anh ấy buông xuôi.","examples":[{"example":"失敗が続いて、彼は自暴自棄になった。","example_reading":"しっぱいがつづいて、かれはじぼうじきになった。","example_meaning":"Thất bại liên tiếp khiến anh ấy buông xuôi."},{"example":"自暴自棄になってはいけない。","example_reading":"じぼうじきになってはいけない。","example_meaning":"Không được tuyệt vọng buông xuôi."}],"level":"p2"},
{"word":"厚顔無恥","reading":"こうがんむち","meaning":"mặt dày không biết xấu hổ.\n(Dùng để chê người làm việc sai trái mà vẫn thản nhiên, không biết hổ thẹn.)","hanviet":"hậu nhan vô sỉ","chars":[{"c":"厚","h":"hậu"},{"c":"顔","h":"nhan"},{"c":"無","h":"vô"},{"c":"恥","h":"sỉ"}],"example":"約束を破って平気な顔をするとは厚顔無恥だ。","example_reading":"やくそくをやぶってへいきなかおをするとはこうがんむちだ。","example_meaning":"Thất hứa mà vẫn thản nhiên thật là mặt dày không biết xấu hổ.","examples":[{"example":"約束を破って平気な顔をするとは厚顔無恥だ。","example_reading":"やくそくをやぶってへいきなかおをするとはこうがんむちだ。","example_meaning":"Thất hứa mà vẫn thản nhiên thật là mặt dày không biết xấu hổ."},{"example":"彼の厚顔無恥な態度に皆が呆れた。","example_reading":"かれのこうがんむちなたいどにみんながあきれた。","example_meaning":"Mọi người ngán ngẩm trước thái độ trơ trẽn của anh ta."}],"level":"p2"},
{"word":"言語道断","reading":"ごんごどうだん","meaning":"quá tệ đến mức không thể nói nên lời.\n(Dùng để chỉ trích hành vi sai trái nghiêm trọng, không thể chấp nhận.)","hanviet":"ngôn ngữ đạo đoạn","chars":[{"c":"言","h":"ngôn"},{"c":"語","h":"ngữ"},{"c":"道","h":"đạo"},{"c":"断","h":"đoạn"}],"example":"約束を破るなんて言語道断だ。","example_reading":"やくそくをやぶるなんてごんごどうだんだ。","example_meaning":"Thất hứa như vậy thật là không thể chấp nhận được.","examples":[{"example":"約束を破るなんて言語道断だ。","example_reading":"やくそくをやぶるなんてごんごどうだんだ。","example_meaning":"Thất hứa như vậy thật là không thể chấp nhận được."},{"example":"飲酒運転は言語道断の行為だ。","example_reading":"いんしゅうんてんはごんごどうだんのこういだ。","example_meaning":"Lái xe khi uống rượu là hành vi không thể dung thứ."}],"level":"p2"},
{"word":"馬耳東風","reading":"ばじとうふう","meaning":"gió xuân thổi qua tai ngựa; nghe mà làm ngơ, như nước đổ lá khoai.\n(Dùng khi lời khuyên, ý kiến của người khác không lọt vào tai ai đó.)","hanviet":"mã nhĩ đông phong","chars":[{"c":"馬","h":"mã"},{"c":"耳","h":"nhĩ"},{"c":"東","h":"đông"},{"c":"風","h":"phong"}],"example":"いくら注意しても、彼には馬耳東風だ。","example_reading":"いくらちゅういしても、かれにはばじとうふうだ。","example_meaning":"Dù nhắc nhở bao nhiêu thì anh ta cũng làm ngơ.","examples":[{"example":"いくら注意しても、彼には馬耳東風だ。","example_reading":"いくらちゅういしても、かれにはばじとうふうだ。","example_meaning":"Dù nhắc nhở bao nhiêu thì anh ta cũng làm ngơ."},{"example":"私の忠告は馬耳東風で聞き流された。","example_reading":"わたしのちゅうこくはばじとうふうでききながされた。","example_meaning":"Lời khuyên của tôi bị bỏ ngoài tai."}],"level":"p2"},
{"word":"付和雷同","reading":"ふわらいどう","meaning":"theo số đông một cách mù quáng, không có chính kiến.\n(Dùng chê người chỉ biết nghe theo ý kiến người khác mà không tự suy nghĩ.)","hanviet":"phụ hòa lôi đồng","chars":[{"c":"付","h":"phụ"},{"c":"和","h":"hòa"},{"c":"雷","h":"lôi"},{"c":"同","h":"đồng"}],"example":"付和雷同せず、自分の意見を持とう。","example_reading":"ふわらいどうせず、じぶんのいけんをもとう。","example_meaning":"Đừng a dua theo người khác, hãy có chính kiến của mình.","examples":[{"example":"付和雷同せず、自分の意見を持とう。","example_reading":"ふわらいどうせず、じぶんのいけんをもとう。","example_meaning":"Đừng a dua theo người khác, hãy có chính kiến của mình."},{"example":"彼は付和雷同する性格だ。","example_reading":"かれはふわらいどうするせいかくだ。","example_meaning":"Anh ấy có tính hay a dua theo số đông."}],"level":"p2"},
{"word":"悠々自適","reading":"ゆうゆうじてき","meaning":"sống thong dong, tự tại theo ý mình.\n(Thường dùng cho cuộc sống nhàn nhã, thoải mái sau khi về hưu.)","hanviet":"du du tự thích","chars":[{"c":"悠","h":"du"},{"c":"々","h":"du"},{"c":"自","h":"tự"},{"c":"適","h":"thích"}],"example":"退職後は田舎で悠々自適の生活を送っている。","example_reading":"たいしょくごはいなかでゆうゆうじてきのせいかつをおくっている。","example_meaning":"Sau khi nghỉ hưu, ông sống thong dong ở vùng quê.","examples":[{"example":"退職後は田舎で悠々自適の生活を送っている。","example_reading":"たいしょくごはいなかでゆうゆうじてきのせいかつをおくっている。","example_meaning":"Sau khi nghỉ hưu, ông sống thong dong ở vùng quê."},{"example":"彼は定年後、悠々自適に暮らしている。","example_reading":"かれはていねんご、ゆうゆうじてきにくらしている。","example_meaning":"Sau tuổi nghỉ hưu, ông ấy sống nhàn nhã, tự tại."}],"level":"p2"},
{"word":"主客転倒","reading":"しゅかくてんとう","meaning":"đảo lộn chính phụ, chủ khách.\n(Dùng khi cái phụ lại được coi trọng hơn cái chính.)","hanviet":"chủ khách chuyển đảo","chars":[{"c":"主","h":"chủ"},{"c":"客","h":"khách"},{"c":"転","h":"chuyển"},{"c":"倒","h":"đảo"}],"example":"手段が目的になるのは主客転倒だ。","example_reading":"しゅだんがもくてきになるのはしゅかくてんとうだ。","example_meaning":"Biến phương tiện thành mục đích là đảo lộn chính phụ.","examples":[{"example":"手段が目的になるのは主客転倒だ。","example_reading":"しゅだんがもくてきになるのはしゅかくてんとうだ。","example_meaning":"Biến phương tiện thành mục đích là đảo lộn chính phụ."},{"example":"宣伝にお金をかけすぎて商品が疎かでは主客転倒だ。","example_reading":"せんでんにおかねをかけすぎてしょうひんがおろそかではしゅかくてんとうだ。","example_meaning":"Chi quá nhiều cho quảng cáo mà bỏ bê sản phẩm là đảo lộn chính phụ."}],"level":"p2"},
{"word":"開口一番","reading":"かいこういちばん","meaning":"vừa mở miệng đã nói ngay (điều gì đó).\n(Dùng khi câu đầu tiên người ta thốt ra lại là một nội dung đặc biệt.)","hanviet":"khai khẩu nhất phiên","chars":[{"c":"開","h":"khai"},{"c":"口","h":"khẩu"},{"c":"一","h":"nhất"},{"c":"番","h":"phiên"}],"example":"彼は開口一番、謝罪の言葉を述べた。","example_reading":"かれはかいこういちばん、しゃざいのことばをのべた。","example_meaning":"Vừa mở miệng, anh ấy đã nói lời xin lỗi.","examples":[{"example":"彼は開口一番、謝罪の言葉を述べた。","example_reading":"かれはかいこういちばん、しゃざいのことばをのべた。","example_meaning":"Vừa mở miệng, anh ấy đã nói lời xin lỗi."},{"example":"開口一番「お疲れ様」と声をかけてくれた。","example_reading":"かいこういちばん「おつかれさま」とこえをかけてくれた。","example_meaning":"Vừa mở lời, anh ấy đã chào hỏi tôi một câu \"vất vả rồi\"."}],"level":"p2"},
{"word":"隠忍自重","reading":"いんにんじちょう","meaning":"nhẫn nhịn chịu đựng và thận trọng giữ mình.\n(Dùng khi kiềm chế cảm xúc, chờ thời cơ thay vì hành động bồng bột.)","hanviet":"ẩn nhẫn tự trọng","chars":[{"c":"隠","h":"ẩn"},{"c":"忍","h":"nhẫn"},{"c":"自","h":"tự"},{"c":"重","h":"trọng"}],"example":"彼は隠忍自重して、機会を待った。","example_reading":"かれはいんにんじちょうして、きかいをまった。","example_meaning":"Anh ấy nhẫn nhịn, thận trọng chờ thời cơ.","examples":[{"example":"彼は隠忍自重して、機会を待った。","example_reading":"かれはいんにんじちょうして、きかいをまった。","example_meaning":"Anh ấy nhẫn nhịn, thận trọng chờ thời cơ."},{"example":"今は隠忍自重の時だ。","example_reading":"いまはいんにんじちょうのときだ。","example_meaning":"Bây giờ là lúc cần nhẫn nhịn và thận trọng."}],"level":"p2"},
{"word":"喜色満面","reading":"きしょくまんめん","meaning":"gương mặt rạng rỡ niềm vui.\n(Dùng khi niềm vui hiện rõ trên cả khuôn mặt.)","hanviet":"hỉ sắc mãn diện","chars":[{"c":"喜","h":"hỉ"},{"c":"色","h":"sắc"},{"c":"満","h":"mãn"},{"c":"面","h":"diện"}],"example":"合格を知って、彼は喜色満面だった。","example_reading":"ごうかくをしって、かれはきしょくまんめんだった。","example_meaning":"Biết tin đậu, anh ấy mặt mày hớn hở.","examples":[{"example":"合格を知って、彼は喜色満面だった。","example_reading":"ごうかくをしって、かれはきしょくまんめんだった。","example_meaning":"Biết tin đậu, anh ấy mặt mày hớn hở."},{"example":"喜色満面で子どもたちが帰ってきた。","example_reading":"きしょくまんめんでこどもたちがかえってきた。","example_meaning":"Lũ trẻ trở về với gương mặt rạng rỡ niềm vui."}],"level":"p2"},
{"word":"一騎当千","reading":"いっきとうせん","meaning":"một người địch nổi nghìn người.\n(Dùng khen người có sức mạnh, năng lực vượt trội hơn hẳn người thường.)","hanviet":"nhất kỵ đương thiên","chars":[{"c":"一","h":"nhất"},{"c":"騎","h":"kỵ"},{"c":"当","h":"đương"},{"c":"千","h":"thiên"}],"example":"彼は一騎当千の働きでチームを勝利に導いた。","example_reading":"かれはいっきとうせんのはたらきでちーむをしょうりにみちびいた。","example_meaning":"Anh ấy lập công lớn, dẫn đội đến chiến thắng.","examples":[{"example":"彼は一騎当千の働きでチームを勝利に導いた。","example_reading":"かれはいっきとうせんのはたらきでちーむをしょうりにみちびいた。","example_meaning":"Anh ấy lập công lớn, dẫn đội đến chiến thắng."},{"example":"このチームには一騎当千の選手が揃っている。","example_reading":"このちーむにはいっきとうせんのせんしゅがそろっている。","example_meaning":"Đội này quy tụ những tuyển thủ một người địch nghìn người."}],"level":"p2"},
{"word":"無味乾燥","reading":"むみかんそう","meaning":"khô khan, nhạt nhẽo, thiếu hứng thú.\n(Dùng cho văn bản, bài nói chuyện hay công việc thiếu sinh khí.)","hanviet":"vô vị can táo","chars":[{"c":"無","h":"vô"},{"c":"味","h":"vị"},{"c":"乾","h":"can"},{"c":"燥","h":"táo"}],"example":"無味乾燥な報告書で読む気がしなかった。","example_reading":"むみかんそうなほうこくしょでよむきがしなかった。","example_meaning":"Bản báo cáo khô khan nên tôi chẳng muốn đọc.","examples":[{"example":"無味乾燥な報告書で読む気がしなかった。","example_reading":"むみかんそうなほうこくしょでよむきがしなかった。","example_meaning":"Bản báo cáo khô khan nên tôi chẳng muốn đọc."},{"example":"単純作業ばかりで、毎日が無味乾燥だ。","example_reading":"たんじゅんさぎょうばかりで、まいにちがむみかんそうだ。","example_meaning":"Toàn việc đơn điệu nên mỗi ngày trôi qua thật nhạt nhẽo."}],"level":"p2"},
{"word":"率先垂範","reading":"そっせんすいはん","meaning":"đi đầu làm gương cho người khác.\n(Dùng để nói người lãnh đạo tự mình hành động trước để nêu gương.)","hanviet":"suất tiên thùy phạm","chars":[{"c":"率","h":"suất"},{"c":"先","h":"tiên"},{"c":"垂","h":"thùy"},{"c":"範","h":"phạm"}],"example":"部長が率先垂範して掃除を始めた。","example_reading":"ぶちょうがそっせんすいはんしてそうじをはじめた。","example_meaning":"Trưởng phòng đi đầu làm gương, bắt đầu quét dọn.","examples":[{"example":"部長が率先垂範して掃除を始めた。","example_reading":"ぶちょうがそっせんすいはんしてそうじをはじめた。","example_meaning":"Trưởng phòng đi đầu làm gương, bắt đầu quét dọn."},{"example":"リーダーは率先垂範することが大切だ。","example_reading":"りーだーはそっせんすいはんすることがたいせつだ。","example_meaning":"Người lãnh đạo cần làm gương đi đầu."}],"level":"p2"},
{"word":"大義名分","reading":"たいぎめいぶん","meaning":"lý do chính đáng, danh nghĩa hành động.\n(Dùng khi nêu lý do hợp lý để biện minh cho một hành động.)","hanviet":"đại nghĩa danh phận","chars":[{"c":"大","h":"đại"},{"c":"義","h":"nghĩa"},{"c":"名","h":"danh"},{"c":"分","h":"phận"}],"example":"彼は大義名分を掲げて改革を進めた。","example_reading":"かれはたいぎめいぶんをかかげてかいかくをすすめた。","example_meaning":"Anh ấy nêu cao danh nghĩa chính đáng để thúc đẩy cải cách.","examples":[{"example":"彼は大義名分を掲げて改革を進めた。","example_reading":"かれはたいぎめいぶんをかかげてかいかくをすすめた。","example_meaning":"Anh ấy nêu cao danh nghĩa chính đáng để thúc đẩy cải cách."},{"example":"戦争をする大義名分はどこにもない。","example_reading":"せんそうをするたいぎめいぶんはどこにもない。","example_meaning":"Không có lý do chính đáng nào để gây chiến tranh."}],"level":"p2"},
{"word":"不眠不休","reading":"ふみんふきゅう","meaning":"không ngủ không nghỉ.\n(Dùng khi làm việc liên tục, nỗ lực hết sức trong thời gian dài.)","hanviet":"bất miên bất hưu","chars":[{"c":"不","h":"bất"},{"c":"眠","h":"miên"},{"c":"不","h":"bất"},{"c":"休","h":"hưu"}],"example":"救助隊は不眠不休で捜索を続けた。","example_reading":"きゅうじょたいはふみんふきゅうでそうさくをつづけた。","example_meaning":"Đội cứu hộ tìm kiếm không ngủ không nghỉ.","examples":[{"example":"救助隊は不眠不休で捜索を続けた。","example_reading":"きゅうじょたいはふみんふきゅうでそうさくをつづけた。","example_meaning":"Đội cứu hộ tìm kiếm không ngủ không nghỉ."},{"example":"不眠不休で働いて、ようやく完成した。","example_reading":"ふみんふきゅうではたらいて、ようやくかんせいした。","example_meaning":"Làm việc không ngủ không nghỉ, cuối cùng cũng hoàn thành."}],"level":"p2"},
{"word":"慇懃無礼","reading":"いんぎんぶれい","meaning":"bề ngoài lịch sự nhưng thực chất khinh thường, vô lễ.\n(Dùng khi thái độ quá khách sáo nhưng ngầm ẩn sự coi thường người khác.)","hanviet":"ân cần vô lễ","chars":[{"c":"慇","h":"ân"},{"c":"懃","h":"cần"},{"c":"無","h":"vô"},{"c":"礼","h":"lễ"}],"example":"丁寧すぎる彼の態度は、かえって慇懃無礼に感じられた。","example_reading":"ていねいすぎるかれのたいどは、かえっていんぎんぶれいにかんじられた。","example_meaning":"Thái độ quá lịch sự của anh ta lại khiến tôi thấy giả tạo, thiếu tôn trọng.","examples":[{"example":"丁寧すぎる彼の態度は、かえって慇懃無礼に感じられた。","example_reading":"ていねいすぎるかれのたいどは、かえっていんぎんぶれいにかんじられた。","example_meaning":"Thái độ quá lịch sự của anh ta lại khiến tôi thấy giả tạo, thiếu tôn trọng."},{"example":"慇懃無礼な対応に腹が立った。","example_reading":"いんぎんぶれいなたいおうにはらがたった。","example_meaning":"Tôi tức giận trước cách ứng xử lịch sự giả tạo."}],"level":"p2"},
{"word":"疑心暗鬼","reading":"ぎしんあんき","meaning":"thần cây đa, ma cây đề; nghi thần nghi quỷ, lòng sinh nghi ngờ thì nhìn đâu cũng thấy đáng sợ.\n(Tâm lý bất an khiến con tự tưởng tượng ra nguy hiểm không có thật.)","hanviet":"nghi tâm ám quỷ","note":"Từ câu «疑心生暗鬼», gắn với chuyện mất rìu trong Liệt Tử: nghi người thì thấy ai cũng giống kẻ trộm.","chars":[{"c":"疑","h":"nghi"},{"c":"心","h":"tâm"},{"c":"暗","h":"ám"},{"c":"鬼","h":"quỷ"}],"poem":{"han":"疑雲一起生幽影／風動枯枝亦是魔","hv":"Nghi vân nhất khởi sinh u ảnh / Phong động khô chi diệc thị ma","vi":"Mây nghi vừa nổi sinh bóng tối, gió lay cành khô cũng ngỡ là ma."},"example":"うわさを聞いて、疑心暗鬼になった。","example_reading":"うわさをきいて、ぎしんあんきになった。","example_meaning":"Nghe tin đồn xong tôi sinh ra nghi ngờ mọi thứ.","examples":[{"example":"うわさを聞いて、疑心暗鬼になった。","example_reading":"うわさをきいて、ぎしんあんきになった。","example_meaning":"Nghe tin đồn xong tôi sinh ra nghi ngờ mọi thứ."},{"example":"一度ウソをつかれてから、彼は疑心暗鬼になった。","example_reading":"いちどウソをつかれてから、かれはぎしんあんきになった。","example_meaning":"Từ khi bị nói dối một lần, anh ấy sinh ra nghi ngờ mọi thứ."}],"level":"p3"},
{"word":"異口同音","reading":"いくどうおん","meaning":"mười người như một, đồng thanh một lời, cùng chung ý kiến.\n(Sự thống nhất cao độ về quan điểm mà không cần bàn bạc trước.)","hanviet":"dị khẩu đồng âm","note":"異口 = nhiều miệng khác nhau, 同音 = cùng một giọng. Dùng khi ý kiến cả nhóm giống hệt nhau.","chars":[{"c":"異","h":"dị"},{"c":"口","h":"khẩu"},{"c":"同","h":"đồng"},{"c":"音","h":"âm"}],"poem":{"han":"千口一聲歸一理／萬人同調和東風","hv":"Thiên khẩu nhất thanh quy nhất lý / Vạn nhân đồng điệu họa đông phong","vi":"Nghìn miệng một tiếng về một lẽ, vạn người cùng điệu hòa gió đông."},"example":"全員が異口同音に「賛成です」と答えた。","example_reading":"ぜんいんがいくどうおんに「さんせいです」とこたえた。","example_meaning":"Mọi người đồng thanh trả lời \"Tán thành\".","examples":[{"example":"全員が異口同音に「賛成です」と答えた。","example_reading":"ぜんいんがいくどうおんに「さんせいです」とこたえた。","example_meaning":"Mọi người đồng thanh trả lời \"Tán thành\"."},{"example":"先生の提案に、生徒たちは異口同音に賛成した。","example_reading":"せんせいのていあんに、せいとたちはいくどうおんにさんせいした。","example_meaning":"Học sinh đồng thanh tán thành đề nghị của thầy."}],"level":"p3"},
{"word":"本末転倒","reading":"ほんまつてんとう","meaning":"tráo trở gốc ngọn; nhầm lẫn giữa cái chính và cái phụ.\n(Đánh mất mục tiêu cốt lõi vì quá chú tâm vào những chi tiết không quan trọng.)","hanviet":"bản mạt chuyển đảo","note":"本 = gốc, 末 = ngọn. Lấy ngọn làm gốc, như người bón lá mà bỏ rễ.","chars":[{"c":"本","h":"bản"},{"c":"末","h":"mạt"},{"c":"転","h":"chuyển"},{"c":"倒","h":"đảo"}],"poem":{"han":"澆枝棄根春自盡／捨本求末事難成","hv":"Kiêu chi khí căn xuân tự tận / Xả bản cầu mạt sự nan thành","vi":"Tưới cành bỏ rễ xuân tự tàn, bỏ gốc theo ngọn việc khó thành."},"example":"健康のために働くのに、病気になっては本末転倒だ。","example_reading":"けんこうのためにはたらくのに、びょうきになってはほんまつてんとうだ。","example_meaning":"Làm việc vì sức khỏe mà lại sinh bệnh thì là lộn gốc ngọn.","examples":[{"example":"健康のために働くのに、病気になっては本末転倒だ。","example_reading":"けんこうのためにはたらくのに、びょうきになってはほんまつてんとうだ。","example_meaning":"Làm việc vì sức khỏe mà lại sinh bệnh thì là lộn gốc ngọn."},{"example":"安さを求めて何度も買い直すのは、本末転倒だ。","example_reading":"やすさをもとめてなんどもかいなおすのは、ほんまつてんとうだ。","example_meaning":"Ham rẻ rồi phải mua lại nhiều lần thì là lộn gốc ngọn."}],"level":"p3"},
{"word":"完全無欠","reading":"かんぜんむけつ","meaning":"hoàn hảo không một vết xước, vẹn toàn không chút khuyết điểm.\n(Đạt đến tiêu chuẩn tối cao về sự trọn vẹn và hoàn mỹ.)","hanviet":"hoàn toàn vô khuyết","note":"無欠 gợi «金甌無缺»: chiếc âu vàng không một vết sứt. Thường dùng phủ định: 完全無欠な人はいない.","chars":[{"c":"完","h":"hoàn"},{"c":"全","h":"toàn"},{"c":"無","h":"vô"},{"c":"欠","h":"khuyết"}],"poem":{"han":"金甌無缺光如月／白璧無瑕潔似冰","hv":"Kim âu vô khuyết quang như nguyệt / Bạch bích vô hà khiết tự băng","vi":"Âu vàng không sứt sáng như trăng, ngọc trắng không tì trong tựa băng."},"example":"完全無欠な人間はいない。","example_reading":"かんぜんむけつなにんげんはいない。","example_meaning":"Không có ai hoàn hảo tuyệt đối.","examples":[{"example":"完全無欠な人間はいない。","example_reading":"かんぜんむけつなにんげんはいない。","example_meaning":"Không có ai hoàn hảo tuyệt đối."},{"example":"完全無欠のチームなんて存在しない。","example_reading":"かんぜんむけつのチームなんてそんざいしない。","example_meaning":"Không hề có đội nào hoàn hảo tuyệt đối."}],"level":"p3"},
{"word":"自問自答","reading":"じもんじとう","meaning":"tự hỏi tự trả lời; tự trăn trở suy ngẫm trong lòng.\n(Quá trình nội tâm tự đối thoại để tìm ra sự thật hoặc quyết định.)","hanviet":"tự vấn tự đáp","note":"自問 = tự hỏi, 自答 = tự đáp. Như người đối bóng dưới trăng, hỏi lòng mình rồi tự trả lời.","chars":[{"c":"自","h":"tự"},{"c":"問","h":"vấn"},{"c":"自","h":"tự"},{"c":"答","h":"đáp"}],"poem":{"han":"對影問心心答影／一燈孤坐至天明","hv":"Đối ảnh vấn tâm tâm đáp ảnh / Nhất đăng cô tọa chí thiên minh","vi":"Đối bóng hỏi lòng, lòng đáp bóng, một ngọn đèn ngồi lẻ đến sáng."},"example":"これでいいのかと、自問自答を繰り返した。","example_reading":"これでいいのかと、じもんじとうをくりかえした。","example_meaning":"Tôi cứ tự hỏi liệu thế này có ổn không.","examples":[{"example":"これでいいのかと、自問自答を繰り返した。","example_reading":"これでいいのかと、じもんじとうをくりかえした。","example_meaning":"Tôi cứ tự hỏi liệu thế này có ổn không."},{"example":"進路について、毎晩自問自答している。","example_reading":"しんろについて、まいばんじもんじとうしている。","example_meaning":"Về hướng đi tương lai, tối nào tôi cũng tự hỏi tự đáp."}],"level":"p3"},
{"word":"質実剛健","reading":"しつじつごうけん","meaning":"giản dị, chân thành nhưng vô cùng mạnh mẽ và kiên cường.\n(Vẻ đẹp của sự khiêm tốn kết hợp với ý chí và sức mạnh nội tại.)","hanviet":"chất thực cương kiện","note":"質 = mộc mạc, 実 = thật, 剛 = cứng, 健 = khỏe. Hay nói về nếp sống, hiệu phong của trường.","chars":[{"c":"質","h":"chất"},{"c":"実","h":"thực"},{"c":"剛","h":"cương"},{"c":"健","h":"kiện"}],"poem":{"han":"布衣粗食心如鐵／瘦骨長松志自堅","hv":"Bố y thô thực tâm như thiết / Sấu cốt trường tùng chí tự kiên","vi":"Áo vải cơm thô lòng như sắt, xương gầy tùng cao chí tự bền."},"example":"この学校は質実剛健の校風で知られている。","example_reading":"このがっこうはしつじつごうけんのこうふうでしられている。","example_meaning":"Trường này nổi tiếng với nếp học giản dị mạnh mẽ.","examples":[{"example":"この学校は質実剛健の校風で知られている。","example_reading":"このがっこうはしつじつごうけんのこうふうでしられている。","example_meaning":"Trường này nổi tiếng với nếp học giản dị mạnh mẽ."},{"example":"質実剛健な暮らしを心がけている。","example_reading":"しつじつごうけんなくらしをこころがけている。","example_meaning":"Tôi chú trọng lối sống giản dị, cứng cỏi."}],"level":"p3"},
{"word":"当意即妙","reading":"とういそくみょう","meaning":"nhanh trí, ứng biến ứng đáp vô cùng tinh tế và hợp cảnh.\n(Sự thông minh, hóm hỉnh xử lý tình huống một cách cực kỳ duyên dáng.)","hanviet":"đương ý tức diệu","note":"当意 = hợp ý lúc đó, 即妙 = lập tức khéo. Hay khen câu đối đáp.","chars":[{"c":"当","h":"đương"},{"c":"意","h":"ý"},{"c":"即","h":"tức"},{"c":"妙","h":"diệu"}],"poem":{"han":"應聲對答如流水／一語偏能解萬愁","hv":"Ứng thanh đối đáp như lưu thủy / Nhất ngữ thiên năng giải vạn sầu","vi":"Nghe tiếng đáp liền như nước chảy, một lời lại giải được vạn sầu."},"example":"彼は当意即妙の返答で場を和ませた。","example_reading":"かれはとういそくみょうのへんとうでばをなごませた。","example_meaning":"Anh ấy đáp khéo, làm không khí dịu lại.","examples":[{"example":"彼は当意即妙の返答で場を和ませた。","example_reading":"かれはとういそくみょうのへんとうでばをなごませた。","example_meaning":"Anh ấy đáp khéo, làm không khí dịu lại."},{"example":"当意即妙なジョークに皆が笑った。","example_reading":"とういそくみょうなジョークにみながわらった。","example_meaning":"Câu đùa ứng khẩu khiến mọi người cười."}],"level":"p3"},
{"word":"温厚篤実","reading":"おんこうとくじつ","meaning":"hiền lành, nhân hậu và thành thực, đáng tin cậy.\n(Tính cách ấm áp, chân thành luôn mang lại cảm giác an tâm cho người khác.)","hanviet":"ôn hậu đốc thực","note":"温 = ấm, 厚 = dày, 篤 = chuyên nhất, 実 = thật. Khen phẩm cách.","chars":[{"c":"温","h":"ôn"},{"c":"厚","h":"hậu"},{"c":"篤","h":"đốc"},{"c":"実","h":"thực"}],"poem":{"han":"春風滿面懷誠實／一諾千金信可憑","hv":"Xuân phong mãn diện hoài thành thực / Nhất nặc thiên kim tín khả bằng","vi":"Mặt như gió xuân, lòng thành thật, một lời nặng nghìn vàng đáng tin."},"example":"温厚篤実な人柄で、誰からも好かれる。","example_reading":"おんこうとくじつなひとがらで、だれからもすかれる。","example_meaning":"Tính hiền hậu chân thành nên ai cũng quý.","examples":[{"example":"温厚篤実な人柄で、誰からも好かれる。","example_reading":"おんこうとくじつなひとがらで、だれからもすかれる。","example_meaning":"Tính hiền hậu chân thành nên ai cũng quý."},{"example":"校長は温厚篤実な先生だ。","example_reading":"こうちょうはおんこうとくじつなせんせいだ。","example_meaning":"Thầy hiệu trưởng là người hiền hậu đáng tin."}],"level":"p3"},
{"word":"破顔一笑","reading":"はがんいっしょう","meaning":"mỉm cười tươi rạng rỡ, khuôn mặt giãn ra rạng ngời niềm vui.\n(Nụ cười tự nhiên, sảng khoái xua tan mọi mệt mỏi hay căng thẳng.)","hanviet":"phá nhan nhất tiếu","note":"破顔 = mặt tươi bung ra. Gần hình ảnh Phật cầm hoa, Ca-diếp mỉm cười.","chars":[{"c":"破","h":"phá"},{"c":"顔","h":"nhan"},{"c":"一","h":"nhất"},{"c":"笑","h":"tiếu"}],"poem":{"han":"愁眉頓展開顏笑／一點春光上面來","hv":"Sầu mi đốn triển khai nhan tiếu / Nhất điểm xuân quang thượng diện lai","vi":"Mày sầu bỗng giãn, mặt bung cười, một chút nắng xuân lên mặt."},"example":"合格の知らせを聞いて、彼は破顔一笑した。","example_reading":"ごうかくのしらせをきいて、かれははがんいっしょうした。","example_meaning":"Nghe tin đỗ, anh ấy bật cười rạng rỡ.","examples":[{"example":"合格の知らせを聞いて、彼は破顔一笑した。","example_reading":"ごうかくのしらせをきいて、かれははがんいっしょうした。","example_meaning":"Nghe tin đỗ, anh ấy bật cười rạng rỡ."},{"example":"孫の顔を見て、祖父は破顔一笑した。","example_reading":"まごのかおをみて、そふははがんいっしょうした。","example_meaning":"Thấy mặt cháu, ông nội cười tươi rói."}],"level":"p3"},
{"word":"山紫水明","reading":"さんしすいめい","meaning":"sơn thủy hữu tình; cảnh sắc thiên nhiên tươi đẹp rực rỡ.\n(Vẻ đẹp tráng lệ, thơ mộng của núi sông đất trời.)","hanviet":"sơn tử thủy minh","note":"紫 = sắc tím lúc chiều, 明 = trong sáng. Tả cảnh sơn thủy.","chars":[{"c":"山","h":"sơn"},{"c":"紫","h":"tử"},{"c":"水","h":"thủy"},{"c":"明","h":"minh"}],"poem":{"han":"遠岫烘霞凝紫翠／清流映日泛明光","hv":"Viễn tụ hồng hà ngưng tử thúy / Thanh lưu ánh nhật phiếm minh quang","vi":"Núi xa ráng đỏ đọng sắc tím biếc, dòng trong ánh nắng nổi sáng lên."},"example":"京都は山紫水明の地として知られる。","example_reading":"きょうとはさんしすいめいのちとしてしられる。","example_meaning":"Kyoto nổi tiếng là vùng núi non thanh tú.","examples":[{"example":"京都は山紫水明の地として知られる。","example_reading":"きょうとはさんしすいめいのちとしてしられる。","example_meaning":"Kyoto nổi tiếng là vùng núi non thanh tú."},{"example":"山紫水明の景色に心が洗われた。","example_reading":"さんしすいめいのけしきにこころがあらわれた。","example_meaning":"Cảnh núi non đẹp làm lòng tôi nhẹ nhõm."}],"level":"p3"},
{"word":"明鏡止水","reading":"めいきょうしすい","meaning":"gương sáng nước trong; tâm trí thanh tĩnh, không một chút gợn sóng hay xao động.\n(Trạng thái bình thản tuyệt đối của tâm hồn khi đứng trước mọi biến cố.)","hanviet":"minh kính chỉ thủy","chars":[{"c":"明","h":"minh"},{"c":"鏡","h":"kính"},{"c":"止","h":"chỉ"},{"c":"水","h":"thủy"}],"example":"明鏡止水の心境だ。","example_reading":"めいきょうしすいのしんきょうだ。","example_meaning":"Tâm cảnh trong lặng như gương.","examples":[{"example":"明鏡止水の心境だ。","example_reading":"めいきょうしすいのしんきょうだ。","example_meaning":"Tâm cảnh trong lặng như gương."},{"example":"明鏡止水の心で臨む。","example_reading":"めいきょうしすいのこころでのぞむ。","example_meaning":"Đối mặt với tâm trí tĩnh lặng."}],"level":"p3"},
{"word":"疾風迅雷","reading":"しっぷうじんらい","meaning":"gió lốc sấm sét; di chuyển hoặc hành động cực kỳ nhanh chóng và mãnh liệt.\n(Sức mạnh bộc phá dữ dội khiến đối thủ không kịp trở tay.)","hanviet":"tật phong tấn lôi","chars":[{"c":"疾","h":"tật"},{"c":"風","h":"phong"},{"c":"迅","h":"tấn"},{"c":"雷","h":"lôi"}],"example":"疾風迅雷の勢いだ。","example_reading":"しっぷうじんらいのいきおいだ。","example_meaning":"Thế nhanh như gió, như sấm.","examples":[{"example":"疾風迅雷の勢いだ。","example_reading":"しっぷうじんらいのいきおいだ。","example_meaning":"Thế nhanh như gió, như sấm."},{"example":"疾風迅雷の攻撃だった。","example_reading":"しっぷうじんらいのこうげきだった。","example_meaning":"Đó là đòn tấn công nhanh như chớp."}],"level":"p3"},
{"word":"臥薪嘗胆","reading":"がしんしょうたん","meaning":"nếm mật nằm gai; chịu đựng gian khổ để nuôi chí lớn trả thù hoặc thành công.\n(Bài học kinh điển về sự nhẫn nại và quyết tâm tích lũy sức mạnh.)","hanviet":"ngọa tân thường đảm","chars":[{"c":"臥","h":"ngọa"},{"c":"薪","h":"tân"},{"c":"嘗","h":"thường"},{"c":"胆","h":"đảm"}],"example":"臥薪嘗胆して復讐を誓う。","example_reading":"がしんしょうたんしてふくしゅうをちかう。","example_meaning":"Chịu khổ thề báo thù.","examples":[{"example":"臥薪嘗胆して復讐を誓う。","example_reading":"がしんしょうたんしてふくしゅうをちかう。","example_meaning":"Chịu khổ thề báo thù."},{"example":"臥薪嘗胆の日々を送る。","example_reading":"がしんしょうたんのひびをおくる。","example_meaning":"Sống những ngày gian khổ chờ cơ hội."}],"level":"p3"},
{"word":"鏡花水月","reading":"きょうかすいげつ","meaning":"hoa trong gương, trăng dưới nước; vẻ đẹp hư ảo, chỉ có thể ngắm nhìn chứ không thể nắm bắt.\n(Triết lý về những điều hão huyền, mộng ảo trong cuộc đời.)","hanviet":"kính hoa thủy nguyệt","chars":[{"c":"鏡","h":"kính"},{"c":"花","h":"hoa"},{"c":"水","h":"thủy"},{"c":"月","h":"nguyệt"}],"example":"鏡花水月のような話だ。","example_reading":"きょうかすいげつのようなはなしだ。","example_meaning":"Chuyện như hoa trong gương, trăng đáy nước.","examples":[{"example":"鏡花水月のような話だ。","example_reading":"きょうかすいげつのようなはなしだ。","example_meaning":"Chuyện như hoa trong gương, trăng đáy nước."},{"example":"彼女の魅力は鏡花水月だ。","example_reading":"かのじょのみりょくはきょうかすいげつだ。","example_meaning":"Sức hút của cô ấy huyền ảo, khó nắm bắt."}],"level":"p3"},
{"word":"泰然自若","reading":"たいぜんじじゃく","meaning":"bình thản tự nhiên, không nao núng trước biến cố hay nguy hiểm.\n(Bản lĩnh ngút ngàn của người lãnh đạo kiệt xuất.)","hanviet":"thái nhiên tự nhược","chars":[{"c":"泰","h":"thái"},{"c":"然","h":"nhiên"},{"c":"自","h":"tự"},{"c":"若","h":"nhược"}],"example":"泰然自若として動じない。","example_reading":"たいぜんじじゃくとしてどうじない。","example_meaning":"Điềm nhiên không nao núng.","examples":[{"example":"泰然自若として動じない。","example_reading":"たいぜんじじゃくとしてどうじない。","example_meaning":"Điềm nhiên không nao núng."},{"example":"泰然自若とした態度だ。","example_reading":"たいぜんじじゃくとしたたいどだ。","example_meaning":"Thái độ điềm tĩnh."}],"level":"p3"},
{"word":"虚心坦懐","reading":"きょしんたんかい","meaning":"lòng không vướng bận, cởi mở tiếp thu ý kiến của người khác mà không thành kiến.\n(Thái độ lắng nghe chân thành để mở rộng tầm nhìn và tri thức.)","hanviet":"hư tâm thản hoài","chars":[{"c":"虚","h":"hư"},{"c":"心","h":"tâm"},{"c":"坦","h":"thản"},{"c":"懐","h":"hoài"}],"example":"虚心坦懐に話し合う。","example_reading":"きょしんたんかいにはなしあう。","example_meaning":"Trao đổi cởi mở không định kiến.","examples":[{"example":"虚心坦懐に話し合う。","example_reading":"きょしんたんかいにはなしあう。","example_meaning":"Trao đổi cởi mở không định kiến."},{"example":"虚心坦懐に意見を聞く。","example_reading":"きょしんたんかいにいけんをきく。","example_meaning":"Lắng nghe ý kiến với tâm thái cởi mở."}],"level":"p3"},
{"word":"孤立無援","reading":"こりつむえん","meaning":"trơ trọi cô độc, không có ai trợ giúp hay ứng cứu.\n(Tình cảnh thử thách sức bền và khả năng tự sinh tự tồn của con người.)","hanviet":"cô lập vô viện","chars":[{"c":"孤","h":"cô"},{"c":"立","h":"lập"},{"c":"無","h":"vô"},{"c":"援","h":"viện"}],"example":"孤立無援で戦った。","example_reading":"こりつむえんでたたかった。","example_meaning":"Chiến đấu cô độc không ai giúp.","examples":[{"example":"孤立無援で戦った。","example_reading":"こりつむえんでたたかった。","example_meaning":"Chiến đấu cô độc không ai giúp."},{"example":"孤立無援の状態だ。","example_reading":"こりつむえんのじょうたいだ。","example_meaning":"Đang ở tình trạng cô lập không ai cứu giúp."}],"level":"p3"},
{"word":"波瀾万丈","reading":"はらんばんじょう","meaning":"sóng gió muôn trùng; cuộc đời đầy thăng trầm, biến cố và tình tiết ly kỳ.\n(Mô tả những hành trình sống giàu trải nghiệm và nhiều cảm xúc.)","hanviet":"ba lan vạn trượng","chars":[{"c":"波","h":"ba"},{"c":"瀾","h":"lan"},{"c":"万","h":"vạn"},{"c":"丈","h":"trượng"}],"example":"波瀾万丈の人生だ。","example_reading":"はらんばんじょうのじんせいだ。","example_meaning":"Cuộc đời nhiều biến cố.","examples":[{"example":"波瀾万丈の人生だ。","example_reading":"はらんばんじょうのじんせいだ。","example_meaning":"Cuộc đời nhiều biến cố."},{"example":"波瀾万丈の物語だ。","example_reading":"はらんばんじょうのものがたりだ。","example_meaning":"Câu chuyện nhiều thăng trầm."}],"level":"p3"},
{"word":"千載一遇","reading":"せんざいいちぐう","meaning":"ngàn năm mới gặp một lần; cơ hội hiếm có vô cùng trong đời.\n(Nhắc nhở ta phải nhanh chóng nắm bắt khi vận may đến.)","hanviet":"thiên tải nhất ngộ","chars":[{"c":"千","h":"thiên"},{"c":"載","h":"tải"},{"c":"一","h":"nhất"},{"c":"遇","h":"ngộ"}],"example":"千載一遇のチャンスだ。","example_reading":"せんざいいちぐうのチャンスだ。","example_meaning":"Cơ hội ngàn năm có một.","examples":[{"example":"千載一遇のチャンスだ。","example_reading":"せんざいいちぐうのチャンスだ。","example_meaning":"Cơ hội ngàn năm có một."},{"example":"千載一遇の機会を逃した。","example_reading":"せんざいいちぐうのきかいをのがした。","example_meaning":"Tôi bỏ lỡ cơ hội ngàn năm có một."}],"level":"p3"},
{"word":"雲外蒼天","reading":"うんがいそうてん","meaning":"sau lớp mây mù là bầu trời xanh thẫm; qua khỏi khó khăn sẽ đến ngày tươi sáng.\n(Thông điệp hy vọng tiếp thêm sức mạnh vượt qua giai đoạn tăm tối.)","hanviet":"vân ngoại thương thiên","chars":[{"c":"雲","h":"vân"},{"c":"外","h":"ngoại"},{"c":"蒼","h":"thương"},{"c":"天","h":"thiên"}],"example":"雲外蒼天を信じて進む。","example_reading":"うんがいそうてんをしんじてすすむ。","example_meaning":"Tin có trời xanh sau mây mà tiến lên.","examples":[{"example":"雲外蒼天を信じて進む。","example_reading":"うんがいそうてんをしんじてすすむ。","example_meaning":"Tin có trời xanh sau mây mà tiến lên."},{"example":"苦しいが雲外蒼天だ。","example_reading":"くるしいがうんがいそうてんだ。","example_meaning":"Dù khổ, sau mây là trời xanh."}],"level":"p3"},
{"word":"天真爛漫","reading":"てんしんらんまん","meaning":"hồn nhiên ngây thơ, tính cách trong sáng tự nhiên không chút giả tạo.\n(Sự đáng yêu và thuần khiết thu hút thiện cảm của mọi người.)","hanviet":"thiên chân lạn mạn","chars":[{"c":"天","h":"thiên"},{"c":"真","h":"chân"},{"c":"爛","h":"lạn"},{"c":"漫","h":"mạn"}],"example":"天真爛漫な笑顔だ。","example_reading":"てんしんらんまんなえがおだ。","example_meaning":"Nụ cười hồn nhiên.","examples":[{"example":"天真爛漫な笑顔だ。","example_reading":"てんしんらんまんなえがおだ。","example_meaning":"Nụ cười hồn nhiên."},{"example":"子どもは天真爛漫だ。","example_reading":"こどもはてんしんらんまんだ。","example_meaning":"Trẻ con hồn nhiên ngây thơ."}],"level":"p3"},
{"word":"乾坤一擲","reading":"けんこんいってき","meaning":"được ăn cả ngã về không; đặt cược tất cả vào một ván cờ quyết định.\n(Hành động mạo hiểm nhưng đầy khí phách vào thời điểm then chốt.)","hanviet":"càn khôn nhất trịch","chars":[{"c":"乾","h":"càn"},{"c":"坤","h":"khôn"},{"c":"一","h":"nhất"},{"c":"擲","h":"trịch"}],"example":"乾坤一擲の勝負に出る。","example_reading":"けんこんいってきのしょうぶにでる。","example_meaning":"Đặt cược một ván sống còn.","examples":[{"example":"乾坤一擲の勝負に出る。","example_reading":"けんこんいってきのしょうぶにでる。","example_meaning":"Đặt cược một ván sống còn."},{"example":"乾坤一擲の大勝負だ。","example_reading":"けんこんいってきのだいしょうぶだ。","example_meaning":"Trận quyết định sinh tử."}],"level":"p3"},
{"word":"百鬼夜行","reading":"ひゃっきやこう","meaning":"trăm quỷ đi đêm; kẻ xấu tung hoành, làm loạn trong bóng tối.\n(Hình ảnh ám chỉ thời kỳ xã hội hỗn loạn, nhiều thành phần xấu hoành hành.)","hanviet":"bách quỷ dạ hành","chars":[{"c":"百","h":"bách"},{"c":"鬼","h":"quỷ"},{"c":"夜","h":"dạ"},{"c":"行","h":"hành"}],"example":"百鬼夜行の絵巻を見る。","example_reading":"ひゃっきやこうのえまきをみる。","example_meaning":"Xem tranh cuộn bách quỷ dạ hành.","examples":[{"example":"百鬼夜行の絵巻を見る。","example_reading":"ひゃっきやこうのえまきをみる。","example_meaning":"Xem tranh cuộn bách quỷ dạ hành."},{"example":"政界は百鬼夜行だ。","example_reading":"せいかいはひゃっきやこうだ。","example_meaning":"Chính giới như bầy quỷ lộng hành."}],"level":"p3"},
{"word":"文武両道","reading":"ぶんぶりょうどう","meaning":"văn võ song toàn; giỏi cả học thuật lẫn thể thao/võ thuật.\n(Hình mẫu phát triển toàn diện cả về trí tuệ lẫn thể chất.)","hanviet":"văn vũ lưỡng đạo","chars":[{"c":"文","h":"văn"},{"c":"武","h":"vũ"},{"c":"両","h":"lưỡng"},{"c":"道","h":"đạo"}],"example":"文武両道を目指す。","example_reading":"ぶんぶりょうどうをめざす。","example_meaning":"Hướng đến vừa văn vừa võ.","examples":[{"example":"文武両道を目指す。","example_reading":"ぶんぶりょうどうをめざす。","example_meaning":"Hướng đến vừa văn vừa võ."},{"example":"彼は文武両道の学生だ。","example_reading":"かれはぶんぶりょうどうのがくせいだ。","example_meaning":"Anh ấy là học sinh giỏi cả văn lẫn võ."}],"level":"p3"},
{"word":"一攫千金","reading":"いっかくせんきん","meaning":"một bước lên mây; kiếm được khoản tiền khổng lồ chỉ trong một lần.\n(Khát vọng làm giàu nhanh chóng nhưng cần cẩn trọng rủi ro đi kèm.)","hanviet":"nhất quặc thiên kim","chars":[{"c":"一","h":"nhất"},{"c":"攫","h":"quặc"},{"c":"千","h":"thiên"},{"c":"金","h":"kim"}],"example":"一攫千金を夢見る。","example_reading":"いっかくせんきんをゆめみる。","example_meaning":"Mơ làm giàu một lần.","examples":[{"example":"一攫千金を夢見る。","example_reading":"いっかくせんきんをゆめみる。","example_meaning":"Mơ làm giàu một lần."},{"example":"一攫千金を狙う。","example_reading":"いっかくせんきんをねらう。","example_meaning":"Nhắm đến việc làm giàu nhanh."}],"level":"p3"},
{"word":"不即不離","reading":"ふそくふり","meaning":"không quá gần gũi cũng không quá xa cách; duy trì khoảng cách vừa phải.\n(Nghệ thuật ứng xử tinh tế trong các mối quan hệ xã hội.)","hanviet":"bất tức bất ly","chars":[{"c":"不","h":"bất"},{"c":"即","h":"tức"},{"c":"不","h":"bất"},{"c":"離","h":"ly"}],"example":"不即不離の関係だ。","example_reading":"ふそくふりのかんけいだ。","example_meaning":"Mối quan hệ không gần không xa.","examples":[{"example":"不即不離の関係だ。","example_reading":"ふそくふりのかんけいだ。","example_meaning":"Mối quan hệ không gần không xa."},{"example":"不即不離の距離を保つ。","example_reading":"ふそくふりのきょりをたもつ。","example_meaning":"Giữ khoảng cách vừa phải."}],"level":"p3"},
{"word":"面従腹背","reading":"めんじゅうふくはい","meaning":"bằng mặt nhưng không bằng lòng; trước mặt tuân phục nhưng sau lưng chống đối.\n(Sự cảnh giác trước những kẻ hai mặt thiếu chân thành.)","hanviet":"diện tòng phúc bối","chars":[{"c":"面","h":"diện"},{"c":"従","h":"tòng"},{"c":"腹","h":"phúc"},{"c":"背","h":"bối"}],"example":"面従腹背の部下だ。","example_reading":"めんじゅうふくはいのぶかだ。","example_meaning":"Cấp dưới ngoài mặt vâng lời, trong lòng chống đối.","examples":[{"example":"面従腹背の部下だ。","example_reading":"めんじゅうふくはいのぶかだ。","example_meaning":"Cấp dưới ngoài mặt vâng lời, trong lòng chống đối."},{"example":"面従腹背は信頼を失う。","example_reading":"めんじゅうふくはいはしんらいをうしなう。","example_meaning":"Ngoài thuận trong nghịch thì mất lòng tin."}],"level":"p3"},
{"word":"竜頭蛇尾","reading":"りゅうとうだび","meaning":"đầu rồng đuôi rắn; lúc đầu hoành tráng nhưng kết thúc lại hời hợt, thất vọng.\n(Bài học về sự kiên trì giữ vững phong độ từ đầu đến cuối.)","hanviet":"long đầu xà vĩ","chars":[{"c":"竜","h":"long"},{"c":"頭","h":"đầu"},{"c":"蛇","h":"xà"},{"c":"尾","h":"vĩ"}],"example":"竜頭蛇尾に終わった。","example_reading":"りゅうとうだびにおわった。","example_meaning":"Kết thúc đầu voi đuôi chuột.","examples":[{"example":"竜頭蛇尾に終わった。","example_reading":"りゅうとうだびにおわった。","example_meaning":"Kết thúc đầu voi đuôi chuột."},{"example":"計画は竜頭蛇尾だった。","example_reading":"けいかくはりゅうとうだびだった。","example_meaning":"Kế hoạch đầu voi đuôi chuột."}],"level":"p3"},
{"word":"一長一短","reading":"いっちょういったん","meaning":"ai hay cái gì cũng có điểm mạnh và điểm yếu riêng.\n(Cái nhìn toàn diện, biết chấp nhận cả ưu điểm lẫn khuyết điểm.)","hanviet":"nhất trưởng nhất đoản","chars":[{"c":"一","h":"nhất"},{"c":"長","h":"trưởng"},{"c":"一","h":"nhất"},{"c":"短","h":"đoản"}],"example":"一長一短がある。","example_reading":"いっちょういったんがある。","example_meaning":"Có ưu có nhược.","examples":[{"example":"一長一短がある。","example_reading":"いっちょういったんがある。","example_meaning":"Có ưu có nhược."},{"example":"どの案も一長一短だ。","example_reading":"どのあんもいっちょういったんだ。","example_meaning":"Phương án nào cũng có ưu nhược."}],"level":"p3"},
{"word":"和魂洋才","reading":"わこんようさい","meaning":"tinh thần Nhật Bản kết hợp với tri thức/kỹ thuật phương Tây.\n(Tư duy học hỏi tinh hoa thế giới nhưng vẫn giữ vững bản sắc dân tộc.)","hanviet":"hòa hồn dương tài","chars":[{"c":"和","h":"hòa"},{"c":"魂","h":"hồn"},{"c":"洋","h":"dương"},{"c":"才","h":"tài"}],"example":"和魂洋才を重んじる。","example_reading":"わこんようさいをおもんじる。","example_meaning":"Coi trọng hồn Nhật tài Tây.","examples":[{"example":"和魂洋才を重んじる。","example_reading":"わこんようさいをおもんじる。","example_meaning":"Coi trọng hồn Nhật tài Tây."},{"example":"明治は和魂洋才の時代だ。","example_reading":"めいじはわこんようさいのじだいだ。","example_meaning":"Minh Trị là thời hồn Nhật tài Tây."}],"level":"p3"},
{"word":"巧言令色","reading":"こうげんれいしょく","meaning":"khéo nói uốn lưỡi, nịnh hót bề ngoài để lấy lòng người khác.\n(Lời nhắc nhở về những lời xảo ngôn thiếu tính chân thực.)","hanviet":"xảo ngôn lệnh sắc","chars":[{"c":"巧","h":"xảo"},{"c":"言","h":"ngôn"},{"c":"令","h":"lệnh"},{"c":"色","h":"sắc"}],"example":"巧言令色を警戒する。","example_reading":"こうげんれいしょくをけいかいする。","example_meaning":"Cảnh giác với kẻ nói khéo lấy lòng.","examples":[{"example":"巧言令色を警戒する。","example_reading":"こうげんれいしょくをけいかいする。","example_meaning":"Cảnh giác với kẻ nói khéo lấy lòng."},{"example":"巧言令色の人は信用できない。","example_reading":"こうげんれいしょくのひとはしんようできない。","example_meaning":"Người nói khéo ra vẻ thì không đáng tin."}],"level":"p3"},
{"word":"才色兼備","reading":"さいしょくけんび","meaning":"tài sắc vẹn toàn; vừa thông minh giỏi giang vừa có vẻ đẹp xinh xắn.\n(Vẻ đẹp toàn diện của người phụ nữ hiện đại.)","hanviet":"tài sắc kiêm bị","chars":[{"c":"才","h":"tài"},{"c":"色","h":"sắc"},{"c":"兼","h":"kiêm"},{"c":"備","h":"bị"}],"example":"才色兼備の女性だ。","example_reading":"さいしょくけんびのじょせいだ。","example_meaning":"Người phụ nữ tài sắc vẹn toàn.","examples":[{"example":"才色兼備の女性だ。","example_reading":"さいしょくけんびのじょせいだ。","example_meaning":"Người phụ nữ tài sắc vẹn toàn."},{"example":"彼女は才色兼備だ。","example_reading":"かのじょはさいしょくけんびだ。","example_meaning":"Cô ấy tài sắc vẹn toàn."}],"level":"p3"},
{"word":"不老不死","reading":"ふろうふし","meaning":"trường sinh bất lão; không già đi và không bao giờ chết.\n(Ước mơ ngàn đời của con người về sự trường tồn vĩnh cửu.)","hanviet":"bất lão bất tử","chars":[{"c":"不","h":"bất"},{"c":"老","h":"lão"},{"c":"不","h":"bất"},{"c":"死","h":"tử"}],"example":"不老不死を願う。","example_reading":"ふろうふしをねがう。","example_meaning":"Mong muốn bất tử.","examples":[{"example":"不老不死を願う。","example_reading":"ふろうふしをねがう。","example_meaning":"Mong muốn bất tử."},{"example":"不老不死の薬は存在しない。","example_reading":"ふろうふしのくすりはそんざいしない。","example_meaning":"Không có thuốc trường sinh bất tử."}],"level":"p3"},
{"word":"安分守己","reading":"あんぶんしゅき","meaning":"hài lòng với hiện tại, giữ mình đúng mực không tham vọng viển vông.\n(Triết lý sống bình yên, biết đủ là hạnh phúc.)","hanviet":"an phận thủ kỷ","chars":[{"c":"安","h":"an"},{"c":"分","h":"phận"},{"c":"守","h":"thủ"},{"c":"己","h":"kỷ"}],"example":"安分守己の生活を送る。","example_reading":"あんぶんしゅきのせいかつをおくる。","example_meaning":"Sống cuộc sống an phận giữ mình.","examples":[{"example":"安分守己の生活を送る。","example_reading":"あんぶんしゅきのせいかつをおくる。","example_meaning":"Sống cuộc sống an phận giữ mình."},{"example":"安分守己を心がける。","example_reading":"あんぶんしゅきをこころがける。","example_meaning":"Tâm niệm an phận giữ mình."}],"level":"p3"},
{"word":"暗中模索","reading":"あんちゅうもさく","meaning":"mò mẫm trong bóng tối; tìm tòi giải pháp khi chưa có phương hướng hay manh mối rõ ràng.\n(Mô tả giai đoạn thử nghiệm ban đầu của một dự án mới, khi chưa ai biết đâu là đáp án đúng.)","hanviet":"ám trung mô sách","chars":[{"c":"暗","h":"ám"},{"c":"中","h":"trung"},{"c":"模","h":"mô"},{"c":"索","h":"sách"}],"example":"新しい事業は暗中模索の状態が続いている。","example_reading":"あたらしいじぎょうはあんちゅうもさくのじょうたいがつづいている。","example_meaning":"Việc kinh doanh mới vẫn đang trong tình trạng mò mẫm.","examples":[{"example":"新しい事業は暗中模索の状態が続いている。","example_reading":"あたらしいじぎょうはあんちゅうもさくのじょうたいがつづいている。","example_meaning":"Việc kinh doanh mới vẫn đang trong tình trạng mò mẫm."},{"example":"暗中模索しながら、ようやく解決の糸口を見つけた。","example_reading":"あんちゅうもさくしながら、ようやくかいけつのいとぐちをみつけた。","example_meaning":"Vừa mò mẫm tìm đường, cuối cùng tôi cũng thấy được manh mối giải quyết."}],"level":"p3"},
{"word":"夜郎自大","reading":"やろうじだい","meaning":"ếch ngồi đáy giếng, tự cao tự đại vì không biết thế giới rộng lớn.\n(Điển tích nước Dạ Lang nhỏ bé nhưng tự cho mình là lớn nhất; dùng chê người kiêu ngạo hẹp hòi.)","hanviet":"dạ lang tự đại","chars":[{"c":"夜","h":"dạ"},{"c":"郎","h":"lang"},{"c":"自","h":"tự"},{"c":"大","h":"đại"}],"example":"彼は夜郎自大で、他人の意見を聞こうとしない。","example_reading":"かれはやろうじだいで、たにんのいけんをきこうとしない。","example_meaning":"Anh ta tự cao tự đại, không chịu nghe ý kiến người khác.","examples":[{"example":"彼は夜郎自大で、他人の意見を聞こうとしない。","example_reading":"かれはやろうじだいで、たにんのいけんをきこうとしない。","example_meaning":"Anh ta tự cao tự đại, không chịu nghe ý kiến người khác."},{"example":"世界を知らず夜郎自大になってはいけない。","example_reading":"せかいをしらずやろうじだいになってはいけない。","example_meaning":"Không được vì thiếu hiểu biết về thế giới mà tự cao tự đại."}],"level":"p3"},
{"word":"朝三暮四","reading":"ちょうさんぼし","meaning":"chỉ lo cái lợi trước mắt mà không thấy kết quả giống nhau; bị lừa bởi lời nói khéo.\n(Điển tích người nuôi khỉ đổi cách chia hạt dẻ; còn chỉ việc đổi cách nói mà thực chất không đổi.)","hanviet":"triêu tam mộ tứ","chars":[{"c":"朝","h":"triêu"},{"c":"三","h":"tam"},{"c":"暮","h":"mộ"},{"c":"四","h":"tứ"}],"example":"小さな違いにこだわるのは朝三暮四だ。","example_reading":"ちいさなちがいにこだわるのはちょうさんぼしだ。","example_meaning":"Câu nệ vào khác biệt nhỏ nhặt thì chỉ là triêu tam mộ tứ.","examples":[{"example":"小さな違いにこだわるのは朝三暮四だ。","example_reading":"ちいさなちがいにこだわるのはちょうさんぼしだ。","example_meaning":"Câu nệ vào khác biệt nhỏ nhặt thì chỉ là triêu tam mộ tứ."},{"example":"目先の利益に惑わされて朝三暮四の結果になった。","example_reading":"めさきのりえきにまどわされてちょうさんぼしのけっかになった。","example_meaning":"Bị cái lợi trước mắt làm lóa mắt, rốt cuộc chẳng được gì hơn."}],"level":"p3"},
{"word":"画蛇添足","reading":"がだそくそく","meaning":"vẽ rắn thêm chân; làm thừa, khiến mọi việc hỏng.\n(Dùng khi thêm vào những thứ không cần thiết làm hỏng cái đã hoàn chỉnh.)","hanviet":"họa xà thiêm túc","chars":[{"c":"画","h":"họa"},{"c":"蛇","h":"xà"},{"c":"添","h":"thiêm"},{"c":"足","h":"túc"}],"example":"最後の一言は画蛇添足だった。","example_reading":"さいごのひとことはがだそくそくだった。","example_meaning":"Câu nói cuối cùng đúng là vẽ rắn thêm chân.","examples":[{"example":"最後の一言は画蛇添足だった。","example_reading":"さいごのひとことはがだそくそくだった。","example_meaning":"Câu nói cuối cùng đúng là vẽ rắn thêm chân."},{"example":"余計な説明を加えて画蛇添足になった。","example_reading":"よけいなせつめいをくわえてがだそくそくになった。","example_meaning":"Thêm lời giải thích thừa nên thành vẽ rắn thêm chân."}],"level":"p3"},
{"word":"羊頭狗肉","reading":"ようとうくにく","meaning":"treo đầu dê bán thịt chó; bề ngoài đẹp nhưng bên trong kém.\n(Dùng chê quảng cáo, sản phẩm hoặc lời nói không đúng với thực chất.)","hanviet":"dương đầu cẩu nhục","chars":[{"c":"羊","h":"dương"},{"c":"頭","h":"đầu"},{"c":"狗","h":"cẩu"},{"c":"肉","h":"nhục"}],"example":"この広告は羊頭狗肉で、中身が全然違う。","example_reading":"このこうこくはようとうくにくで、なかみがぜんぜんちがう。","example_meaning":"Quảng cáo này treo đầu dê bán thịt chó, nội dung hoàn toàn khác.","examples":[{"example":"この広告は羊頭狗肉で、中身が全然違う。","example_reading":"このこうこくはようとうくにくで、なかみがぜんぜんちがう。","example_meaning":"Quảng cáo này treo đầu dê bán thịt chó, nội dung hoàn toàn khác."},{"example":"羊頭狗肉の商品に客は怒った。","example_reading":"ようとうくにくのしょうひんにきゃくはおこった。","example_meaning":"Khách hàng tức giận vì sản phẩm treo đầu dê bán thịt chó."}],"level":"p3"},
{"word":"玉石混交","reading":"ぎょくせきこんこう","meaning":"ngọc lẫn với đá; tốt xấu lẫn lộn.\n(Dùng khi các thứ giá trị cao thấp khác nhau trộn lẫn.)","hanviet":"ngọc thạch hỗn giao","chars":[{"c":"玉","h":"ngọc"},{"c":"石","h":"thạch"},{"c":"混","h":"hỗn"},{"c":"交","h":"giao"}],"example":"ネット上の情報は玉石混交だ。","example_reading":"ねっとじょうのじょうほうはぎょくせきこんこうだ。","example_meaning":"Thông tin trên mạng thật giả lẫn lộn.","examples":[{"example":"ネット上の情報は玉石混交だ。","example_reading":"ねっとじょうのじょうほうはぎょくせきこんこうだ。","example_meaning":"Thông tin trên mạng thật giả lẫn lộn."},{"example":"応募作品は玉石混交で、選ぶのが大変だった。","example_reading":"おうぼさくひんはぎょくせきこんこうで、えらぶのがたいへんだった。","example_meaning":"Các tác phẩm dự thi tốt xấu lẫn lộn nên chọn rất vất vả."}],"level":"p3"},
{"word":"換骨奪胎","reading":"かんこつだったい","meaning":"dựa vào ý tưởng cũ, biến đổi để tạo ra cái mới.\n(Dùng cho việc mượn ý hoặc cấu trúc của tác phẩm cũ để sáng tạo cái mới.)","hanviet":"hoán cốt đoạt thai","chars":[{"c":"換","h":"hoán"},{"c":"骨","h":"cốt"},{"c":"奪","h":"đoạt"},{"c":"胎","h":"thai"}],"example":"この小説は古典を換骨奪胎した作品だ。","example_reading":"このしょうせつはこてんをかんこつだったいしたさくひんだ。","example_meaning":"Tiểu thuyết này là tác phẩm cải biên từ tác phẩm cổ điển.","examples":[{"example":"この小説は古典を換骨奪胎した作品だ。","example_reading":"このしょうせつはこてんをかんこつだったいしたさくひんだ。","example_meaning":"Tiểu thuyết này là tác phẩm cải biên từ tác phẩm cổ điển."},{"example":"彼は既存の技術を換骨奪胎して新製品を作った。","example_reading":"かれはきそんのぎじゅつをかんこつだったいしてしんせいひんをつくった。","example_meaning":"Anh ấy cải biên công nghệ có sẵn để làm ra sản phẩm mới."}],"level":"p3"},
{"word":"捲土重来","reading":"けんどちょうらい","meaning":"thất bại rồi quay lại với sức mạnh mới.\n(Dùng khi ai đó tái xuất, quyết tâm phục thù sau khi thất bại.)","hanviet":"quyển thổ trùng lai","chars":[{"c":"捲","h":"quyển"},{"c":"土","h":"thổ"},{"c":"重","h":"trùng"},{"c":"来","h":"lai"}],"example":"来年こそは捲土重来を期して頑張る。","example_reading":"らいねんこそはけんどちょうらいをきしてがんばる。","example_meaning":"Sang năm nhất định tôi sẽ cố gắng để lấy lại vị thế.","examples":[{"example":"来年こそは捲土重来を期して頑張る。","example_reading":"らいねんこそはけんどちょうらいをきしてがんばる。","example_meaning":"Sang năm nhất định tôi sẽ cố gắng để lấy lại vị thế."},{"example":"彼は捲土重来を誓って留学した。","example_reading":"かれはけんどちょうらいをちかってりゅうがくした。","example_meaning":"Anh ấy thề sẽ trở lại mạnh mẽ nên đã đi du học."}],"level":"p3"},
{"word":"艱難辛苦","reading":"かんなんしんく","meaning":"muôn vàn gian nan vất vả.\n(Dùng cho những khó khăn, thử thách lớn trong cuộc sống.)","hanviet":"gian nan tân khổ","chars":[{"c":"艱","h":"gian"},{"c":"難","h":"nan"},{"c":"辛","h":"tân"},{"c":"苦","h":"khổ"}],"example":"彼は艱難辛苦に耐えて成功を収めた。","example_reading":"かれはかんなんしんくにたえてせいこうをおさめた。","example_meaning":"Anh ấy chịu đựng muôn vàn gian khổ để đạt thành công.","examples":[{"example":"彼は艱難辛苦に耐えて成功を収めた。","example_reading":"かれはかんなんしんくにたえてせいこうをおさめた。","example_meaning":"Anh ấy chịu đựng muôn vàn gian khổ để đạt thành công."},{"example":"艱難辛苦の末、ついに夢を実現した。","example_reading":"かんなんしんくのすえ、ついにゆめをじつげんした。","example_meaning":"Sau bao gian nan vất vả, cuối cùng cũng thực hiện được ước mơ."}],"level":"p3"},
{"word":"虚虚実実","reading":"きょきょじつじつ","meaning":"hư thực lẫn lộn, dùng mưu kế đấu trí.\n(Dùng khi hai bên giở đủ chiêu thật giả để đấu trí, đấu mưu.)","hanviet":"hư hư thực thực","chars":[{"c":"虚","h":"hư"},{"c":"虚","h":"hư"},{"c":"実","h":"thực"},{"c":"実","h":"thực"}],"example":"両者は虚虚実実の駆け引きを繰り広げた。","example_reading":"りょうしゃはきょきょじつじつのかけひきをくりひろげた。","example_meaning":"Hai bên đã đấu trí hư hư thực thực.","examples":[{"example":"両者は虚虚実実の駆け引きを繰り広げた。","example_reading":"りょうしゃはきょきょじつじつのかけひきをくりひろげた。","example_meaning":"Hai bên đã đấu trí hư hư thực thực."},{"example":"交渉は虚虚実実の攻防が続いた。","example_reading":"こうしょうはきょきょじつじつのこうぼうがつづいた。","example_meaning":"Cuộc đàm phán diễn ra cuộc đấu trí giằng co hư thực khó lường."}],"level":"p3"},
{"word":"紆余曲折","reading":"うよきょくせつ","meaning":"quanh co khúc khuỷu, nhiều biến chuyển phức tạp.\n(Dùng cho quá trình đi qua nhiều trắc trở, thay đổi mới đạt kết quả.)","hanviet":"vu dư khúc chiết","chars":[{"c":"紆","h":"vu"},{"c":"余","h":"dư"},{"c":"曲","h":"khúc"},{"c":"折","h":"chiết"}],"example":"紆余曲折を経て、計画は実現した。","example_reading":"うよきょくせつをへて、けいかくはじつげんした。","example_meaning":"Sau nhiều khúc mắc quanh co, kế hoạch đã thành hiện thực.","examples":[{"example":"紆余曲折を経て、計画は実現した。","example_reading":"うよきょくせつをへて、けいかくはじつげんした。","example_meaning":"Sau nhiều khúc mắc quanh co, kế hoạch đã thành hiện thực."},{"example":"二人の関係は紆余曲折があったが、結婚した。","example_reading":"ふたりのかんけいはうよきょくせつがあったが、けっこんした。","example_meaning":"Quan hệ hai người nhiều thăng trầm nhưng rồi cũng kết hôn."}],"level":"p3"},
{"word":"曖昧模糊","reading":"あいまいもこ","meaning":"mờ nhạt, không rõ ràng.\n(Dùng cho ý kiến, ký ức hoặc ranh giới không rõ ràng.)","hanviet":"ái muội mô hồ","chars":[{"c":"曖","h":"ái"},{"c":"昧","h":"muội"},{"c":"模","h":"mô"},{"c":"糊","h":"hồ"}],"example":"彼の説明は曖昧模糊としていて、よくわからない。","example_reading":"かれのせつめいはあいまいもことしていて、よくわからない。","example_meaning":"Lời giải thích của anh ấy mơ hồ nên tôi chẳng hiểu rõ.","examples":[{"example":"彼の説明は曖昧模糊としていて、よくわからない。","example_reading":"かれのせつめいはあいまいもことしていて、よくわからない。","example_meaning":"Lời giải thích của anh ấy mơ hồ nên tôi chẳng hiểu rõ."},{"example":"曖昧模糊とした記憶しか残っていない。","example_reading":"あいまいもことしたきおくしかのこっていない。","example_meaning":"Chỉ còn lại những ký ức mờ nhạt."}],"level":"p3"},
{"word":"荒唐無稽","reading":"こうとうむけい","meaning":"hoang đường, vô căn cứ, không đáng tin.\n(Dùng cho lời nói, câu chuyện phi lý, không có cơ sở.)","hanviet":"hoang đường vô kê","chars":[{"c":"荒","h":"hoang"},{"c":"唐","h":"đường"},{"c":"無","h":"vô"},{"c":"稽","h":"kê"}],"example":"そんな荒唐無稽な話は信じられない。","example_reading":"そんなこうとうむけいなはなしはしんじられない。","example_meaning":"Câu chuyện hoang đường như vậy tôi không thể tin.","examples":[{"example":"そんな荒唐無稽な話は信じられない。","example_reading":"そんなこうとうむけいなはなしはしんじられない。","example_meaning":"Câu chuyện hoang đường như vậy tôi không thể tin."},{"example":"この映画は荒唐無稽だが、面白い。","example_reading":"このえいがはこうとうむけいだが、おもしろい。","example_meaning":"Phim này hoang đường nhưng hấp dẫn."}],"level":"p3"},
{"word":"魑魅魍魎","reading":"ちみもうりょう","meaning":"yêu ma quỷ quái; những kẻ xấu xa gian hiểm.\n(Chỉ các loài yêu quái trong núi sông, nghĩa bóng chỉ bọn người xấu xa lẩn khuất.)","hanviet":"si mị võng lưỡng","chars":[{"c":"魑","h":"si"},{"c":"魅","h":"mị"},{"c":"魍","h":"võng"},{"c":"魎","h":"lưỡng"}],"example":"政界には魑魅魍魎が跋扈している。","example_reading":"せいかいにはちみもうりょうがばっこしている。","example_meaning":"Giới chính trị đầy rẫy bọn gian hiểm hoành hành.","examples":[{"example":"政界には魑魅魍魎が跋扈している。","example_reading":"せいかいにはちみもうりょうがばっこしている。","example_meaning":"Giới chính trị đầy rẫy bọn gian hiểm hoành hành."},{"example":"古い屋敷は魑魅魍魎の住処のようだった。","example_reading":"ふるいやしきはちみもうりょうのすみかのようだった。","example_meaning":"Căn nhà cổ trông như hang ổ của yêu ma quỷ quái."}],"level":"p3"},
{"word":"天衣無縫","reading":"てんいむほう","meaning":"áo trời không đường may; tự nhiên hoàn mỹ, hồn nhiên không giả tạo.\n(Dùng khen tính cách hồn nhiên, hoặc tác phẩm hoàn hảo, không chút gượng ép.)","hanviet":"thiên y vô phùng","chars":[{"c":"天","h":"thiên"},{"c":"衣","h":"y"},{"c":"無","h":"vô"},{"c":"縫","h":"phùng"}],"example":"彼女は天衣無縫な性格で皆に愛されている。","example_reading":"かのじょはてんいむほうなせいかくでみんなにあいされている。","example_meaning":"Cô ấy có tính cách hồn nhiên, được mọi người yêu mến.","examples":[{"example":"彼女は天衣無縫な性格で皆に愛されている。","example_reading":"かのじょはてんいむほうなせいかくでみんなにあいされている。","example_meaning":"Cô ấy có tính cách hồn nhiên, được mọi người yêu mến."},{"example":"天衣無縫の演技に観客は魅了された。","example_reading":"てんいむほうのえんぎにかんきゃくはみりょうされた。","example_meaning":"Khán giả bị mê hoặc bởi diễn xuất tự nhiên hoàn mỹ."}],"level":"p3"},
{"word":"沈思黙考","reading":"ちんしもっこう","meaning":"lặng lẽ suy nghĩ sâu xa.\n(Dùng khi ai đó im lặng tập trung suy nghĩ kỹ lưỡng.)","hanviet":"trầm tư mặc khảo","chars":[{"c":"沈","h":"trầm"},{"c":"思","h":"tư"},{"c":"黙","h":"mặc"},{"c":"考","h":"khảo"}],"example":"彼は沈思黙考したのち、結論を出した。","example_reading":"かれはちんしもっこうしたのち、けつろんをだした。","example_meaning":"Anh ấy trầm ngâm suy nghĩ rồi mới đưa ra kết luận.","examples":[{"example":"彼は沈思黙考したのち、結論を出した。","example_reading":"かれはちんしもっこうしたのち、けつろんをだした。","example_meaning":"Anh ấy trầm ngâm suy nghĩ rồi mới đưa ra kết luận."},{"example":"重要な決断の前に沈思黙考の時間を持つ。","example_reading":"じゅうようなけつだんのまえにちんしもっこうのじかんをもつ。","example_meaning":"Trước quyết định quan trọng, tôi dành thời gian lặng lẽ suy ngẫm."}],"level":"p3"},
{"word":"満身創痍","reading":"まんしんそうい","meaning":"toàn thân đầy thương tích; kiệt quệ, tơi tả.\n(Dùng cho cơ thể bị thương khắp nơi hoặc tổ chức bị tổn hại nặng nề.)","hanviet":"mãn thân sang di","chars":[{"c":"満","h":"mãn"},{"c":"身","h":"thân"},{"c":"創","h":"sang"},{"c":"痍","h":"di"}],"example":"彼は満身創痍で試合に出場した。","example_reading":"かれはまんしんそういでしあいにしゅつじょうした。","example_meaning":"Anh ấy toàn thân đầy thương tích vẫn ra sân thi đấu.","examples":[{"example":"彼は満身創痍で試合に出場した。","example_reading":"かれはまんしんそういでしあいにしゅつじょうした。","example_meaning":"Anh ấy toàn thân đầy thương tích vẫn ra sân thi đấu."},{"example":"満身創痍の会社を立て直すのは難しい。","example_reading":"まんしんそういのかいしゃをたてなおすのはむずかしい。","example_meaning":"Rất khó để vực dậy một công ty đã tơi tả."}],"level":"p3"},
{"word":"優勝劣敗","reading":"ゆうしょうれっぱい","meaning":"kẻ mạnh thắng, kẻ yếu thua.\n(Dùng khi nói về quy luật cạnh tranh: người giỏi thắng, người kém bị loại.)","hanviet":"ưu thắng liệt bại","chars":[{"c":"優","h":"ưu"},{"c":"勝","h":"thắng"},{"c":"劣","h":"liệt"},{"c":"敗","h":"bại"}],"example":"市場は優勝劣敗の世界だ。","example_reading":"しじょうはゆうしょうれっぱいのせかいだ。","example_meaning":"Thị trường là thế giới kẻ mạnh thắng, kẻ yếu thua.","examples":[{"example":"市場は優勝劣敗の世界だ。","example_reading":"しじょうはゆうしょうれっぱいのせかいだ。","example_meaning":"Thị trường là thế giới kẻ mạnh thắng, kẻ yếu thua."},{"example":"優勝劣敗の競争は厳しい。","example_reading":"ゆうしょうれっぱいのきょうそうはきびしい。","example_meaning":"Cạnh tranh mạnh được yếu thua rất khắc nghiệt."}],"level":"p3"},
{"word":"栄枯盛衰","reading":"えいこせいすい","meaning":"thịnh suy, lúc hưng thịnh lúc suy tàn.\n(Dùng khi cảm thán về sự thay đổi lên xuống của con người, quốc gia, tổ chức.)","hanviet":"vinh khô thịnh suy","chars":[{"c":"栄","h":"vinh"},{"c":"枯","h":"khô"},{"c":"盛","h":"thịnh"},{"c":"衰","h":"suy"}],"example":"歴史は栄枯盛衰の繰り返しだ。","example_reading":"れきしはえいこせいすいのくりかえしだ。","example_meaning":"Lịch sử là sự lặp lại của hưng thịnh và suy vong.","examples":[{"example":"歴史は栄枯盛衰の繰り返しだ。","example_reading":"れきしはえいこせいすいのくりかえしだ。","example_meaning":"Lịch sử là sự lặp lại của hưng thịnh và suy vong."},{"example":"古い城跡を見て栄枯盛衰を感じた。","example_reading":"ふるいしろあとをみてえいこせいすいをかんじた。","example_meaning":"Nhìn tàn tích thành cổ, tôi cảm nhận sự thịnh suy của thời cuộc."}],"level":"p3"},
{"word":"盛者必衰","reading":"じょうしゃひっすい","meaning":"kẻ thịnh vượng ắt có ngày suy tàn.\n(Gốc Phật giáo, nổi tiếng trong Truyện Heike; nhắc rằng không gì tồn tại mãi.)","hanviet":"thịnh giả tất suy","chars":[{"c":"盛","h":"thịnh"},{"c":"者","h":"giả"},{"c":"必","h":"tất"},{"c":"衰","h":"suy"}],"example":"盛者必衰の理は世の常だ。","example_reading":"じょうしゃひっすいのことわりはよのつねだ。","example_meaning":"Lẽ kẻ thịnh ắt suy là quy luật thường tình của đời.","examples":[{"example":"盛者必衰の理は世の常だ。","example_reading":"じょうしゃひっすいのことわりはよのつねだ。","example_meaning":"Lẽ kẻ thịnh ắt suy là quy luật thường tình của đời."},{"example":"どんな強大な国も盛者必衰を免れない。","example_reading":"どんなきょうだいなくにもじょうしゃひっすいをまぬかれない。","example_meaning":"Dù là quốc gia hùng mạnh đến đâu cũng không tránh khỏi suy vong."}],"level":"p3"},
{"word":"諸行無常","reading":"しょぎょうむじょう","meaning":"mọi sự trên đời đều biến đổi, không có gì vĩnh cửu.\n(Giáo lý cốt lõi của Phật giáo về vô thường.)","hanviet":"chư hành vô thường","chars":[{"c":"諸","h":"chư"},{"c":"行","h":"hành"},{"c":"無","h":"vô"},{"c":"常","h":"thường"}],"example":"桜が散るのを見て、諸行無常を感じた。","example_reading":"さくらがちるのをみて、しょぎょうむじょうをかんじた。","example_meaning":"Nhìn hoa anh đào rơi, tôi cảm nhận được sự vô thường.","examples":[{"example":"桜が散るのを見て、諸行無常を感じた。","example_reading":"さくらがちるのをみて、しょぎょうむじょうをかんじた。","example_meaning":"Nhìn hoa anh đào rơi, tôi cảm nhận được sự vô thường."},{"example":"すべては変わる。これが諸行無常という考えだ。","example_reading":"すべてはかわる。これがしょぎょうむじょうというかんがえだ。","example_meaning":"Mọi thứ đều đổi thay. Đó là quan niệm chư hành vô thường."}],"level":"p3"},
{"word":"有為転変","reading":"ういてんぺん","meaning":"sự đời thay đổi không ngừng.\n(Gốc Phật giáo, chỉ sự thay đổi liên tục của mọi sự vật trên đời.)","hanviet":"hữu vi chuyển biến","chars":[{"c":"有","h":"hữu"},{"c":"為","h":"vi"},{"c":"転","h":"chuyển"},{"c":"変","h":"biến"}],"example":"有為転変は世の習いだ。","example_reading":"ういてんぺんはよのならいだ。","example_meaning":"Đời đổi thay không ngừng là lẽ thường.","examples":[{"example":"有為転変は世の習いだ。","example_reading":"ういてんぺんはよのならいだ。","example_meaning":"Đời đổi thay không ngừng là lẽ thường."},{"example":"人の世の有為転変を思い知らされた。","example_reading":"ひとのよのういてんぺんをおもいしらされた。","example_meaning":"Tôi nhận ra sâu sắc sự đổi thay của cuộc đời con người."}],"level":"p3"},
{"word":"阿鼻叫喚","reading":"あびきょうかん","meaning":"cảnh la hét kêu gào thảm thiết.\n(Từ địa ngục A Tỳ và Khiếu Hoán trong Phật giáo; chỉ cảnh hỗn loạn đau thương.)","hanviet":"a tỵ khiếu hoán","chars":[{"c":"阿","h":"a"},{"c":"鼻","h":"tỵ"},{"c":"叫","h":"khiếu"},{"c":"喚","h":"hoán"}],"example":"地震の直後、街は阿鼻叫喚の巷と化した。","example_reading":"じしんのちょくご、まちはあびきょうかんのちまたとかした。","example_meaning":"Ngay sau trận động đất, thành phố biến thành cảnh la hét thảm thiết.","examples":[{"example":"地震の直後、街は阿鼻叫喚の巷と化した。","example_reading":"じしんのちょくご、まちはあびきょうかんのちまたとかした。","example_meaning":"Ngay sau trận động đất, thành phố biến thành cảnh la hét thảm thiết."},{"example":"事故現場は阿鼻叫喚の状態だった。","example_reading":"じここうじょうはあびきょうかんのじょうたいだった。","example_meaning":"Hiện trường tai nạn tràn ngập tiếng kêu gào thảm thiết."}],"level":"p3"},
{"word":"酔生夢死","reading":"すいせいむし","meaning":"sống mơ màng, chết trong mộng; sống vô nghĩa.\n(Dùng chê cuộc sống uổng phí, không có mục đích hay thành tựu.)","hanviet":"túy sinh mộng tử","chars":[{"c":"酔","h":"túy"},{"c":"生","h":"sinh"},{"c":"夢","h":"mộng"},{"c":"死","h":"tử"}],"example":"酔生夢死の人生を送りたくない。","example_reading":"すいせいむしのじんせいをおくりたくない。","example_meaning":"Tôi không muốn sống một cuộc đời vô nghĩa.","examples":[{"example":"酔生夢死の人生を送りたくない。","example_reading":"すいせいむしのじんせいをおくりたくない。","example_meaning":"Tôi không muốn sống một cuộc đời vô nghĩa."},{"example":"目標のない日々は酔生夢死のようだ。","example_reading":"もくひょうのないひびはすいせいむしのようだ。","example_meaning":"Những ngày tháng không mục tiêu giống như sống trong mơ màng."}],"level":"p3"},
{"word":"抱腹絶倒","reading":"ほうふくぜっとう","meaning":"cười ôm bụng, cười lăn lộn.\n(Dùng khi chuyện quá buồn cười khiến người ta cười không nhịn được.)","hanviet":"bão phúc tuyệt đảo","chars":[{"c":"抱","h":"bão"},{"c":"腹","h":"phúc"},{"c":"絶","h":"tuyệt"},{"c":"倒","h":"đảo"}],"example":"落語を聞いて抱腹絶倒した。","example_reading":"らくごをきいてほうふくぜっとうした。","example_meaning":"Nghe kể chuyện rakugo, tôi cười lăn lộn.","examples":[{"example":"落語を聞いて抱腹絶倒した。","example_reading":"らくごをきいてほうふくぜっとうした。","example_meaning":"Nghe kể chuyện rakugo, tôi cười lăn lộn."},{"example":"彼の失敗談は抱腹絶倒ものだった。","example_reading":"かれのしっぱいだんはほうふくぜっとうものだった。","example_meaning":"Câu chuyện thất bại của anh ấy khiến ai cũng cười ôm bụng."}],"level":"p3"},
{"word":"傲岸不遜","reading":"ごうがんふそん","meaning":"kiêu căng ngạo mạn, không biết khiêm nhường.\n(Dùng chê người coi thường người khác, thái độ cao ngạo.)","hanviet":"ngạo ngạn bất tốn","chars":[{"c":"傲","h":"ngạo"},{"c":"岸","h":"ngạn"},{"c":"不","h":"bất"},{"c":"遜","h":"tốn"}],"example":"傲岸不遜な態度で人々の反感を買った。","example_reading":"ごうがんふそんなたいどでひとびとのはんかんをかった。","example_meaning":"Thái độ kiêu căng ngạo mạn khiến người ta phản cảm.","examples":[{"example":"傲岸不遜な態度で人々の反感を買った。","example_reading":"ごうがんふそんなたいどでひとびとのはんかんをかった。","example_meaning":"Thái độ kiêu căng ngạo mạn khiến người ta phản cảm."},{"example":"彼の傲岸不遜な振る舞いに皆が不快感を示した。","example_reading":"かれのごうがんふそんなふるまいにみんながふかいかんをしめした。","example_meaning":"Cách cư xử ngạo mạn của anh ta khiến mọi người khó chịu."}],"level":"p3"},
{"word":"右顧左眄","reading":"うこさべん","meaning":"ngó phải ngó trái, do dự vì lo ý kiến người khác.\n(Dùng chê người thiếu quyết đoán, quá để ý đến phản ứng xung quanh.)","hanviet":"hữu cố tả miện","chars":[{"c":"右","h":"hữu"},{"c":"顧","h":"cố"},{"c":"左","h":"tả"},{"c":"眄","h":"miện"}],"example":"右顧左眄していては何も決められない。","example_reading":"うこさべんしていてはなにもきめられない。","example_meaning":"Cứ ngó nghiêng do dự thì chẳng quyết định được gì.","examples":[{"example":"右顧左眄していては何も決められない。","example_reading":"うこさべんしていてはなにもきめられない。","example_meaning":"Cứ ngó nghiêng do dự thì chẳng quyết định được gì."},{"example":"彼は周囲の目を気にして右顧左眄するばかりだ。","example_reading":"かれはしゅういのめをきにしてうこさべんするばかりだ。","example_meaning":"Anh ấy cứ để ý ánh mắt xung quanh mà do dự mãi."}],"level":"p3"},
{"word":"空中楼閣","reading":"くうちゅうろうかく","meaning":"lâu đài trên không; kế hoạch viển vông, thiếu cơ sở thực tế.\n(Dùng cho ý tưởng, lý thuyết đẹp đẽ nhưng không thể thực hiện.)","hanviet":"không trung lâu các","chars":[{"c":"空","h":"không"},{"c":"中","h":"trung"},{"c":"楼","h":"lâu"},{"c":"閣","h":"các"}],"example":"資金も人もなく、その計画は空中楼閣にすぎない。","example_reading":"しきんもひともなく、そのけいかくはくうちゅうろうかくにすぎない。","example_meaning":"Không có vốn lẫn nhân lực, kế hoạch đó chỉ là lâu đài trên không.","examples":[{"example":"資金も人もなく、その計画は空中楼閣にすぎない。","example_reading":"しきんもひともなく、そのけいかくはくうちゅうろうかくにすぎない。","example_meaning":"Không có vốn lẫn nhân lực, kế hoạch đó chỉ là lâu đài trên không."},{"example":"現実を無視した空中楼閣のような理論だ。","example_reading":"げんじつをむししたくうちゅうろうかくのようなりろんだ。","example_meaning":"Đó là lý thuyết như lâu đài trên không, bỏ qua hiện thực."}],"level":"p3"},
{"word":"呆然自失","reading":"ぼうぜんじしつ","meaning":"sững sờ, thẫn thờ đến mất hồn.\n(Dùng khi quá sốc, kinh ngạc đến mức không biết làm gì.)","hanviet":"ngốc nhiên tự thất","chars":[{"c":"呆","h":"ngốc"},{"c":"然","h":"nhiên"},{"c":"自","h":"tự"},{"c":"失","h":"thất"}],"example":"合格の知らせに、彼は呆然自失した。","example_reading":"ごうかくのしらせに、かれはぼうぜんじしつした。","example_meaning":"Nghe tin đậu, anh ấy sững sờ đến thẫn thờ.","examples":[{"example":"合格の知らせに、彼は呆然自失した。","example_reading":"ごうかくのしらせに、かれはぼうぜんじしつした。","example_meaning":"Nghe tin đậu, anh ấy sững sờ đến thẫn thờ."},{"example":"事故を目撃して、しばらく呆然自失だった。","example_reading":"じこをもくげきして、しばらくぼうぜんじしつだった。","example_meaning":"Chứng kiến vụ tai nạn, tôi sững sờ một lúc lâu."}],"level":"p3"},
{"word":"千変万化","reading":"せんぺんばんか","meaning":"biến hóa muôn hình vạn trạng.\n(Dùng cho sự vật thay đổi liên tục, không ngừng.)","hanviet":"thiên biến vạn hóa","chars":[{"c":"千","h":"thiên"},{"c":"変","h":"biến"},{"c":"万","h":"vạn"},{"c":"化","h":"hóa"}],"example":"山の天気は千変万化する。","example_reading":"やまのてんきはせんぺんばんかする。","example_meaning":"Thời tiết trên núi thay đổi muôn hình vạn trạng.","examples":[{"example":"山の天気は千変万化する。","example_reading":"やまのてんきはせんぺんばんかする。","example_meaning":"Thời tiết trên núi thay đổi muôn hình vạn trạng."},{"example":"このゲームは千変万化の展開が楽しい。","example_reading":"このげーむはせんぺんばんかのてんかいがたのしい。","example_meaning":"Điểm thú vị của trò chơi này là diễn biến biến hóa khôn lường."}],"level":"p3"},
{"word":"徹頭徹尾","reading":"てっとうてつび","meaning":"từ đầu đến cuối, nhất quán đến cùng.\n(Dùng khi giữ vững một thái độ, lập trường xuyên suốt.)","hanviet":"triệt đầu triệt vĩ","chars":[{"c":"徹","h":"triệt"},{"c":"頭","h":"đầu"},{"c":"徹","h":"triệt"},{"c":"尾","h":"vĩ"}],"example":"彼は徹頭徹尾、反対の立場を貫いた。","example_reading":"かれはてっとうてつび、はんたいのたちばをつらぬいた。","example_meaning":"Anh ấy kiên trì lập trường phản đối từ đầu đến cuối.","examples":[{"example":"彼は徹頭徹尾、反対の立場を貫いた。","example_reading":"かれはてっとうてつび、はんたいのたちばをつらぬいた。","example_meaning":"Anh ấy kiên trì lập trường phản đối từ đầu đến cuối."},{"example":"徹頭徹尾、誠実に対応するつもりだ。","example_reading":"てっとうてつび、せいじつにたいおうするつもりだ。","example_meaning":"Tôi định ứng xử chân thành từ đầu đến cuối."}],"level":"p3"},
{"word":"心頭滅却","reading":"しんとうめっきゃく","meaning":"dẹp bỏ tạp niệm trong lòng.\n(Trong câu 心頭を滅却すれば火もまた涼し: gạt bỏ tạp niệm thì lửa cũng mát.)","hanviet":"tâm đầu diệt khước","chars":[{"c":"心","h":"tâm"},{"c":"頭","h":"đầu"},{"c":"滅","h":"diệt"},{"c":"却","h":"khước"}],"example":"心頭滅却すれば火もまた涼しという言葉がある。","example_reading":"しんとうめっきゃくすればひもまたすずしいということばがある。","example_meaning":"Có câu rằng dẹp hết tạp niệm thì lửa cũng thấy mát.","examples":[{"example":"心頭滅却すれば火もまた涼しという言葉がある。","example_reading":"しんとうめっきゃくすればひもまたすずしいということばがある。","example_meaning":"Có câu rằng dẹp hết tạp niệm thì lửa cũng thấy mát."},{"example":"試験前は心頭滅却して勉強に集中した。","example_reading":"しけんまえはしんとうめっきゃくしてべんきょうにしゅうちゅうした。","example_meaning":"Trước kỳ thi, tôi gạt bỏ tạp niệm để tập trung học."}],"level":"p3"}
],
"grammar": []
};
